window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s15-59","number":59,"surah":15,"verses":[23],"references":[{"surah":15,"verses":[23]}],"verseLabel":"الحجر: 23","question":"ما سرّ حذف مفعولي ﴿نُحْيِي وَنُمِيتُ﴾؟","answer":"ترك المفعول يوجه العناية إلى أصل الفعلين واختصاص الله بهما، لا إلى إحياء أشخاص معينين أو إماتتهم؛ فالمقصود إثبات القدرة والتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص394، تحت «سبب حذف المفعول في نحيي ونميت»","url":""}]},{"id":"s15-60","number":60,"surah":15,"verses":[24],"references":[{"surah":15,"verses":[24]}],"verseLabel":"الحجر: 24","question":"ما فائدة تكرار ﴿ولقد علمنا﴾ مع المستقدمين والمستأخرين؟","answer":"يؤكد التكرار إحاطة علم الله بكل من مضى ومن لم يأت بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص400، تحت «فائدة التكرار في ولقد علمنا»","url":""}]},{"id":"s15-172","number":172,"surah":15,"verses":[24],"references":[{"surah":15,"verses":[24]}],"verseLabel":"الحجر: 24","question":"ما فائدة التعريف في ﴿المستقدمين﴾ و﴿المستأخرين﴾؟","answer":"يفيد استغراق جميع المتقدمين والمتأخرين في الوجود والأعمال، فلا يخرج أحد عن علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص401، تحت «فائدة التعريف بال في الآية»","url":""}]},{"id":"s15-61","number":61,"surah":15,"verses":[25],"references":[{"surah":15,"verses":[25]}],"verseLabel":"الحجر: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ﴾؟","answer":"«إنّ» تؤكد وقوع الحشر، وتقوية إسناده في ﴿هُوَ يَحْشُرُهُمْ﴾ تفيد اختصاص الله به؛ فهو وحده يجمعهم ويعيدهم، مهما كثروا وتفرقت أجزاؤهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص405، تحت «دلالة الحصر»","url":""}]},{"id":"s15-62","number":62,"surah":15,"verses":[25],"references":[{"surah":15,"verses":[25]}],"verseLabel":"الحجر: 25","question":"ما سرّ تقديم ﴿حَكِيمٌ﴾ على ﴿عَلِيمٌ﴾؟","answer":"قُدّمت الحكمة لأن الحشر والجزاء مما تقتضيه الحكمة؛ ثم جاء العلم لإفادة إحاطته بمن يحشرهم وأعمالهم، فيكون الجزاء على علم تام.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص407، تحت «نكتة الترتيب في حكيم عليم»","url":""}]},{"id":"s15-63","number":63,"surah":15,"verses":[26,27],"references":[{"surah":15,"verses":[26,27]}],"verseLabel":"الحجر: 26-27","question":"ما دلالة ذكر أصل الإنسان ثم أصل الجان في هذا السياق؟","answer":"يبين اختلاف أصلي الإنسان والجان كمال القدرة على تنويع الخلق مع وحدة الخالق، ويمهد لذكر ما جرى بين آدم وإبليس من عداوة؛ فلا يكون اختلاف المادة حجة للاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص415، تحت «بلاغة العطف في الآية»","url":""}]},{"id":"s15-64","number":64,"surah":15,"verses":[29],"references":[{"surah":15,"verses":[29]}],"verseLabel":"الحجر: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿فَقَعُوا لَهُ سَاجِدِينَ﴾ لا اسجدوا فقط؟","answer":"يصوّر الفعل مبادرتهم إلى السجود وسهولة انقيادهم للأمر، حتى كأنهم هووا إليه من غير تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص427، تحت «نكتة التعبير بقوله فقعوا»","url":""}]},{"id":"s15-65","number":65,"surah":15,"verses":[30],"references":[{"surah":15,"verses":[30]}],"verseLabel":"الحجر: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿فَسَجَدَ الْمَلَائِكَةُ كُلُّهُمْ أَجْمَعُونَ﴾ وجمع مؤكدين؟","answer":"«كلهم» تؤكد شمول السجود لجميع الملائكة. و«أجمعون» تزيد التأكيد، وقيل: تفيد أيضًا اجتماعهم فيه دون تخلف؛ والفاء تُشعر بالمبادرة إلى الامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص431، تحت «سر اقتران أجمعون بكلهم»","url":""}]},{"id":"s15-66","number":66,"surah":15,"verses":[32],"references":[{"surah":15,"verses":[32]}],"verseLabel":"الحجر: 32","question":"لماذا جاء الاستفهام: ﴿مَا لَكَ أَلَّا تَكُونَ مَعَ السَّاجِدِينَ﴾؟","answer":"الاستفهام للإنكار والتوبيخ، لا لطلب علم؛ فينفي أن يكون له عذر في الامتناع، ويستخرج ما أضمره من استكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص436، تحت «بلاغة الاستفهام المجازي في الآية»","url":""}]},{"id":"s15-67","number":67,"surah":15,"verses":[33],"references":[{"surah":15,"verses":[33]}],"verseLabel":"الحجر: 33","question":"ما سرّ التعبير في قول إبليس: ﴿لَمْ أَكُنْ لِأَسْجُدَ﴾؟","answer":"لام الجحود تؤكد نفي السجود؛ فكأنه يزعم أن السجود لآدم لا يليق به ولا يمكن أن يصدر منه، وفي ذلك كشف لاستكباره.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص441، 442، تحت «فائدة اللام في قوله لأسجد»","url":""}]},{"id":"s15-68","number":68,"surah":15,"verses":[34],"references":[{"surah":15,"verses":[34]}],"verseLabel":"الحجر: 34","question":"ما دلالة الفاء في ﴿فَاخْرُجْ مِنْهَا﴾؟","answer":"رتبت الفاء الأمر بالخروج على ما أظهره إبليس من عصيان واستكبار؛ فصار الطرد جزاءً لذلك القول والموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص446، تحت «فائدة الفاء في قوله فاخرج منها»","url":""}]},{"id":"s15-69","number":69,"surah":15,"verses":[34],"references":[{"surah":15,"verses":[34]}],"verseLabel":"الحجر: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿رَجِيمٌ﴾ لا مطرود؟","answer":"«رجيم» بمعنى مرجوم، وهو كناية عن طرد مقرون بالتحقير والإهانة، فيبلغ في تصوير إبعاده مبلغًا لا يؤديه مجرد لفظ الطرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص448، تحت «بلاغة الكناية في قوله رجيم»","url":""}]},{"id":"s15-70","number":70,"surah":15,"verses":[35],"references":[{"surah":15,"verses":[35]}],"verseLabel":"الحجر: 35","question":"ما سرّ تقديم ﴿عَلَيْكَ﴾ في ﴿وَإِنَّ عَلَيْكَ اللَّعْنَةَ﴾؟","answer":"يفيد التقديم تخصيصه بهذه اللعنة وتأكيد وقوعها عليه؛ فيشتد بيان إبعاده جزاء عصيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص451، تحت «بلاغة تقديم عليك»","url":""}]},{"id":"s15-71","number":71,"surah":15,"verses":[36],"references":[{"surah":15,"verses":[36]}],"verseLabel":"الحجر: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَى يَوْمِ يُبْعَثُونَ﴾؟","answer":"طلب إبليس التأخير إلى يوم البعث طمعًا في أن يفلت من الموت، وأن يتسع له زمن إغواء بني آدم؛ فجاء تحديده كاشفًا لغرضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص458، تحت «مناسبة تحديد الإنظار في الآية»","url":""}]},{"id":"s15-72","number":72,"surah":15,"verses":[37,38],"references":[{"surah":15,"verses":[37,38]}],"verseLabel":"الحجر: 37-38","question":"ما سرّ التعبير بقوله تعالى: ﴿مِنَ الْمُنْظَرِينَ إِلَى يَوْمِ الْوَقْتِ الْمَعْلُومِ﴾؟","answer":"لم يترك إنظاره مطلقًا؛ بل قُيّد بأجل معلوم عند الله. ومن تفسيراته وقت النفخة الأولى، لا يوم البعث الذي طلبه، فلا يخرج إبليس عن الموت والقضاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص461، تحت «دلالة تقييد الإنظار في الآية»","url":""}]},{"id":"s15-73","number":73,"surah":15,"verses":[39],"references":[{"surah":15,"verses":[39]}],"verseLabel":"الحجر: 39","question":"ما سرّ التعبير في قول إبليس: ﴿بِمَا أَغْوَيْتَنِي﴾؟","answer":"التعبير بالإغواء يشعر بانغماس إبليس في الباطل وفساده فسادًا لا يُرجى معه صلاحه؛ وفيه تنبيه لبني آدم من وسوسته، إذ لا يرى سوى الباطل ولا يأمر إلا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص468، تحت «نكتة التعبير بلفظ أغويتني»","url":""}]},{"id":"s15-74","number":74,"surah":15,"verses":[39],"references":[{"surah":15,"verses":[39]}],"verseLabel":"الحجر: 39","question":"ما بلاغة حذف مفعول ﴿لأزينن﴾؟","answer":"يعم الحذف كل ما يزينه إبليس لبني آدم من الباطل والمعاصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص469، تحت «بلاغة حذف مفعول لأزينن»","url":""}]},{"id":"s15-173","number":173,"surah":15,"verses":[39],"references":[{"surah":15,"verses":[39]}],"verseLabel":"الحجر: 39","question":"ما دلالة قوله تعالى: ﴿في الأرض﴾؟","answer":"يقيد تزيين إبليس بزمن وجود بني آدم في الدنيا، دار متاعهم وابتلائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص469، تحت «دلالة الحال في قوله في الأرض»","url":""}]},{"id":"s15-75","number":75,"surah":15,"verses":[39],"references":[{"surah":15,"verses":[39]}],"verseLabel":"الحجر: 39","question":"ما سرّ إسناد الإغواء إلى إبليس في قوله: ﴿وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ﴾؟","answer":"الإسناد مجاز عقلي؛ أي لأحملنهم على الغواية وأتسبب فيها، وفيه تصوير شدة حرص إبليس واجتهاده في إضلال بني آدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص470، تحت «بلاغة المجاز في قوله ولأغوينهم»","url":""}]},{"id":"s15-76","number":76,"surah":15,"verses":[40],"references":[{"surah":15,"verses":[40]},{"surah":38,"verses":[83]}],"verseLabel":"الحجر: 40؛ ص: 83","question":"ما دلالة استثناء ﴿عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ﴾ في الحجر وص؟","answer":"في الحجر: 40، استثنى من اختصهم الله بطاعته وحفظهم، إقرارًا بعجزه عن إغوائهم.\n\nوفي ص: 83، جاء الاستثناء احترازًا من كذب دعواه بإغواء الجميع؛ فالمخلَصون مصونون بعناية الله، وعلى قراءة كسر اللام هم الذين أخلصوا له دينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص474، تحت «نكتة التعبير بلفظ المخلصين»","url":""}]},{"id":"s15-77","number":77,"surah":15,"verses":[40],"references":[{"surah":15,"verses":[40]}],"verseLabel":"الحجر: 40","question":"ما سرّ تقديم ﴿مِنْهُمُ﴾ على ﴿الْمُخْلَصِينَ﴾؟","answer":"تقديم «منهم» يُبرز أن المخلصين من البشر الذين استهدفهم إبليس، وأن نجاتهم لخصوص إخلاصهم لله؛ وفي ذلك مزية لهم على سائر من يتبع إغواءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص473، 474، تحت «بلاغة تقديم منهم في الآية»","url":""}]},{"id":"s15-78","number":78,"surah":15,"verses":[41],"references":[{"surah":15,"verses":[41]}],"verseLabel":"الحجر: 41","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿هذا صراط علي﴾؟","answer":"شُبّه الوعد بصيانة المخلصين بطريق ثابت، و﴿علي﴾ تفيد التزام هذا الوعد تفضلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص476، تحت «بلاغة الاستعارة في قوله هذا صراط علي»","url":""}]},{"id":"s15-174","number":174,"surah":15,"verses":[41],"references":[{"surah":15,"verses":[41]}],"verseLabel":"الحجر: 41","question":"ما فائدة وصف الصراط بأنه ﴿مستقيم﴾؟","answer":"يؤكد سلامته من الانحراف وثباته؛ فلا يستطيع إبليس صرف المخلصين عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص478، تحت «فائدة مجيء الصفة في قوله مستقيم»","url":""}]},{"id":"s15-79","number":79,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما فائدة إضافة العباد إلى الله في قوله: ﴿إن عبادي﴾؟","answer":"الإضافة تشريف لهم وإظهار لعناية الله وحفظه إياهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص483، تحت «فائدة الإضافة في قوله عبادي»","url":""}]},{"id":"s15-175","number":175,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما نكتة التعبير بلفظ ﴿سلطان﴾؟","answer":"ينفي عن إبليس الحجة والقهر؛ فلا يملك إجبارهم على العصيان وإنما يدعو ويزين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص484، تحت «نكتة التعبير بلفظ سلطان»","url":""}]},{"id":"s15-80","number":80,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما فائدة تقديم ﴿لك﴾ في قوله تعالى: ﴿ليس لك عليهم سلطان﴾؟","answer":"يؤكد نفي السلطان عن إبليس خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص483، تحت «فائدة تقديم لك»","url":""}]},{"id":"s15-176","number":176,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما فائدة تقديم ﴿عليهم﴾ على ﴿سلطان﴾؟","answer":"يخص عباد الله بهذا النفي، فتقوى دلالة الحماية والاختصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص483، تحت «فائدة تقديم عليهم على سلطان»","url":""}]},{"id":"s15-81","number":81,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا مَنِ اتَّبَعَكَ﴾ لا من أغويته؟","answer":"يظهر أن تسلطه عليهم ناشئ عن اتباعهم له باختيارهم، لا عن قهر يلجئهم إليه؛ فوسوسته لا تعفيهم من مسؤولية الاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص487، تحت «نكتة التعبير بلفظ اتبعك»","url":""}]},{"id":"s15-82","number":82,"surah":15,"verses":[43],"references":[{"surah":15,"verses":[43]}],"verseLabel":"الحجر: 43","question":"ما دلالة تسمية جهنم ﴿مَوْعِدَهُمْ﴾؟","answer":"سُمّيت جهنم موعدهم تهكمًا وتهديدًا، كأنهم بتتابعهم على الغواية قد تواعدوا على الاجتماع فيها؛ فصارت مكان لقائهم ومصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص491، تحت «نكتة التعبير بلفظ لموعدهم»","url":""}]},{"id":"s15-83","number":83,"surah":15,"verses":[44],"references":[{"surah":15,"verses":[44]}],"verseLabel":"الحجر: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿لَهَا سَبْعَةُ أَبْوَابٍ﴾؟","answer":"تعدد الأبواب يُشعر بكثرة الداخلين وتنوع مراتبهم في الغواية والعذاب؛ ولكل باب جماعة مخصوصة. وقيل: الأبواب كناية عن طبقاتها ودركاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص495، تحت «سر التعبير بقوله لها سبعة أبواب»","url":""}]},{"id":"s15-84","number":84,"surah":15,"verses":[44],"references":[{"surah":15,"verses":[44]}],"verseLabel":"الحجر: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿لِكُلِّ بَابٍ مِنْهُمْ جُزْءٌ مَقْسُومٌ﴾؟","answer":"لكل باب جماعة متميزة من الغاوين، تجمعها حالها في الغواية وما تستحقه من العقاب؛ فالقسمة تُظهر اختلاف مراتب العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص497، 498، تحت «نكتة التعبير بقوله جزء مقسوم»","url":""}]},{"id":"s15-85","number":85,"surah":15,"verses":[45],"references":[{"surah":15,"verses":[45]}],"verseLabel":"الحجر: 45","question":"ما دلالة حذف متعلّق ﴿الْمُتَّقِينَ﴾؟","answer":"حذف المتعلق يعم ما ينبغي اتقاؤه من الشرك والفواحش وغواية الشيطان؛ فلا يحصر التقوى في اجتناب شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص500، تحت «براعة حذف متعلق المتقين»","url":""}]},{"id":"s15-86","number":86,"surah":15,"verses":[45],"references":[{"surah":15,"verses":[45]}],"verseLabel":"الحجر: 45","question":"ما دلالة جمع ﴿جنات وعيون﴾؟","answer":"يشعر الجمع بكثرة الجنات والعيون وتنوع النعيم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص502، تحت «فائدة الجمع في قوله جنات وعيون»","url":""}]},{"id":"s15-177","number":177,"surah":15,"verses":[45],"references":[{"surah":15,"verses":[45]}],"verseLabel":"الحجر: 45","question":"ما دلالة تنكير ﴿جنات وعيون﴾؟","answer":"يعظم شأنها؛ فهي جنات وعيون لا يشبه نعيمها ما عرفه الناس في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص502، تحت «فائدة التنكير في قوله جنات وعيون»","url":""}]},{"id":"s15-87","number":87,"surah":15,"verses":[46],"references":[{"surah":15,"verses":[46]}],"verseLabel":"الحجر: 46","question":"ما دلالة قوله تعالى: ﴿بسلام﴾؟","answer":"يفيد الدخول مصحوبًا بالسلامة من الآفات والمنغصات.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص506، تحت «دلالة الحال في قوله بسلام»","url":""}]},{"id":"s15-178","number":178,"surah":15,"verses":[46],"references":[{"surah":15,"verses":[46]}],"verseLabel":"الحجر: 46","question":"ما بلاغة التعبير بلفظ ﴿آمنين﴾؟","answer":"يفيد الأمن من الخروج وزوال النعيم، فيطمئنون إلى دوام بقائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص506، تحت «براعة التعبير بلفظ آمنين»","url":""}]},{"id":"s15-88","number":88,"surah":15,"verses":[47],"references":[{"surah":15,"verses":[47]}],"verseLabel":"الحجر: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنَزَعْنَا مَا فِي صُدُورِهِمْ مِنْ غِلٍّ﴾؟","answer":"نُسب النزع إلى الله لإفادة سهولته بقدرته؛ فيُزال الغل من صدور المؤمنين من غير مشقة عليهم، وتصفو نفوسهم من الضغائن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص511، تحت «نكتة التعبير بلفظ ونزعنا»","url":""}]},{"id":"s15-89","number":89,"surah":15,"verses":[47],"references":[{"surah":15,"verses":[47]}],"verseLabel":"الحجر: 47","question":"ما سرّ زيادة ﴿إِخْوَانًا﴾ بعد نزع الغل في الحجر، دون نظيرها في الأعراف؟","answer":"في الحجر يُفصّل السياق أحوال اجتماع أهل الجنة ودوام صفائهم، فناسب ذكر أخوتهم بعد نزع الغل. أما الأعراف فيذكر نعيمهم وشكرهم عند دخول الجنة دون هذا التفصيل لأحوال اجتماعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص515، 516، تحت «توجيه المتشابه اللفظي في الآية»","url":""}]},{"id":"s15-90","number":90,"surah":15,"verses":[47],"references":[{"surah":15,"verses":[47]}],"verseLabel":"الحجر: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَى سُرُرٍ مُتَقَابِلِينَ﴾؟","answer":"التقابل يصور صفاء اجتماعهم وأنس بعضهم ببعض؛ فلا استدبار ولا تقاطع، بل وجوه متواجهة وقلوب متصافية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص515، تحت «نكتة التعبير بلفظ متقابلين»","url":""}]},{"id":"s15-91","number":91,"surah":15,"verses":[48],"references":[{"surah":15,"verses":[48]}],"verseLabel":"الحجر: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَمَسُّهُمْ فِيهَا نَصَبٌ﴾؟","answer":"المس أدنى الإصابة، فنفيه يدل على انتفاء أقل تعب عنهم، فضلًا عما فوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص520، تحت «بلاغة الكناية في قوله لا يمسهم»","url":""}]},{"id":"s15-92","number":92,"surah":15,"verses":[48],"references":[{"surah":15,"verses":[48]}],"verseLabel":"الحجر: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا هُمْ مِنْهَا بِمُخْرَجِينَ﴾ لا «خالدون» فقط؟","answer":"نفي الإخراج ينفي كل احتمال لانقطاع النعيم، والبناء للمفعول يشعر بأن أحدًا لا يستطيع إخراجهم؛ فيتم أمنهم وخلودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص522، تحت «نكتة الإخبار بقوله بمخرجين»","url":""}]},{"id":"s15-93","number":93,"surah":15,"verses":[49],"references":[{"surah":15,"verses":[49]}],"verseLabel":"الحجر: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿نَبِّئْ عِبَادِي﴾ لا أخبرهم؟","answer":"النبأ خبر عظيم الفائدة والشأن، وصيغة التفعيل تزيد تأكيده وتقريره؛ فيُطلب تلقي خبر المغفرة والرحمة بعناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص526، تحت «سبب إيثار التعبير بلفظ نبئ»","url":""}]},{"id":"s15-94","number":94,"surah":15,"verses":[49],"references":[{"surah":15,"verses":[49]}],"verseLabel":"الحجر: 49","question":"ما دلالة إضافة العباد إلى الله في ﴿نَبِّئْ عِبَادِي﴾؟","answer":"إضافتهم إلى الله تشرفهم وترفع شأنهم، وتمهد لتلقي بشارة مغفرته ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص527، تحت «فائدة الإضافة في قوله عبادي»","url":""}]},{"id":"s15-95","number":95,"surah":15,"verses":[49],"references":[{"surah":15,"verses":[49]}],"verseLabel":"الحجر: 49","question":"ما دلالة الجمع بين ﴿الْغَفُورُ الرَّحِيمُ﴾؟","answer":"المغفرة ستر الذنب، والرحمة أوسع وتشمل العناية بعباده؛ والإنسان لا ينفك عن الحاجة إليهما، فجمع الوصفان البشارة بستر تقصيره وإحسان الله إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص529، تحت «بلاغة ذكر الوصفين الغفور الرحيم»","url":""}]},{"id":"s15-96","number":96,"surah":15,"verses":[50],"references":[{"surah":15,"verses":[50]}],"verseLabel":"الحجر: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الْأَلِيمُ﴾؟","answer":"الضمير وتعريف «العذاب» يؤكدان اختصاص عذابه بكمال الإيلام؛ فيقترن الوعد بالمغفرة والرحمة بالتحذير من العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص531، تحت «فائدة الضمير هو»","url":""}]},{"id":"s15-97","number":97,"surah":15,"verses":[51],"references":[{"surah":15,"verses":[51]}],"verseLabel":"الحجر: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنَبِّئْهُمْ عَنْ ضَيْفِ إِبْرَاهِيمَ﴾؟","answer":"وصلت القصة بخبر المغفرة والعذاب لأنها تُري أثرهما: بشارة إبراهيم ونجاة لوط، ثم هلاك المكذبين؛ فيجتمع الاعتبار بالوعد والوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص535، تحت «فائدة الوصل بالواو في قوله ونبئهم»","url":""}]},{"id":"s15-98","number":98,"surah":15,"verses":[51],"references":[{"surah":15,"verses":[51]}],"verseLabel":"الحجر: 51","question":"ما سرّ إفراد ﴿ضَيْفِ﴾ مع أن ضيوف إبراهيم جماعة؟","answer":"«ضيف» اسم جنس يستوي فيه القليل والكثير، فجاء مفردًا مع أنهم جماعة؛ وحق الضيافة يثبت للجمع وللفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص537، تحت «فائدة اسم الجنس الإفرادي الضيف»","url":""}]},{"id":"s15-99","number":99,"surah":15,"verses":[52],"references":[{"surah":15,"verses":[52]}],"verseLabel":"الحجر: 52","question":"ما سرّ التعبير في قول إبراهيم: ﴿إِنَّا مِنْكُمْ وَجِلُونَ﴾؟","answer":"الوجل خوف واضطراب في النفس من أمر تتوقعه؛ فاختير اللفظ لتصوير ما استشعره إبراهيم من ضيوفه حين لم يتناولوا الطعام، كما تفصله نظائر القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص542، تحت «نكتة التعبير بلفظ وجلون»","url":""}]},{"id":"s15-100","number":100,"surah":15,"verses":[53],"references":[{"surah":15,"verses":[53]}],"verseLabel":"الحجر: 53","question":"ما سرّ التعبير في قول الملائكة: ﴿لَا تَوْجَلْ﴾ مع حذف سبب الوجل؟","answer":"حذف المتعلق يعم النهي عن الخوف من أي شيء، فيتم تسكين قلبه قبل البشارة؛ وليس المقصود نفي سبب واحد للوجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص549، تحت «سر حذف متعلق الفعل لا توجل»","url":""}]},{"id":"s15-101","number":101,"surah":15,"verses":[54],"references":[{"surah":15,"verses":[54]}],"verseLabel":"الحجر: 54","question":"ما سرّ التعبير في قول إبراهيم: ﴿مَسَّنِيَ الْكِبَرُ﴾؟","answer":"صوّر الكبر كأنه شيء يمس الإنسان بأذاه، دلالة على ظهور أثره في القوة والحركة. وذكره إبراهيم تعجبًا من مجيء الولد بعد انقطاع أسبابه المعتادة، لا شكًا في قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص559، تحت «نكتة التعبير بلفظ مسني»","url":""}]},{"id":"s15-102","number":102,"surah":15,"verses":[56],"references":[{"surah":15,"verses":[56]}],"verseLabel":"الحجر: 56","question":"ما بلاغة الاستفهام في قوله تعالى: ﴿ومن يقنط من رحمة ربه﴾؟","answer":"هو استفهام إنكاري ينفي القنوط عن العارف بربه ويحصره في الضالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص571، تحت «بلاغة الاستفهام المجازي في الآية الكريمة»","url":""}]},{"id":"s15-179","number":179,"surah":15,"verses":[56],"references":[{"surah":15,"verses":[56]}],"verseLabel":"الحجر: 56","question":"لماذا قيل: ﴿من رحمة ربه﴾ لا من رحمة الله؟","answer":"إضافة الرحمة إلى الرب تستحضر عنايته وتربيته وإحسانه، فتقوي الرجاء فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص572، تحت «سبب إيثار التعبير بلفظ ربه»","url":""}]},{"id":"s15-103","number":103,"surah":15,"verses":[57],"references":[{"surah":15,"verses":[57]}],"verseLabel":"الحجر: 57","question":"ما نكتة التعبير بلفظ ﴿خطبكم﴾؟","answer":"الخطب شأن عظيم، فدل على أن إبراهيم أدرك أن وراء البشارة مهمة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص577، تحت «نكتة التعبير بلفظ خطبكم»","url":""}]},{"id":"s15-180","number":180,"surah":15,"verses":[57],"references":[{"surah":15,"verses":[57]}],"verseLabel":"الحجر: 57","question":"ما سرّ حذف حرف النداء في قوله: ﴿أيها المرسلون﴾؟","answer":"حذفت ﴿يا﴾ لقربهم وحضورهم، ولأن المقام مقام إيجاز ومباشرة في السؤال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص578، تحت «سر حذف حرف النداء في السياق»","url":""}]},{"id":"s15-104","number":104,"surah":15,"verses":[59],"references":[{"surah":15,"verses":[59]}],"verseLabel":"الحجر: 59","question":"ما دلالة استثناء ﴿آل لوط﴾ من القوم المجرمين؟","answer":"أخرج الاستثناء آل لوط المؤمنين من حكم الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص584، تحت «دلالة الاستثناء في قوله إلا آل لوط»","url":""}]},{"id":"s15-181","number":181,"surah":15,"verses":[59],"references":[{"surah":15,"verses":[59]}],"verseLabel":"الحجر: 59","question":"ما بلاغة قوله تعالى: ﴿إنا لمنجوهم أجمعين﴾؟","answer":"أكدت الجملة شمول النجاة لجميع آل لوط بعد استثنائهم من القوم المجرمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص584، تحت «بلاغة جملة الاستئناف في الآية»","url":""}]},{"id":"s15-105","number":105,"surah":15,"verses":[60],"references":[{"surah":15,"verses":[60]}],"verseLabel":"الحجر: 60","question":"ما نكتة التعبير عن امرأة لوط بأنها ﴿من الغابرين﴾؟","answer":"الغابرون الباقون؛ فهي باقية مع المجرمين للهلاك لا للنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص588، تحت «نكتة التعبير بقوله لمن الغابرين»","url":""}]},{"id":"s15-182","number":182,"surah":15,"verses":[60],"references":[{"surah":15,"verses":[60]}],"verseLabel":"الحجر: 60","question":"ما فائدة حذف متعلق ﴿الغابرين﴾؟","answer":"يجمع الحذف بقاءها مع المجرمين وتخلفها عن الخروج مع لوط.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص589، تحت «فائدة حذف متعلق الغابرين»","url":""}]},{"id":"s15-106","number":106,"surah":15,"verses":[61,62,63],"references":[{"surah":15,"verses":[61,62,63]}],"verseLabel":"الحجر: 61-63","question":"ما فائدة ﴿بل﴾ في قول الملائكة: ﴿بل جئناك﴾؟","answer":"أبطلت موجب خوف لوط ونقلت الكلام إلى حقيقة مجيئهم بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص600، تحت «فائدة التعبير ببل»","url":""}]},{"id":"s15-183","number":183,"surah":15,"verses":[61,62,63],"references":[{"surah":15,"verses":[61,62,63]}],"verseLabel":"الحجر: 61-63","question":"ما نكتة التعبير بـ﴿يمترون﴾؟","answer":"يشعر اللفظ بتكلف طلب الشك بعد ظهور الدليل، فيكشف عناد قوم لوط.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص603، تحت «نكتة التعبير بلفظ يمترون»","url":""}]},{"id":"s15-107","number":107,"surah":15,"verses":[63],"references":[{"surah":15,"verses":[63]}],"verseLabel":"الحجر: 63","question":"ما سرّ تقديم ﴿فِيهِ﴾ على ﴿يَمْتَرُونَ﴾؟","answer":"التقديم يؤكد تعلق امترائهم بالعذاب الموعود، ويبرز عظم ما شكوا فيه، مع مراعاة الفاصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص602، تحت «بلاغة تقديم فيه على يمترون»","url":""}]},{"id":"s15-108","number":108,"surah":15,"verses":[65],"references":[{"surah":15,"verses":[65]}],"verseLabel":"الحجر: 65","question":"ما سرّ حذف متعلَّق ﴿تُؤْمَرُونَ﴾ في قوله تعالى: ﴿وَامْضُوا حَيْثُ تُؤْمَرُونَ﴾؟","answer":"التقدير: «حيث تؤمرون بالمضي إليه» أو «تؤمرون به»؛ وحذف المتعلَّق يفيد اتصافهم بالائتمار والامتثال لأي أمر يأتيهم من الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص615، 616، تحت «بلاغة الحذف في قوله تؤمرون»","url":""}]},{"id":"s15-109","number":109,"surah":15,"verses":[66],"references":[{"surah":15,"verses":[66]}],"verseLabel":"الحجر: 66","question":"ما سرّ تقديم ﴿إِلَيْهِ﴾ في قوله تعالى: ﴿وَقَضَيْنَا إِلَيْهِ ذَلِكَ الْأَمْرَ﴾؟","answer":"تقديم الجار والمجرور يفيد تخصيص لوط عليه السلام بإخباره باستئصال قومه، اهتمامًا بشأنه ورعايةً لحق الرسالة، وليتهيأ هو وأتباعه للخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص621، تحت «بلاغة تقديم إليه على ذلك الأمر»","url":""}]},{"id":"s15-110","number":110,"surah":15,"verses":[66],"references":[{"surah":15,"verses":[66]}],"verseLabel":"الحجر: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿مَقْطُوعٌ﴾ لا هالك؟","answer":"قطع الدابر كناية عن استئصال القوم حتى لا يبقى أحد يتبعهم؛ و«مقطوع» تعرض هذا الاستئصال كأمر محقق الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص623، تحت «نكتة التعبير بصيغة مقطوع»","url":""}]},{"id":"s15-111","number":111,"surah":15,"verses":[68],"references":[{"surah":15,"verses":[68]}],"verseLabel":"الحجر: 68","question":"ما سرّ التعبير في قول لوط: ﴿إِنَّ هَؤُلَاءِ ضَيْفِي﴾ باسم الإشارة؟","answer":"الإشارة إلى الضيوف القريبين تُظهر عناية لوط بهم، وتعرّفهم لقومه تعريفًا يستدعي إكرامهم وصيانتهم؛ فهم حاضرون في ضيافته وحمايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص629، تحت «دلالة التعبير باسم الإشارة هؤلاء»","url":""}]},{"id":"s15-112","number":112,"surah":15,"verses":[72],"references":[{"surah":15,"verses":[72]}],"verseLabel":"الحجر: 72","question":"ما دلالة القسم بـ﴿لَعَمْرُكَ﴾؟","answer":"على قول جمهور المفسرين إن الخطاب للنبي محمد ﷺ، ففي القسم بحياته تشريف عظيم له، وتأكيد لما أخبر به عن ضلال المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص646، تحت «بلاغة صيغة جملة القسم لعمرك»","url":""}]},{"id":"s15-113","number":113,"surah":15,"verses":[72],"references":[{"surah":15,"verses":[72]}],"verseLabel":"الحجر: 72","question":"ما سرّ فتح العين في ﴿لَعَمْرُكَ﴾ في القسم؟","answer":"اختير الفتح في القسم لأنه أخف، ولأن هذا التعبير كثير الدوران على الألسنة؛ فناسبت كثرة استعماله خفة لفظه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص647، تحت «وجه اختصاص لعمرك دون عمرك بالقسم»","url":""}]},{"id":"s15-114","number":114,"surah":15,"verses":[72],"references":[{"surah":15,"verses":[72]}],"verseLabel":"الحجر: 72","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿في سكرتهم﴾؟","answer":"شُبّه ضلالهم وغلبة شهواتهم بسكر يحجب العقل عن التمييز.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص648، تحت «بلاغة الاستعارة التصريحية في لفظ سكرتهم»","url":""}]},{"id":"s15-184","number":184,"surah":15,"verses":[72],"references":[{"surah":15,"verses":[72]}],"verseLabel":"الحجر: 72","question":"ما بلاغة التعبير بـ﴿يعمهون﴾؟","answer":"يصور حيرتهم وترددهم كمن عميت بصيرته فلم يعرف وجه الصواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص649، تحت «بلاغة المجاز في لفظ يعمهون»","url":""}]},{"id":"s15-115","number":115,"surah":15,"verses":[72],"references":[{"surah":15,"verses":[72]}],"verseLabel":"الحجر: 72","question":"ما دلالة إفراد ﴿سَكْرَتِهِمْ﴾ مع تعددهم؟","answer":"قوبل جمعهم بسكرة واحدة، للدلالة على اتحاد سبب ضلالهم واشتراكهم في حال تحجبهم عن الهدى، فكأن العقل الغائب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص649، تحت «نكتة إفراد سكرتهم دون جمعها في السياق»","url":""}]},{"id":"s15-116","number":116,"surah":15,"verses":[73],"references":[{"surah":15,"verses":[73]}],"verseLabel":"الحجر: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَخَذَتْهُمُ الصَّيْحَةُ مُشْرِقِينَ﴾؟","answer":"جاءت «مشرقين» حالًا لتصور هيئتهم حين أدركهم العذاب في ضوء النهار، يشاهدون شدته؛ فزاد ذلك هول المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص654، تحت «بلاغة الإخبار بالحال مشرقين دون الظرف»","url":""}]},{"id":"s15-117","number":117,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"لماذا قيل: ﴿فجعلنا﴾ لا «فقلبنا»؟","answer":"يبرز ﴿جعلنا﴾ تحول هيئة المدينة إلى ضدها وتمام وقوع التغيير.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص656، تحت «سر اختيار لفظ فجعلنا دون قلبنا»","url":""}]},{"id":"s15-185","number":185,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"ما بلاغة قوله: ﴿عاليها سافلها﴾؟","answer":"يصوّر قلب المدينة وإهلاك ما عليها، فيرى السامع أثر الانقلاب وهوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص657، تحت «بلاغة التعبير بجعل العالي سافلا لا العكس»","url":""}]},{"id":"s15-118","number":118,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"ما سرّ ﴿وَأَمْطَرْنَا عَلَيْهِمْ﴾ في الحجر، و﴿وَأَمْطَرْنَا عَلَيْهَا﴾ في هود؟","answer":"في الحجر عاد الضمير إلى القوم المجرمين، فالتصريح بإمطارهم أبلغ في زجرهم وبيان استئصالهم. وفي هود عاد الضمير في ﴿عَلَيْهَا﴾ إلى المدينة التي جرى ذكر قلبها، فناسب كل ضمير سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص659، 660، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s15-119","number":119,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"ما سرّ تقديم ﴿عَلَيْهِمْ﴾ على ﴿حِجَارَةً﴾؟","answer":"يفيد التقديم تخصيصهم بإصابة الحجارة وتأكيده؛ فلا يصيب هذا العذاب لوطًا وأهله الناجين، ويبرز الاهتمام بعقوبة الهالكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص659، تحت «دلالة تقديم عليهم على حجارة»","url":""}]},{"id":"s15-120","number":120,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"ما معنى ﴿من﴾ في قوله تعالى: ﴿من سجيل﴾؟","answer":"تبين ﴿من﴾ جنس الحجارة التي أمطرت على القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص661، تحت «معنى من في قوله من سجيل»","url":""}]},{"id":"s15-186","number":186,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"ما نكتة التعبير بلفظ ﴿سجيل﴾؟","answer":"السجيل طين اشتد وتصلب، فيصور قوة حجارة العذاب وصلابتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص661، تحت «نكتة التعبير بلفظ سجيل في البيان الجليل»","url":""}]},{"id":"s15-121","number":121,"surah":15,"verses":[75],"references":[{"surah":15,"verses":[75]}],"verseLabel":"الحجر: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿لَآيَاتٍ لِلْمُتَوَسِّمِينَ﴾ بالجمع؟","answer":"جُمعت الآيات لتعدد وجوه العبرة في القصة: مجيء الضيف والبشارة وإنجاء المؤمنين وإهلاك المكذبين وقلب المدينة وإمطار الحجارة؛ فكل واحدة منها آية للناظر المتأمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص664، تحت «نكتة جمع الآيات دون إفرادها»","url":""}]},{"id":"s15-122","number":122,"surah":15,"verses":[75],"references":[{"surah":15,"verses":[75]}],"verseLabel":"الحجر: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلْمُتَوَسِّمِينَ﴾؟","answer":"المتوسمون يستدلون بالعلامات الظاهرة على حقائق الأمور؛ فلا يقفون عند مشاهدة الآثار، بل يعتبرون بسبب هلاك المكذبين ونجاة المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص665، تحت «نكتة التعبير بلفظ للمتوسمين»","url":""}]},{"id":"s15-123","number":123,"surah":15,"verses":[76],"references":[{"surah":15,"verses":[76]}],"verseLabel":"الحجر: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّهَا لَبِسَبِيلٍ مُقِيمٍ﴾؟","answer":"«مقيم» يصور الطريق ثابتًا معروفًا لا ينقطع سلوك الناس له؛ فآثار القرية في طريق يمرون به، والعبرة قريبة من أعينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص669، تحت «دلالة اختيار مفردة مقيم»","url":""}]},{"id":"s15-124","number":124,"surah":15,"verses":[78],"references":[{"surah":15,"verses":[78]}],"verseLabel":"الحجر: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كَانَ أَصْحَابُ الْأَيْكَةِ لَظَالِمِينَ﴾؟","answer":"وصفهم بالظلم يكشف تجاوزهم الحق ووضعهم نعم الله في غير مواضعها؛ ويدخل فيه كفرهم وشركهم، وهو أعظم الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص679، تحت «سر إيثار لفظ الظلم دون الكفر»","url":""}]},{"id":"s15-126","number":126,"surah":15,"verses":[80],"references":[{"surah":15,"verses":[80]}],"verseLabel":"الحجر: 80","question":"ما سرّ تسميتهم ﴿أَصْحَابُ الْحِجْرِ﴾ هنا دون «ثمود»؟","answer":"نسبوا إلى موضعهم المحاط بالحجارة، وفي الاسم استحضار قوتهم وتحصنهم ونحتهم البيوت في الجبال؛ وهي أسباب لم تمنع عنهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص689، تحت «وجه تسمية القوم هنا بأصحاب الحجر دون ثمود»","url":""}]},{"id":"s15-127","number":127,"surah":15,"verses":[80],"references":[{"surah":15,"verses":[80]}],"verseLabel":"الحجر: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَّبَتْ... الْمُرْسَلِينَ﴾ مع أن رسولهم واحد؟","answer":"لتوافق الرسل في أصل دعوتهم، كان تكذيب صالح تكذيبًا للجميع؛ ولفظ «المرسلين» يُشعر أيضًا بأن رد الرسول ردٌّ على من أرسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص689، تحت «بلاغة التعبير في جمع المرسلين»","url":""}]},{"id":"s15-128","number":128,"surah":15,"verses":[81],"references":[{"surah":15,"verses":[81]}],"verseLabel":"الحجر: 81","question":"ما دلالة جمع ﴿آيَاتِنَا﴾ مع أن أشهر آيات ثمود الناقة؟","answer":"من توجيه الجمع أن الناقة الواحدة اشتملت على وجوه متعددة من الدلالة؛ فتنوع ما يشاهدونه من شأنها يجعلها آيات على قدرة الله وصدق رسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص693، تحت «نكتة جمع الآيات في قوله آياتنا»","url":""}]},{"id":"s15-129","number":129,"surah":15,"verses":[81],"references":[{"surah":15,"verses":[81]}],"verseLabel":"الحجر: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿فَكَانُوا عَنْهَا مُعْرِضِينَ﴾؟","answer":"الإعراض يصور تولّيهم عن الآيات بعد وصولها إليهم، و«كانوا» مع وصف «معرضين» تدل على استمرار هذا الموقف ورسوخه حتى صار طبعًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص694، تحت «نكتة التعبير بالإعراض عن الآيات»","url":""}]},{"id":"s15-130","number":130,"surah":15,"verses":[82],"references":[{"surah":15,"verses":[82]}],"verseLabel":"الحجر: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿وَكَانُوا يَنْحِتُونَ﴾؟","answer":"«كانوا» مع المضارع تدل على استمرار النحت وعادتهم فيه؛ فتستحضر تمكنهم من هذه الصنعة واغترارهم بما أنشؤوه من بيوت قوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص697، تحت «سر التعبير بتركيب وكانوا ينحتون»","url":""}]},{"id":"s15-131","number":131,"surah":15,"verses":[82],"references":[{"surah":15,"verses":[82]}],"verseLabel":"الحجر: 82","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿يَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتًا﴾، وفي الأعراف: ﴿تَنْحِتُونَ الْجِبَالَ بُيُوتًا﴾؟","answer":"في الحجر تحتمل «من» ابتداء النحت من الجبال أو التبعيض، والسياق يذكر تكذيبهم. أما الأعراف فسياق تعداد النعم، فناسبه العموم في ﴿تَنْحِتُونَ الْجِبَالَ﴾، وقد سبقه ﴿مِنْ سُهُولِهَا﴾ فاستُغني عن تكرار «من».","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص700، تحت «توجيه المتشابه»","url":""}]},{"id":"s15-132","number":132,"surah":15,"verses":[82],"references":[{"surah":15,"verses":[82]}],"verseLabel":"الحجر: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿آمِنِينَ﴾ وحذف ممَّ كانوا آمنين؟","answer":"حُذف متعلق الأمن ليتسع لما كانوا يتوهمونه من السلامة من الانهيار والعدو وسائر المخاوف؛ فقد اغتروا بحصانة بيوتهم، ولم تمنع عنهم عذاب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص699، 700، تحت «دلالة حذف متعلق اسم الفاعل آمنين»","url":""}]},{"id":"s15-133","number":133,"surah":15,"verses":[84],"references":[{"surah":15,"verses":[84]}],"verseLabel":"الحجر: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا أَغْنَى عَنْهُمْ مَا كَانُوا يَكْسِبُونَ﴾ لا نفع؟","answer":"الإغناء هنا دفع الضرر؛ فنفت الآية أن تدفع مكاسبهم عنهم العذاب الذي ظنوا أنها تحميهم منه. أما النفع فأعم، إذ يشمل جلب الخير ودفع الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص706، تحت «سر التعبير بالإغناء دون النفع في الآية الكريمة»","url":""}]},{"id":"s15-134","number":134,"surah":15,"verses":[84],"references":[{"surah":15,"verses":[84]}],"verseLabel":"الحجر: 84","question":"ما سرّ التعبير بـ﴿يَكْسِبُونَ﴾ دون «يبنون» أو «ينحتون»؟","answer":"الكسب أوسع من البناء والنحت؛ فيشمل ما حصّلوه من الأموال وما عملوه واعتقدوه، فيعم النفي جميع ما ظنوه نافعًا لهم أو دافعًا للعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص708، تحت «سر التعبير بالكسب دون البناء أو النحت»","url":""}]},{"id":"s15-136","number":136,"surah":15,"verses":[85],"references":[{"surah":15,"verses":[85]}],"verseLabel":"الحجر: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاصْفَحِ الصَّفْحَ الْجَمِيلَ﴾؟","answer":"الصفح إعراض عن الذنب وترك مؤاخذة صاحبه، ووصفه بالجمال يطلب صفحًا يخلو من العتاب والتقريع والمنّ؛ فليس مجرد ترك العقوبة مع إبقاء الأذى بالقول.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص721، تحت «بلاغة الاستعارة في قوله الصفح الجميل»","url":""}]},{"id":"s15-137","number":137,"surah":15,"verses":[86],"references":[{"surah":15,"verses":[86]}],"verseLabel":"الحجر: 86","question":"ما دلالة ختام الآية بـ﴿إِنَّ رَبَّكَ هُوَ الْخَلَّاقُ الْعَلِيمُ﴾؟","answer":"يجمع الوصفان كمال القدرة على الخلق والإعادة وكمال العلم بأحوال الخلق وأعمالهم؛ فيطمئن النبي إلى أن ربه يتولى أمرهم ويجازيهم، ويناسب ذلك ذكر الساعة والأمر بالصفح.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص726، تحت «بلاغة اجتماع وصفي الخلاق العليم»","url":""}]},{"id":"s15-138","number":138,"surah":15,"verses":[87],"references":[{"surah":15,"verses":[87]}],"verseLabel":"الحجر: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿آتَيْنَاكَ﴾ لا أعطيناك أو أوحينا؟","answer":"الإيتاء يتضمن وصول العطية إلى النبي، ويجمع معنى الإعطاء والتنزيل والإيحاء؛ وفيه إبراز للإكرام والإنعام بالقرآن، فوق مجرد الإخبار بوقوع الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص729، 730، تحت «نكتة التعبير بالفعل آتيناك دون أعطيناك»","url":""}]},{"id":"s15-139","number":139,"surah":15,"verses":[87],"references":[{"surah":15,"verses":[87]}],"verseLabel":"الحجر: 87","question":"ما دلالة تسمية الفاتحة ﴿سَبْعًا مِنَ الْمَثَانِي﴾؟","answer":"على تفسير السبع المثاني بالفاتحة، فهي سبع آيات تُثنّى قراءتها وتتكرر في الصلاة؛ فجمع التعبير عدد آياتها ووصف تكرار تلاوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص731، تحت «دلالة لفظ المثاني»","url":""}]},{"id":"s15-140","number":140,"surah":15,"verses":[87],"references":[{"surah":15,"verses":[87]}],"verseLabel":"الحجر: 87","question":"ما سرّ عطف ﴿وَالْقُرْآنَ الْعَظِيمَ﴾ على السبع المثاني؟","answer":"على تفسير السبع المثاني بالفاتحة، فهذا عطف العام على الخاص؛ خُصّت الفاتحة بالذكر تشريفًا لها، ثم ذُكر القرآن كله تعظيمًا للنعمة التي أوتيها النبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص732، تحت «نوع عطف جملة والقرآن العظيم على السابق»","url":""}]},{"id":"s15-141","number":141,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَمُدَّنَّ عَيْنَيْكَ﴾ لا تنظر؟","answer":"مدّ العين يصور إطالة النظر مع شدة الرغبة والتطلع؛ فالنهي يتجه إلى الحرص على متاعهم والتعلق به، وهو أبلغ من النهي عن مجرد النظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص739، تحت «براعة التعبير بلا تمدن عينيك دون لا تنظر»","url":""}]},{"id":"s15-142","number":142,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما سرّ تثنية ﴿عَيْنَيْكَ﴾ في النهي عن مدّهما إلى متاع الآخرين؟","answer":"تثنية العينين تناسب كثرة المتاع الذي عندهم وتنوع أصنافه؛ فتشمل صورة النهي استغراق النظر والتطلع إلى ما بُسط لهم منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص739، تحت «نكتة التعبير بالعينين دون أن يقول عينك»","url":""}]},{"id":"s15-143","number":143,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"لماذا عبّر بالتمتيع في قوله: ﴿ما متعنا به﴾ دون الإنعام؟","answer":"يبرز التمتيع قصر مدة ما عندهم وزواله، فلا يستحق التعلق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص740، تحت «بلاغة ذكر التمتع دون الإنعام»","url":""}]},{"id":"s15-187","number":187,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما دلالة قوله تعالى: ﴿أزواجًا منهم﴾؟","answer":"تفسر الأزواج بأصناف من الناس؛ فمهما تنوع المتاع وتعدد أصحابه فهو زائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص742، تحت «دلالة قوله أزواجا»","url":""}]},{"id":"s15-144","number":144,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما سرّ تقديم ﴿بِهِ﴾ في ﴿مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِنْهُمْ﴾؟","answer":"يبرز التقديم الاهتمام بالمتاع الذي تعلقوا به وشدة إقبالهم عليه، كما يُبقي «أزواجًا» متصلة بقيدها «منهم» من غير فصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص742، تحت «فائدة تقديم الجار والمجرور به»","url":""}]},{"id":"s15-145","number":145,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَحْزَنْ عَلَيْهِمْ﴾؟","answer":"فيه تسلية للنبي وتخفيف لحسرته على إعراضهم وما يصيرون إليه؛ وذكر «عليهم» يوجه النهي إلى الحزن على هؤلاء المكذبين، فلا يعم كل حزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص744، تحت «بلاغة التعبير في قوله ولا تحزن عليهم بين الكناية والتصريح»","url":""}]},{"id":"s15-146","number":146,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ﴾؟","answer":"صُوّر لين الجانب والتواضع للمؤمنين بطائر يخفض جناحه لفراخه فيضمهم ويرفق بهم؛ فتجمع الصورة القرب والرحمة وحسن الرعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص746، تحت «بلاغة الاستعارة التمثيلية في السياق البليغ»","url":""}]},{"id":"s15-147","number":147,"surah":15,"verses":[89],"references":[{"surah":15,"verses":[89]}],"verseLabel":"الحجر: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنِّي أَنَا النَّذِيرُ الْمُبِينُ﴾ ولم يذكر البشير؟","answer":"المقام مقام وعيد للمكذبين وتخويف لهم من عاقبة التكذيب؛ فناسب إبراز الإنذار الواضح الذي يقيم الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص753، تحت «نكتة ذكر النذير دون البشير»","url":""}]},{"id":"s15-148","number":148,"surah":15,"verses":[90],"references":[{"surah":15,"verses":[90]}],"verseLabel":"الحجر: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿كَمَا أَنْزَلْنَا عَلَى الْمُقْتَسِمِينَ﴾؟","answer":"من توجيه التشبيه أنه متصل بالإنذار السابق: أُنذركم بمثل ما أُنذر به المقتسمون، أو بما أُنزل عليهم من العذاب؛ ففيه تغليظ للوعيد. وقيل: يتصل بإيتاء الكتاب، تشبيهًا بما أُنزل على أهل الكتاب الذين فرّقوا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص756، تحت «نكتة التشبيه بالكاف في سياق الآية الكريمة»","url":""}]},{"id":"s15-149","number":149,"surah":15,"verses":[91],"references":[{"surah":15,"verses":[91]}],"verseLabel":"الحجر: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿جَعَلُوا الْقُرْآنَ عِضِينَ﴾؟","answer":"«عضين» تصور القرآن كجسم مزّقوه أعضاء متفرقة؛ ومن توجيهها أنهم فرّقوا القول فيه بين سحر وشعر ونحوهما، أو آمنوا ببعض وكفروا ببعض. فالصورة تُظهر تشويههم لوحدته، لا مجرد تقسيم محايد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص763، تحت «بلاغة الاستعارة في لفظ عضين»","url":""}]},{"id":"s15-150","number":150,"surah":15,"verses":[92],"references":[{"surah":15,"verses":[92]}],"verseLabel":"الحجر: 92","question":"ما نكتة التوكيد بـ﴿أجمعين﴾ في قوله: ﴿لنسألنهم أجمعين﴾؟","answer":"ينفي أن يترك أحد منهم بلا سؤال أو حساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص768، تحت «نكتة التعبير بالتوكيد أجمعين»","url":""}]},{"id":"s15-188","number":188,"surah":15,"verses":[92],"references":[{"surah":15,"verses":[92]}],"verseLabel":"الحجر: 92","question":"لماذا قيل: ﴿عما كانوا يعملون﴾؟","answer":"يعم السؤال أعمالهم التي اقترفوها ويقرر مسؤوليتهم عنها في سياق الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص769، تحت «سبب إيثار السؤال عما سلف من عملهم»","url":""}]},{"id":"s15-151","number":151,"surah":15,"verses":[94],"references":[{"surah":15,"verses":[94]}],"verseLabel":"الحجر: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاصْدَعْ بِمَا تُؤْمَرُ﴾ لا فبلّغ؟","answer":"الصدع يتضمن الجهر والإظهار بقوة وتأثير، وفي أصل معناه الشق؛ فيصور إعلان الحق الذي يفصل بينه وبين الباطل، ويزيد على مجرد إيصال البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص774، 775، تحت «سبب إيثار التعبير بفاصدع دون فبلغ»","url":""}]},{"id":"s15-152","number":152,"surah":15,"verses":[94],"references":[{"surah":15,"verses":[94]}],"verseLabel":"الحجر: 94","question":"ما دلالة بناء ﴿تُؤْمَرُ﴾ للمفعول؟","answer":"الآمر معلوم، والبناء للمفعول يبرز أن ما يجهر به النبي مأمور به من عند الله؛ فهو يبلّغ ما أُمر به، ولا ينشئ الدعوة من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص776، تحت «دلالة التعبير بصيغة المبني للمفعول تؤمر»","url":""}]},{"id":"s15-153","number":153,"surah":15,"verses":[95],"references":[{"surah":15,"verses":[95]}],"verseLabel":"الحجر: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّا كَفَيْنَاكَ الْمُسْتَهْزِئِينَ﴾؟","answer":"تعلقت الكفاية بالمستهزئين أنفسهم، فتشمل دفع أذاهم وأفعالهم، لا استهزاءهم وحده؛ وفي ذلك طمأنة للنبي تعينه على الجهر بما أُمر به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص782، تحت «دلالة إسناد الكفاية إلى ذات المستهزئين»","url":""}]},{"id":"s15-154","number":154,"surah":15,"verses":[96],"references":[{"surah":15,"verses":[96]}],"verseLabel":"الحجر: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿يَجْعَلُونَ مَعَ اللَّهِ إِلَهًا آخَرَ﴾ لا ربًا؟","answer":"لأن موضع شركهم هو العبادة والتأله لغير الله، مع إقرارهم بربوبيته؛ فلفظ «إلهًا» يحدد الجريمة التي وقعوا فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص785، تحت «براعة ذكر لفظ إلها دون ربا»","url":""}]},{"id":"s15-155","number":155,"surah":15,"verses":[96],"references":[{"surah":15,"verses":[96]}],"verseLabel":"الحجر: 96","question":"ما دلالة تنكير ﴿إِلَهًا﴾ في ﴿إِلَهًا آخَرَ﴾؟","answer":"التنكير يعرض المعبود الباطل غير معين، أيًّا كان نوعه؛ فيكشف أن اتخاذهم الآلهة تابع لأهوائهم وأوهامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص786، تحت «نكتة تنكير لفظ إلها»","url":""}]},{"id":"s15-156","number":156,"surah":15,"verses":[96],"references":[{"surah":15,"verses":[96]}],"verseLabel":"الحجر: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿فَسَوْفَ يَعْلَمُونَ﴾ لا فسيعلمون؟","answer":"«سوف» تمد زمن الانتظار أكثر من السين، فيشتد وقع الوعيد وهم يترقبون ما سيعلمونه؛ وتأخر العقوبة لا يزيل تحققها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص786، تحت «نكتة ذكر سوف دون السين»","url":""}]},{"id":"s15-157","number":157,"surah":15,"verses":[97],"references":[{"surah":15,"verses":[97]}],"verseLabel":"الحجر: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ﴾؟","answer":"الإخبار بعلم الله بحاله تسلية له وبيان للعناية به؛ والمضارع يستحضر استمرار هذا العلم، فلا يخفى على ربه ما يتجدد له من ضيق بسبب أقوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص791، تحت «نكتة التعبير بالمضارع نعلم»","url":""}]},{"id":"s15-158","number":158,"surah":15,"verses":[97],"references":[{"surah":15,"verses":[97]}],"verseLabel":"الحجر: 97","question":"ما سرّ إسناد الضيق إلى الصدر دون القلب؟","answer":"الصدر موضع يُتصوَّر فيه الاتساع والانقباض، فناسب تصوير أثر الأذى به؛ وإسناد الضيق إليه يصور التأذي بأقوالهم مع بقاء القلب مطمئنًا بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص794، تحت «بلاغة إسناد الضيق إلى الصدر دون القلب»","url":""}]},{"id":"s15-159","number":159,"surah":15,"verses":[98],"references":[{"surah":15,"verses":[98]}],"verseLabel":"الحجر: 98","question":"ما دلالة توجيه النبي إلى ﴿فَسَبِّحْ بِحَمْدِ رَبِّكَ﴾ بعد ذكر ضيق صدره؟","answer":"لأن التسبيح المصحوب بحمد الله والصلاة والعبادة مما يزيل ضيق الصدر والفزع؛ فجمع له بين تنزيه ربه والثناء عليه والتوجه إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص799، تحت «الغرض من الأمر بين التعيين والعموم»","url":""}]},{"id":"s15-160","number":160,"surah":15,"verses":[98],"references":[{"surah":15,"verses":[98]}],"verseLabel":"الحجر: 98","question":"ما فائدة الإضافة في قوله تعالى: ﴿بحمد ربك﴾؟","answer":"تفيد اختصاص الرب سبحانه بالحمد واجتماع التسبيح مع الثناء عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص800، تحت «فائدة الإضافة في قوله بحمد ربك»","url":""}]},{"id":"s15-189","number":189,"surah":15,"verses":[98],"references":[{"surah":15,"verses":[98]}],"verseLabel":"الحجر: 98","question":"لماذا اختير لفظ ﴿ربك﴾ في قوله: ﴿بحمد ربك﴾؟","answer":"في إضافة الرب إلى النبي لطف به؛ فهو مدبر أمره ومربيه والمحسن إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص800، تحت «سبب اختيار لفظ ربك»","url":""}]},{"id":"s15-161","number":161,"surah":15,"verses":[99],"references":[{"surah":15,"verses":[99]}],"verseLabel":"الحجر: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاعْبُدْ رَبَّكَ حَتَّى يَأْتِيَكَ الْيَقِينُ﴾؟","answer":"تحديد الغاية بالموت يدل على استغراق العبادة زمن الحياة، فلا تكون مرة أو مدة ثم تنقطع؛ بل يثبت العبد عليها حتى أجله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص805، تحت «بلاغة الكناية»","url":""}]},{"id":"s15-162","number":162,"surah":15,"verses":[99],"references":[{"surah":15,"verses":[99]}],"verseLabel":"الحجر: 99","question":"ما سرّ تسمية الموت ﴿الْيَقِينَ﴾؟","answer":"لتحقق وقوعه ويقين الناس بمجيئه؛ فسُمّي باسم ما يلازمه من اليقين، تذكيرًا بنهاية لا شك فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص805، تحت «مجاز التعبير في تسمية الموت باليقين»","url":""}]},{"id":"s15-163","number":163,"surah":15,"verses":[99],"references":[{"surah":15,"verses":[99]}],"verseLabel":"الحجر: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿يَأْتِيَكَ﴾ لا يجيئك؟","answer":"اختير الإتيان دون المجيء للإشعار بأن إتيان الموت سهل يسير، وأنه ليس بينه وبين العبد إلا انقضاء الوقت وحلول الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص804، تحت «بلاغة اختيار لفظ الإتيان دون المجيء»","url":""}]},{"id":"s16-1","number":1,"surah":16,"verses":[1],"references":[{"surah":16,"verses":[1]}],"verseLabel":"النحل: 1","question":"ما سرّ افتتاح السورة بالماضي ﴿أَتَى أَمْرُ اللَّهِ﴾ مع أن الموعود لم يقع بعد؟","answer":"لتحقيق الوقوع؛ ما وعد الله به محقق حتى صح التعبير عنه كأنه أتى وانتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص26، تحت «براعة الاستهلال ودلالة الفعل الماضي أتى»","url":""}]},{"id":"s16-2","number":2,"surah":16,"verses":[1],"references":[{"surah":16,"verses":[1]}],"verseLabel":"النحل: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْرُ اللَّهِ﴾ لا عذاب الله؟","answer":"عُبّر بـ﴿أمر الله﴾ تهويلًا وتعظيمًا للموعود؛ فهو ما قدّره الله وأراد وقوعه في أجله، وإضافته إلى اسم الجلالة تزيده عظمةً وهيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص26، تحت «فائدة إضافة أمر إلى اسم الجلالة»","url":""}]},{"id":"s16-3","number":3,"surah":16,"verses":[1],"references":[{"surah":16,"verses":[1]}],"verseLabel":"النحل: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا تَسْتَعْجِلُوهُ﴾ بعد ﴿أتى﴾؟","answer":"الماضي يقرر تحقق الموعود، ثم يتفرع عليه النهي عن استعجاله استهزاءً؛ فما هو واقع لا محالة لا يجدي استبطاؤه ولا طلب تعجيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص27، تحت «نوع الفاء في فلا تستعجلوه وفائدتها»","url":""}]},{"id":"s16-4","number":4,"surah":16,"verses":[1],"references":[{"surah":16,"verses":[1]}],"verseLabel":"النحل: 1","question":"ما سرّ ختام الآية بـ﴿سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ﴾؟","answer":"زعم المشركون أن شركاءهم يدفعون عنهم العذاب، فجاء التسبيح والتعالي تنزيهًا لله عن هذا الزعم وإبطالًا لقدرة تلك المعبودات على منع أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص30، تحت «دلالة الجمع بين سبحانه وتعالى»","url":""}]},{"id":"s16-5","number":5,"surah":16,"verses":[2],"references":[{"surah":16,"verses":[2]}],"verseLabel":"النحل: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿يُنَزِّلُ الْمَلَائِكَةَ بِالرُّوحِ﴾؟","answer":"سمي الوحي روحًا لأنه يحيي القلوب كما تحيي الروح الأجساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص40، 41، تحت «بلاغة الاستعارة في إطلاق الروح على الوحي»","url":""}]},{"id":"s16-6","number":6,"surah":16,"verses":[2],"references":[{"surah":16,"verses":[2]}],"verseLabel":"النحل: 2","question":"ما دلالة تعريف ﴿الملائكة﴾ في قوله تعالى: ﴿ينزل الملائكة بالروح من أمره﴾؟","answer":"تفيد ﴿أل﴾ الجنس، فتتناول جنس الملائكة الذين يبلغون رسالات الله وينزلون بأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص39، تحت «دلالة أل على الجنس في لفظ الملائكة»","url":""}]},{"id":"s16-208","number":208,"surah":16,"verses":[2],"references":[{"surah":16,"verses":[2]}],"verseLabel":"النحل: 2","question":"ما دلالة جمع لفظ ﴿الملائكة﴾ في سياق تنزيل الوحي؟","answer":"يشمل الجمع الملائكة الموكلين بالتبليغ، وقيل أريد به جبريل وعبر عنه بالجمع لأنه رئيسهم والمقتدى به في هذا الشأن.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص39، تحت «دلالة الجمع في لفظ الملائكة»","url":""}]},{"id":"s16-7","number":7,"surah":16,"verses":[2],"references":[{"surah":16,"verses":[2]}],"verseLabel":"النحل: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ أَمْرِهِ﴾؟","answer":"من توجيه العبارة أن التنزيل يقع بأمر الله وإذنه؛ فلا تتصرف الملائكة في الوحي من عند نفسها. وتحتمل «من» أيضًا بيان أن الوحي من جنس أموره وشؤونه التي استأثر بتقديرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص41، تحت «دلالة حرف الجر من أمره ومعنى الإضافة»","url":""}]},{"id":"s16-8","number":8,"surah":16,"verses":[2],"references":[{"surah":16,"verses":[2]}],"verseLabel":"النحل: 2","question":"ما دلالة تلخيص الوحي في ﴿أَنْ أَنْذِرُوا أَنَّهُ لَا إِلَهَ إِلَّا أَنَا﴾؟","answer":"التوحيد أصل الدعوة وأول واجب، فجمع الوحي في إفراد الله بالألوهية. وناسب الإنذار حال من اتخذوا مع الله آلهة أخرى، لتحذيرهم من عاقبة الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص48، تحت «بلاغة كلمة التوحيد لا إله إلا أنا»","url":""}]},{"id":"s16-9","number":9,"surah":16,"verses":[3],"references":[{"surah":16,"verses":[3]}],"verseLabel":"النحل: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ﴾؟","answer":"«بالحق» تجعل الخلق ملتبسًا بالحكمة ومقرونًا بها، لا عبثًا؛ ومن ذلك أن يجازى كل عامل بما يناسب عمله، فالخلق قائم على غاية وحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص58، تحت «دلالة الباء في شبه الجملة بالحق»","url":""}]},{"id":"s16-10","number":10,"surah":16,"verses":[4],"references":[{"surah":16,"verses":[4]}],"verseLabel":"النحل: 4","question":"ما سرّ التعبير في قوله تعالى عن الإنسان: ﴿فَإِذَا هُوَ خَصِيمٌ مُبِينٌ﴾؟","answer":"«إذا» للمفاجأة والفاء للتفريع؛ فيبرز التركيب المفارقة بين أصله الضعيف نطفةً وصيرورته شديد الخصومة، حتى يجادل في قدرة من خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص71، تحت «دلالة التركيب فإذا وأثرها في السياق»","url":""}]},{"id":"s16-11","number":11,"surah":16,"verses":[4],"references":[{"surah":16,"verses":[4]}],"verseLabel":"النحل: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿خَصِيمٌ﴾ لا مجادل؟","answer":"«خصيم» على وزن فعيل للمبالغة، فتدل على شدة الخصومة وكثرتها. والجدال قد يكون محمودًا أو مذمومًا، أما الخصومة هنا فتبرز منازعته وجحوده لخالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص76، تحت «الخصيم والمجادل»","url":""}]},{"id":"s16-12","number":12,"surah":16,"verses":[5],"references":[{"surah":16,"verses":[5]}],"verseLabel":"النحل: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالْأَنْعَامَ خَلَقَهَا لَكُمْ﴾ وقدّمها؟","answer":"تقديم الأنعام يبرز العناية بما فيها من فوائد للإنسان، وإعادة الضمير في «خلقها» تقوي تقرير خلقها؛ تمهيدًا لتفصيل نعم الدفء والمنافع والأكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص81، تحت «سر تقديم المفعول به وبلاغته»","url":""}]},{"id":"s16-13","number":13,"surah":16,"verses":[5],"references":[{"surah":16,"verses":[5]}],"verseLabel":"النحل: 5","question":"ما دلالة تعريف ﴿الْأَنْعَامَ﴾؟","answer":"لاستحضار الجنس المعروف كله، لا أفرادًا مخصوصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص81، تحت «دلالة أل في لفظ الأنعام وفائدتها»","url":""}]},{"id":"s16-14","number":14,"surah":16,"verses":[5],"references":[{"surah":16,"verses":[5]}],"verseLabel":"النحل: 5","question":"ما سرّ تخصيص ﴿دِفْءٌ﴾ بالذكر ثم عطف ﴿وَمَنَافِعُ﴾ عليه؟","answer":"خُصّ الدفء بالذكر للعناية بشأنه، ثم عُطفت عليه «منافع» لتشمل سائر ما ينتفع به من الأنعام؛ فهو عطف العام على الخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص85، تحت «دلالة عطف العام على الخاص»","url":""}]},{"id":"s16-15","number":15,"surah":16,"verses":[6],"references":[{"surah":16,"verses":[6]}],"verseLabel":"النحل: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿لَكُمْ فِيهَا جَمَالٌ﴾؟","answer":"بعد المنافع الضرورية ذُكرت نعمة الجمال التي تسر النفوس؛ وتنكيره يعظم ما في منظر الأنعام عند رواحها وسراحها من بهجة لأصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص94، تحت «دلالة تنكير لفظ جمال»","url":""}]},{"id":"s16-16","number":16,"surah":16,"verses":[6],"references":[{"surah":16,"verses":[6]}],"verseLabel":"النحل: 6","question":"ما سرّ تقديم الرواح على السراح؟","answer":"لأن جمالها عند الرواح أظهر؛ تعود ممتلئة البطون حافلة الضروع، ثم تجتمع في الحظائر، فيكون منظرها أوقع في نفوس أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص95، تحت «السر في تقديم تريحون على تسرحون»","url":""}]},{"id":"s16-17","number":17,"surah":16,"verses":[7],"references":[{"surah":16,"verses":[7]}],"verseLabel":"النحل: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿تَحْمِلُ أَثْقَالَكُمْ﴾ بالمضارع؟","answer":"لتصوير المنفعة متجددة في كل سفر وحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص101، تحت «نكتة التعبير بالمضارع تحمل»","url":""}]},{"id":"s16-18","number":18,"surah":16,"verses":[7],"references":[{"surah":16,"verses":[7]}],"verseLabel":"النحل: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَى بَلَدٍ لَمْ تَكُونُوا بَالِغِيهِ إِلَّا بِشِقِّ الْأَنْفُسِ﴾؟","answer":"استحضر المشقة التي رفعتها الأنعام ليُرى قدر النعمة بالمقارنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص103، تحت «فائدة القيد إلا بشق الأنفس»","url":""}]},{"id":"s16-19","number":19,"surah":16,"verses":[7],"references":[{"surah":16,"verses":[7]}],"verseLabel":"النحل: 7","question":"ما سرّ ختام الآية بـ﴿رَءُوفٌ رَحِيمٌ﴾؟","answer":"حمل الأثقال وتيسير بلوغ البلاد أثر من رأفة الله ورحمته بعباده؛ وقدمت الرأفة، وهي أخص وأرق، ثم ذُكرت الرحمة لتتم دلالة الإنعام ورفع المشقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص107، تحت «نكتة الترتيب في رؤوف رحيم»","url":""}]},{"id":"s16-20","number":20,"surah":16,"verses":[8],"references":[{"surah":16,"verses":[8]}],"verseLabel":"النحل: 8","question":"ما سرّ ذكر الخيل والبغال والحمير منفصلة عن الأنعام؟","answer":"لأن السياق انتقل من الدفء والأكل إلى الركوب والزينة، وهي منافعها الأظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص114، تحت «نكتة العدول عن حملها للأثقال إلى ركوبها واتخاذها زينة»","url":""}]},{"id":"s16-21","number":21,"surah":16,"verses":[8],"references":[{"surah":16,"verses":[8]}],"verseLabel":"النحل: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿لِتَرْكَبُوهَا وَزِينَةً﴾؟","answer":"نُصّ على الركوب بوصفه الغرض الأصلي من خلقها للإنسان، ثم ذُكرت الزينة منفعة تابعة؛ فجمع التعبير الحاجة والبهجة مع بيان مرتبتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص115، تحت «نكتة العدول عن لام التعليل وزينة»","url":""}]},{"id":"s16-22","number":22,"surah":16,"verses":[8],"references":[{"surah":16,"verses":[8]}],"verseLabel":"النحل: 8","question":"ما دلالة ختام الآية بـ﴿وَيَخْلُقُ مَا لَا تَعْلَمُونَ﴾؟","answer":"فتح أفق النعم لما يستحدث ويخفى، فلا يحصر الخلق في وسائل النقل المعروفة زمن التنزيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص117، تحت «فائدة الخبر في خلقه ما لا يعلمون»","url":""}]},{"id":"s16-23","number":23,"surah":16,"verses":[9],"references":[{"surah":16,"verses":[9]}],"verseLabel":"النحل: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿وَعَلَى اللَّهِ قَصْدُ السَّبِيلِ﴾؟","answer":"تقديم الجار يفيد أن بيان الطريق المستقيم وهدايته تفضل تكفل الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص123، تحت «فائدة تقديم شبه الجملة على المسند إليه»","url":""}]},{"id":"s16-24","number":24,"surah":16,"verses":[9],"references":[{"surah":16,"verses":[9]}],"verseLabel":"النحل: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿قَصْدُ السَّبِيلِ﴾ لا السبيل القاصد؟","answer":"من توجيه الإضافة أنها إضافة الصفة إلى الموصوف، أي السبيل القاصد المستقيم الذي لا عوج فيه؛ وعلى هذا يكون المعنى: على الله بيان ذلك الطريق بالأدلة والرسل والكتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص125، تحت «فائدة الإضافة في قصد السبيل»","url":""}]},{"id":"s16-25","number":25,"surah":16,"verses":[9],"references":[{"surah":16,"verses":[9]}],"verseLabel":"النحل: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمِنْهَا جَائِرٌ﴾؟","answer":"وُصف بعض السبل بالجور، أي الميل عن الاستقامة، كناية عن طرق الضلال. والعدول عن نحو «وعليه جائرها» يميز طريق الحق الذي بيّنه الله لهداية الناس من طرق الانحراف عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص126، تحت «سر العدول في ومنها جائر»","url":""}]},{"id":"s16-26","number":26,"surah":16,"verses":[10],"references":[{"surah":16,"verses":[10]}],"verseLabel":"النحل: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿هُوَ الَّذِي أَنْزَلَ مِنَ السَّمَاءِ مَاءً﴾؟","answer":"تعريف طرفي الإسناد في ﴿هُوَ الَّذِي أَنْزَلَ﴾ يفيد قصر الإنزال على الله وحده، وفي الموصول وصلته تعظيم للمنعم بذكر نعمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص134، تحت «نكتة القصر بتعريف طرفي الإسناد»","url":""}]},{"id":"s16-27","number":27,"surah":16,"verses":[10],"references":[{"surah":16,"verses":[10]}],"verseLabel":"النحل: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ﴾؟","answer":"قسم الماء بحسب نفعه المباشر للإنسان ونفعه في النبات الذي ترعى فيه الأنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص138، تحت «دلالة جملة ومنه شجر بين الفصل والوصل»","url":""}]},{"id":"s16-28","number":28,"surah":16,"verses":[11],"references":[{"surah":16,"verses":[11]}],"verseLabel":"النحل: 11","question":"ما سرّ تفصيل الزرع والزيتون والنخيل والأعناب قبل ﴿وَمِنْ كُلِّ الثَّمَرَاتِ﴾؟","answer":"لجمع القوت والزيت والثمر، ثم عمم بقوله ﴿ومن كل الثمرات﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص147، تحت «فائدة الترتيب بين الزرع وما عطف عليه»","url":""}]},{"id":"s16-29","number":29,"surah":16,"verses":[11],"references":[{"surah":16,"verses":[11]}],"verseLabel":"النحل: 11","question":"ما سرّ ختام الآية بـ﴿لِقَوْمٍ يَتَفَكَّرُونَ﴾؟","answer":"لأن إدراك ما في إنبات هذه الأصناف من دلالة على وجود الله وكمال قدرته ووحدانيته يحتاج إلى التفكر والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص150، تحت «سر تذييل الآية بالتفكر»","url":""}]},{"id":"s16-30","number":30,"surah":16,"verses":[11],"references":[{"surah":16,"verses":[11]}],"verseLabel":"النحل: 11","question":"ما دلالة إفراد ﴿آيَةً﴾ بعد ذكر أصناف النبات؟","answer":"من توجيه الإفراد أن المدلول واحد، وهو وحدانية الله، وقيل: لوحدة المنشأ الذي تتفرع عنه هذه النعم، وهو الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص149، تحت «دلالة إفراد الآية»","url":""}]},{"id":"s16-31","number":31,"surah":16,"verses":[12],"references":[{"surah":16,"verses":[12]}],"verseLabel":"النحل: 12","question":"ما سرّ جمع ﴿لَآيَاتٍ﴾ بعد تسخير الليل والنهار والشمس والقمر والنجوم؟","answer":"الجمع يراعي تعدد الأدلة؛ فالليل والنهار والشمس والقمر والنجوم، وما لكل منها من أحوال ومنافع، دلائل متنوعة على وحدانية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص159، تحت «نكتة جمع آيات في لآيات لقوم يعقلون»","url":""}]},{"id":"s16-34","number":34,"surah":16,"verses":[13],"references":[{"surah":16,"verses":[13]}],"verseLabel":"النحل: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿مُخْتَلِفًا أَلْوَانُهُ﴾؟","answer":"المراد بالألوان ما يشمل اختلاف الأصناف والخصائص؛ فتنوع ما خلقه الله في الأرض يلفت إلى سعة قدرته وتعدد نعمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص169، تحت «الموقع النحوي لجملة مختلفا ألوانه»","url":""}]},{"id":"s16-35","number":35,"surah":16,"verses":[14],"references":[{"surah":16,"verses":[14]}],"verseLabel":"النحل: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿وَهُوَ الَّذِي سَخَّرَ الْبَحْرَ﴾؟","answer":"«هو» مبتدأ، والموصول خبر؛ وتعريف الطرفين يفيد قصر تسخير البحر على الله. وتذكر الصلة نعمته بتذليل هذا المخلوق لمنافع الناس، فتدل على قدرته واستحقاقه العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص178، تحت «بلاغة القصر في تعريف طرفي الإسناد»","url":""}]},{"id":"s16-36","number":36,"surah":16,"verses":[14],"references":[{"surah":16,"verses":[14]}],"verseLabel":"النحل: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿لَحْمًا طَرِيًّا﴾؟","answer":"في الطراوة تذكير بلذة السمك ولطافته، وبنعمة خلق لحم عذب طري في ماء مالح؛ وفيها أيضًا تنبيه إلى المبادرة بأكله قبل أن يسرع إليه الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص180، تحت «فائدة وصف اللحم بالوصف طريا»","url":""}]},{"id":"s16-37","number":37,"surah":16,"verses":[15],"references":[{"surah":16,"verses":[15]}],"verseLabel":"النحل: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ تَمِيدَ بِكُمْ﴾؟","answer":"بيّن غاية إلقاء الرواسي: كراهة أن تضطرب الأرض بأهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص195، تحت «بلاغة الإيجاز في أسلوب التعليل»","url":""}]},{"id":"s16-38","number":38,"surah":16,"verses":[15],"references":[{"surah":16,"verses":[15]}],"verseLabel":"النحل: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنْهَارًا وَسُبُلًا لَعَلَّكُمْ تَهْتَدُونَ﴾؟","answer":"جُمعت الأنهار والسبل في تعداد النعم، وخُتمت بالاهتداء الذي يحتمل بلوغ مقاصد السفر، ويشمل الاستدلال بهذه المخلوقات على التوحيد؛ فتجتمع منفعة الطريق ودلالة الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص198، تحت «توجيه الاهتداء بين الحسي والمعنوي»","url":""}]},{"id":"s16-39","number":39,"surah":16,"verses":[16],"references":[{"surah":16,"verses":[16]}],"verseLabel":"النحل: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿وَعَلَامَاتٍ وَبِالنَّجْمِ هُمْ يَهْتَدُونَ﴾؟","answer":"عمم العلامات الأرضية ثم خص النجم بالذكر لعظم دوره في ظلمات البر والبحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص200، تحت «فائدة الفصل بين المعطوفات»","url":""}]},{"id":"s16-40","number":40,"surah":16,"verses":[17],"references":[{"surah":16,"verses":[17]}],"verseLabel":"النحل: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿أَفَمَنْ يَخْلُقُ كَمَنْ لَا يَخْلُقُ﴾؟","answer":"استفهام يحول براهين النعم إلى نتيجة بدهيّة: لا يستوي الخالق والعاجز المخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص206، تحت «بلاغة الاستفهام ودلالته»","url":""}]},{"id":"s16-41","number":41,"surah":16,"verses":[18],"references":[{"surah":16,"verses":[18]}],"verseLabel":"النحل: 18","question":"ما سرّ إفراد ﴿نِعْمَةَ اللَّهِ﴾ مع ذكر العد؟","answer":"اسم جنس؛ بل النعمة الواحدة تتشعب إلى نعم لا يحصيها الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص212، 213، تحت «سر إفراد النعمة مع ذكر العد ولا يعد إلا الجمع»","url":""}]},{"id":"s16-42","number":42,"surah":16,"verses":[18],"references":[{"surah":16,"verses":[18]}],"verseLabel":"النحل: 18","question":"ما سرّ ختام آية النعم بـ﴿غَفُورٌ رَحِيمٌ﴾؟","answer":"من عجز عن إحصاء النعم عجز عن الوفاء بحق شكرها؛ فجاءت المغفرة والرحمة تسليةً، وبيانًا أن الله يتجاوز عن تقصير عباده ويواصل إنعامه عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص214، تحت «علة الفصل ودلالته»","url":""}]},{"id":"s16-43","number":43,"surah":16,"verses":[19],"references":[{"surah":16,"verses":[19]}],"verseLabel":"النحل: 19","question":"ما دلالة الجمع بين ﴿مَا تُسِرُّونَ وَمَا تُعْلِنُونَ﴾؟","answer":"الجمع بين الضدين يدل على شمول علم الله للظاهر والباطن؛ فلا يحجب الإسرار شيئًا عنه، وفي ذلك بعث على إصلاح العمل والنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص221، تحت «بديع فن الطباق»","url":""}]},{"id":"s16-44","number":44,"surah":16,"verses":[20],"references":[{"surah":16,"verses":[20]}],"verseLabel":"النحل: 20","question":"ما سرّ التعبير في قوله تعالى عن المعبودات: ﴿أَمْوَاتٌ غَيْرُ أَحْيَاءٍ﴾؟","answer":"وصف الأصنام بأنها «غير أحياء» يؤكد نفي الحياة عنها، ويدفع توهم أنها كانت حية ثم ماتت أو ستحيا؛ فهي جمادات لا تملك شعورًا ولا قدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص227، تحت «بلاغة الاحتراس»","url":""}]},{"id":"s16-45","number":45,"surah":16,"verses":[21],"references":[{"surah":16,"verses":[21]}],"verseLabel":"النحل: 21","question":"ما نكتة قوله عن المعبودات: ﴿وما يشعرون﴾؟","answer":"ينفي عنها أدنى إدراك؛ فهي لا تشعر حتى بوقت بعث عابديها، فكيف تصلح للعبادة أو دفع الضرر؟","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص229، تحت «نكتة التعبير بمفردة الشعور»","url":""}]},{"id":"s16-209","number":209,"surah":16,"verses":[21],"references":[{"surah":16,"verses":[21]}],"verseLabel":"النحل: 21","question":"لماذا قيل: ﴿أيان يبعثون﴾ دون «متى يبعثون»؟","answer":"تستعمل ﴿أيان﴾ في السؤال عن الزمن العظيم الشأن، فتلائم تهويل وقت البعث وما يقع فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص230، تحت «سر استعمال أيان دون متى»","url":""}]},{"id":"s16-46","number":46,"surah":16,"verses":[22],"references":[{"surah":16,"verses":[22]}],"verseLabel":"النحل: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾؟","answer":"أُعيد لفظ «إله» في الخبر ليتجه نفي التعدد إلى الألوهية نفسها: المعبود الحق واحد لا يتعدد. فلو قيل «إلهكم واحد» وحدها لكان احتمال حمل الوحدة على غير هذا المعنى أوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص234، تحت «بلاغة إقامة الموصوف خبرا دون صفته»","url":""}]},{"id":"s16-47","number":47,"surah":16,"verses":[22],"references":[{"surah":16,"verses":[22]}],"verseLabel":"النحل: 22","question":"ما سرّ إسناد الإنكار إلى القلوب؟","answer":"لأن القلب موضع القبول والإنكار؛ فتخصيصه يكشف أن رفضهم ناشئ من فساد التلقي الباطن، مع قيام أدلة الوحدانية، لا من خفاء الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص238، تحت «بلاغة المقابلة في تخصيص الإنكار بالقلوب وتعميم الاستكبار»","url":""}]},{"id":"s16-48","number":48,"surah":16,"verses":[22],"references":[{"surah":16,"verses":[22]}],"verseLabel":"النحل: 22","question":"ما دلالة ختام الآية بـ﴿وَهُمْ مُسْتَكْبِرُونَ﴾؟","answer":"يقرن الختام إنكار القلوب باستكبار يشمل حالهم كلها؛ والجملة الاسمية تدل على تمكن هذا الوصف ورسوخه، لا صدوره عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص239، تحت «فائدة التعبير بالاسمية»","url":""}]},{"id":"s16-49","number":49,"surah":16,"verses":[23],"references":[{"surah":16,"verses":[23]}],"verseLabel":"النحل: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا جَرَمَ﴾؟","answer":"تركيب تحقيق وقطع، يقرر علم الله بالسر والعلن وجزاء المستكبرين بلا تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص240، تحت «براعة تركيب لا جرم في سياقه»","url":""}]},{"id":"s16-50","number":50,"surah":16,"verses":[24],"references":[{"surah":16,"verses":[24]},{"surah":83,"verses":[13]}],"verseLabel":"النحل: 24؛ المطففين: 13","question":"ما نكتة رفع ﴿أساطير الأولين﴾ في سورة النحل؟","answer":"جاء الرفع على تقدير: هو أساطير الأولين؛ فحكوا حكمهم الباطل على الوحي معرضين عن الإقرار بأنه تنزيل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص248، تحت «نكتة رفع لفظ أساطير»","url":""}]},{"id":"s16-210","number":210,"surah":16,"verses":[24],"references":[{"surah":16,"verses":[24]},{"surah":83,"verses":[13]}],"verseLabel":"النحل: 24؛ المطففين: 13","question":"ما دلالة قول المكذب في سورة المطففين: ﴿أساطير الأولين﴾؟","answer":"يصور اعتياده رد آيات الله بأنها خرافات قديمة، ليعرض عن حججها ومواعظها من غير نظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص482، تحت «دلالة استعمال لفظ أساطير»","url":""}]},{"id":"s16-51","number":51,"surah":16,"verses":[25],"references":[{"surah":16,"verses":[25]}],"verseLabel":"النحل: 25","question":"ما بلاغة قوله تعالى: ﴿ليحملوا أوزارهم﴾؟","answer":"صورت الذنوب أحمالًا ثقيلة تلازم أصحابها يوم القيامة، تجسيدًا لعظم تبعتها ومشقة جزائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص250، تحت «بلاغة الاستعارة التمثيلية في حمل الأوزار»","url":""}]},{"id":"s16-211","number":211,"surah":16,"verses":[25],"references":[{"surah":16,"verses":[25]}],"verseLabel":"النحل: 25","question":"ما دلالة تقييد الأوزار بقوله: ﴿كاملة﴾؟","answer":"يؤكد أنهم يتحملون تبعة ذنوبهم غير منقوصة، فلا يفلت شيء منها ولا تسقط عنهم كما يتوهمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص251، تحت «بلاغة التقييد بالحال»","url":""}]},{"id":"s16-52","number":52,"surah":16,"verses":[25],"references":[{"surah":16,"verses":[25]}],"verseLabel":"النحل: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمِنْ أَوْزَارِ الَّذِينَ يُضِلُّونَهُمْ﴾؟","answer":"يُضاف إلى وزرهم وزر إضلال غيرهم. ومن توجيه «من» التبعيض: يحملون من أوزار الأتباع ما تسببوا فيه بإضلالهم، فلا تختلط مسؤولية المضل بمطلق أعمال من تبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص252، تحت «معنى من ودلالتها»","url":""}]},{"id":"s16-53","number":53,"surah":16,"verses":[27],"references":[{"surah":16,"verses":[27]}],"verseLabel":"النحل: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَتَى اللَّهُ بُنْيَانَهُمْ مِنَ الْقَوَاعِدِ﴾؟","answer":"تُصوّر الاستعارة مكرهم كبنيان أحكموا قواعده، ثم صار انهياره سبب هلاكهم؛ وإتيانه من القواعد يصور إبطال المكر من أصوله واستئصاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص261، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s16-54","number":54,"surah":16,"verses":[27],"references":[{"surah":16,"verses":[27]}],"verseLabel":"النحل: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿فَخَرَّ عَلَيْهِمُ السَّقْفُ مِنْ فَوْقِهِمْ﴾ مع أن السقف فوق؟","answer":"القيد يؤكد أن السقف وقع عليهم وهم تحته، ويدفع احتمال سقوط سقف آخر أو وقوعه بعيدًا عنهم. ومع ذكر القواعد تكتمل صورة الهلاك المحيط بالبنيان وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص264، تحت «فائدة التقييد باللازم المعلوم»","url":""}]},{"id":"s16-55","number":55,"surah":16,"verses":[28],"references":[{"surah":16,"verses":[28]}],"verseLabel":"النحل: 28","question":"ما دلالة ﴿من﴾ في قولهم: ﴿ما كنا نعمل من سوء﴾؟","answer":"جاءت لتوكيد الاستغراق في سياق النفي، فبالغوا في ادعاء أنهم لم يعملوا أدنى سوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص293، تحت «دلالة من في قوله من سوء»","url":""}]},{"id":"s16-212","number":212,"surah":16,"verses":[28],"references":[{"surah":16,"verses":[28]}],"verseLabel":"النحل: 28","question":"ما دلالة الرد على إنكارهم بقوله تعالى: ﴿بلى﴾؟","answer":"أبطلت ﴿بلى﴾ نفيهم وأثبتت وقوع ما أنكروه، ثم قررت أن الله عليم بأعمالهم فلا ينفعهم الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص294، تحت «توجيه التعبير ببلى»","url":""}]},{"id":"s16-56","number":56,"surah":16,"verses":[29],"references":[{"surah":16,"verses":[29]}],"verseLabel":"النحل: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿فَادْخُلُوا أَبْوَابَ جَهَنَّمَ﴾ بالجمع؟","answer":"الجمع يوافق تعدد أبواب جهنم؛ فهي سبعة أبواب كما بُيّن في سورة الحجر. وفي ذكر الدخول من أبوابها إظهار لما يستقبلهم من مراتب العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص301، 302، تحت «نكتة جمع الأبواب جمع قلة»","url":""}]},{"id":"s16-57","number":57,"surah":16,"verses":[30],"references":[{"surah":16,"verses":[30]}],"verseLabel":"النحل: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَدَارُ الْآخِرَةِ خَيْرٌ﴾ لا الجنة فقط؟","answer":"«دار الآخرة» تناسب مقابلة نعيم الآخرة بالحسنة في الدنيا؛ فالحديث عن مقام الجزاء وخيريته. وإسناد الخير إلى الدار يشمل ما فيها من خير لأهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص320، تحت «إيثار تركيب دار الآخرة دون القيامة أو غيره»","url":""}]},{"id":"s16-59","number":59,"surah":16,"verses":[32],"references":[{"surah":16,"verses":[32]}],"verseLabel":"النحل: 32","question":"ما بلاغة قول الملائكة للمتقين: ﴿سلام عليكم﴾؟","answer":"الجملة الاسمية تثبت لهم السلام والأمان، وتسبق بشارة الجنة بتحية تطمئنهم عند الوفاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص340، تحت «براعة التعبير عن سلامهم بالجملة الاسمية»","url":""}]},{"id":"s16-213","number":213,"surah":16,"verses":[32],"references":[{"surah":16,"verses":[32]}],"verseLabel":"النحل: 32","question":"ما دلالة قول الملائكة للمتقين: ﴿ادخلوا الجنة﴾؟","answer":"الأمر بشارة وإكرام بما أعد لهم من الجنة جزاء أعمالهم، ولا يلزم منه أن يكون الدخول فور الوفاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص340، تحت «دلالة الأمر في ادخلوا»","url":""}]},{"id":"s16-60","number":60,"surah":16,"verses":[33],"references":[{"surah":16,"verses":[33]}],"verseLabel":"النحل: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿هَلْ يَنْظُرُونَ إِلَّا أَنْ تَأْتِيَهُمُ الْمَلَائِكَةُ﴾؟","answer":"ينفي السياق أن يبقى بعد إعراضهم إلا حلول ما وُعدوا به؛ وصُوّر بقاؤهم قبل الموت أو العذاب بصورة المنتظر له، على سبيل التهكم والتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص346، تحت «بلاغة الاستعارة التهكمية في ينظرون»","url":""}]},{"id":"s16-61","number":61,"surah":16,"verses":[34],"references":[{"surah":16,"verses":[34]}],"verseLabel":"النحل: 34","question":"ما سرّ التعبير بـ﴿مَا عَمِلُوا﴾ هنا، بعد ﴿كَذَلِكَ فَعَلَ الَّذِينَ مِنْ قَبْلِهِمْ﴾؟","answer":"المقام مقام جزاء وحساب على فعل مقصود؛ فناسبه «عملوا»، لأن العمل أخص بالقصد، أما الفعل فأعم وقد يقع من غير قصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص361، تحت «علة العدول من فعلوا إلى عملوا»","url":""}]},{"id":"s16-62","number":62,"surah":16,"verses":[35],"references":[{"surah":16,"verses":[35]}],"verseLabel":"النحل: 35","question":"ما دلالة حكاية احتجاج المشركين بـ﴿لَوْ شَاءَ اللَّهُ مَا عَبَدْنَا﴾؟","answer":"جعلوا تمكين الله لهم وإمهاله إياهم دليلًا على رضاه عن شركهم، مع أنه نهاهم عنه وأرسل الرسل بالبيان؛ فخلطوا بين وقوع الفعل بمشيئته وبين محبته له ورضاه عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص371، تحت «سر حكاية احتجاجهم في قوله لو شاء الله»","url":""}]},{"id":"s16-63","number":63,"surah":16,"verses":[36],"references":[{"surah":16,"verses":[36]}],"verseLabel":"النحل: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي كُلِّ أُمَّةٍ رَسُولًا﴾؟","answer":"ليثبت عموم الحجة عبر التاريخ؛ لا أمة تُركت بلا بيان أصل التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص391، تحت «الغرض من تقديم في كل أمة»","url":""}]},{"id":"s16-64","number":64,"surah":16,"verses":[36],"references":[{"surah":16,"verses":[36]}],"verseLabel":"النحل: 36","question":"ما دلالة الجمع بين ﴿اعْبُدُوا اللَّهَ﴾ و﴿اجْتَنِبُوا الطَّاغُوتَ﴾؟","answer":"التوحيد يجمع إثبات العبادة لله واجتناب عبادة غيره؛ فالأمران متكاملان. و«اجتنبوا» أبلغ من مجرد الترك، لأنها تصور البعد عن الطاغوت وجعل العبد في جانب غير جانبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص393، تحت «نكتة عطف الجملتين المتقابلتين بالواو»","url":""}]},{"id":"s16-65","number":65,"surah":16,"verses":[36],"references":[{"surah":16,"verses":[36]}],"verseLabel":"النحل: 36","question":"ما دلالة اختيار لفظ ﴿الطَّاغُوتَ﴾؟","answer":"أصل اللفظ من الطغيان، وهو مجاوزة الحد؛ ويُطلق هنا على ما عُبد من دون الله، من صنم أو شيطان ونحوهما، فيجمع صور العبادة الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص401، تحت «الطاغوت والشيطان»","url":""}]},{"id":"s16-66","number":66,"surah":16,"verses":[37],"references":[{"surah":16,"verses":[37]}],"verseLabel":"النحل: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنْ تَحْرِصْ عَلَى هُدَاهُمْ﴾؟","answer":"في الشرط بيان شدة حرص النبي ورأفته بقومه، مع تقرير أن حرصه لا يستقل بتحقيق الهداية؛ فالتوفيق إلى الهدى بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص406، تحت «دلالة التعريض في سياق الشرط»","url":""}]},{"id":"s16-67","number":67,"surah":16,"verses":[38],"references":[{"surah":16,"verses":[38]}],"verseLabel":"النحل: 38","question":"ما دلالة ﴿جَهْدَ أَيْمَانِهِمْ﴾ في قسمهم على نفي البعث؟","answer":"جمعوا القسم وبذل غاية الجهد في توكيد إنكار البعث؛ فتظهر المفارقة في قسمهم بالله على نفي قدرته على الإعادة. ثم تنقض «بلى» نفيهم وتثبت البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص418، تحت «دلالة الجمع بين أقسموا وجهد أيمانهم»","url":""}]},{"id":"s16-68","number":68,"surah":16,"verses":[38],"references":[{"surah":16,"verses":[38]}],"verseLabel":"النحل: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿وَعْدًا عَلَيْهِ حَقًّا﴾؟","answer":"جعل البعث وعدًا تفضل بإيجابه على نفسه، ثم أكده بالحق ليقطع الشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص421، تحت «موقع وعدا ودلالته في الآية الكريمة»","url":""}]},{"id":"s16-69","number":69,"surah":16,"verses":[40],"references":[{"surah":16,"verses":[40]}],"verseLabel":"النحل: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ﴾؟","answer":"يصور التعبير كمال القدرة وسهولة الإيجاد؛ فما أراده الله لا يعجزه ولا يحتاج في إيجاده إلى معالجة أو معين. والمقصود تقرير نفاذ إرادته وقدرته على البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص438، تحت «دلالة القدرة المطلقة في قوله كن فيكون»","url":""}]},{"id":"s16-70","number":70,"surah":16,"verses":[41,42],"references":[{"surah":16,"verses":[41,42]}],"verseLabel":"النحل: 41-42","question":"ما دلالة الجمع بين الهجرة والصبر والتوكل؟","answer":"وُصف المهاجرون بالصبر على أذى المشركين ومفارقة الوطن، وبالتوكل على الله في جميع أمورهم. فجمعوا احتمال المشقة وبذل السبب مع اعتماد القلب على ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص453، تحت «دلالة الجمع بين الصبر والتوكل»","url":""}]},{"id":"s16-71","number":71,"surah":16,"verses":[43],"references":[{"surah":16,"verses":[43]},{"surah":21,"verses":[7]}],"verseLabel":"النحل: 43؛ الأنبياء: 7","question":"ما سرّ الأمر بقوله تعالى في النحل: ﴿فاسألوا أهل الذكر﴾؟","answer":"أحال المنكرين لبشرية الرسل إلى أهل العلم بالكتب السابقة، إلزامًا لهم بما تثبته أخبار الرسل من أنهم بشر يوحى إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص470، تحت «سر الأمر بسؤال أهل الذكر»","url":""}]},{"id":"s16-214","number":214,"surah":16,"verses":[43],"references":[{"surah":16,"verses":[43]},{"surah":21,"verses":[7]}],"verseLabel":"النحل: 43؛ الأنبياء: 7","question":"ما براعة التعبير بـ﴿أهل الذكر﴾ في سورة الأنبياء دون «أهل الكتاب»؟","answer":"اللفظ أعم في وصف أهل العلم بالوحي، فيرشد إلى سؤال العارفين ويوبخ من اتخذ الجهل حجة لإنكار حقيقة معلومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص116، تحت «براعة استعمال أهل الذكر دون أهل الكتاب»","url":""}]},{"id":"s16-72","number":72,"surah":16,"verses":[44],"references":[{"surah":16,"verses":[44]}],"verseLabel":"النحل: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ﴾؟","answer":"جُعل بيان المنزل للناس غايةً من إنزال الذكر على الرسول؛ فمهمته تبليغ ألفاظه وإيضاح معانيه وما يحتاج إليه الناس للعمل به والاهتداء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص483، تحت «دلالة إسناد مهمة التبيين للرسول»","url":""}]},{"id":"s16-73","number":73,"surah":16,"verses":[44],"references":[{"surah":16,"verses":[44]}],"verseLabel":"النحل: 44","question":"ما دلالة ختام الآية بـ﴿لَعَلَّهُمْ يَتَفَكَّرُونَ﴾؟","answer":"البيان يرفع الغموض، ثم يبقى على الناس أن يعملوا الفكر حتى يبلغوا المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص487، تحت «غرض استعمال أداة الرجاء لعل»","url":""}]},{"id":"s16-74","number":74,"surah":16,"verses":[45],"references":[{"surah":16,"verses":[45]}],"verseLabel":"النحل: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ يَخْسِفَ اللَّهُ بِهِمُ الْأَرْضَ﴾؟","answer":"الخسف نوع من العذاب يصير به موضع الاستقرار سببًا للهلاك؛ وفي تخصيصه تهديد لمن اغتروا بالأمن، وتصوير لقدرة الله على أن يذهب بهم في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص496، تحت «سر التنصيص على الخسف»","url":""}]},{"id":"s16-75","number":75,"surah":16,"verses":[46],"references":[{"surah":16,"verses":[46]}],"verseLabel":"النحل: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ يَأْخُذَهُمْ فِي تَقَلُّبِهِمْ﴾؟","answer":"أي أثناء حركتهم في المعاش والسفر؛ العذاب لا يحتاج انتظار سكونهم أو استعدادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص504، تحت «سر استعمال المصدر الصريح تقلبهم»","url":""}]},{"id":"s16-76","number":76,"surah":16,"verses":[47],"references":[{"surah":16,"verses":[47]}],"verseLabel":"النحل: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ يَأْخُذَهُمْ عَلَى تَخَوُّفٍ﴾؟","answer":"أي على تنقص تدريجي أو حال خوف؛ فالعقوبة قد تفجأ وقد تتدرج أمام العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص511، تحت «بلاغة التعبير بالمصدر تخوف»","url":""}]},{"id":"s16-77","number":77,"surah":16,"verses":[47],"references":[{"surah":16,"verses":[47]}],"verseLabel":"النحل: 47","question":"ما سرّ ختام صور الأخذ بـ﴿رَءُوفٌ رَحِيمٌ﴾؟","answer":"لأن الإمهال والتحذير قبل المؤاخذة رأفة ورحمة، لا عجزًا عن الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص514، تحت «دلالة ذكر الرأفة والرحمة بعد ذكر أنواع العذاب»","url":""}]},{"id":"s16-78","number":78,"surah":16,"verses":[48],"references":[{"surah":16,"verses":[48]}],"verseLabel":"النحل: 48","question":"ما دلالة قوله تعالى في الظلال: ﴿يتفيأ﴾ بصيغة المضارع؟","answer":"تصور الصيغة تجدد رجوع الظلال وامتدادها وانقباضها على مدار الزمن وفق تقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص525، تحت «دلالة الصيغة فيء والتعبير عنها بالمضارع»","url":""}]},{"id":"s16-215","number":215,"surah":16,"verses":[48],"references":[{"surah":16,"verses":[48]}],"verseLabel":"النحل: 48","question":"ما بلاغة وصف الظلال بأنها ﴿سجدًا لله﴾؟","answer":"استعير السجود لانقياد الظلال التام لنظام الله، وفيه تعريض بمن يأبى الخضوع مع ظهور دلائله حوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص530، تحت «بلاغة استعارة لفظ السجود لمعنى الانقياد والخضوع»","url":""}]},{"id":"s16-79","number":79,"surah":16,"verses":[48],"references":[{"surah":16,"verses":[48]}],"verseLabel":"النحل: 48","question":"ما سرّ إفراد ﴿الْيَمِينِ﴾ وجمع ﴿الشَّمَائِلِ﴾؟","answer":"من توجيهه أن المفرد يراد به جنس الجهة، والجمع يراعي تعدد أصحاب الظلال؛ وقيل: روعي لفظ «ما» المفرد في اليمين ومعناها المتعدد في الشمائل. فالإفراد والجمع لا يحصران الظلال في شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص527، 528، تحت «سر التفنن بإفراد اليمين وجمع الشمائل»","url":""}]},{"id":"s16-80","number":80,"surah":16,"verses":[49],"references":[{"surah":16,"verses":[49]}],"verseLabel":"النحل: 49","question":"ما دلالة تخصيص الدواب والملائكة بالذكر في سياق السجود؟","answer":"الدواب من ذوات الحس والحركة في الأرض، والملائكة أشرف المخلوقات السماوية؛ فذكرهما يبين خضوع الصنفين لله. وتخصيص الملائكة بعد العموم تشريف لهم وتوكيد لعبوديتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص542، تحت «دلالة تخصيص الدواب والملائكة بالذكر»","url":""}]},{"id":"s16-81","number":81,"surah":16,"verses":[50],"references":[{"surah":16,"verses":[50]}],"verseLabel":"النحل: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿يَخَافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ﴾؟","answer":"من توجيه العبارة أنها تثني على الله بعلو القهر وعظمة السلطان؛ فهم يخافون ربهم العالي القاهر لهم، فيجتمع الخوف والتعظيم مع تمام الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص549، تحت «فائدة التعبير بشبه الجملة من فوقهم»","url":""}]},{"id":"s16-82","number":82,"surah":16,"verses":[50],"references":[{"surah":16,"verses":[50]}],"verseLabel":"النحل: 50","question":"ما دلالة ختام الآية بـ﴿وَيَفْعَلُونَ مَا يُؤْمَرُونَ﴾؟","answer":"بعد نفي الاستكبار أثبت كمال الامتثال العملي؛ خوفهم يثمر طاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص550، تحت «بلاغة الإيجاز في التذييل»","url":""}]},{"id":"s16-83","number":83,"surah":16,"verses":[51],"references":[{"surah":16,"verses":[51]}],"verseLabel":"النحل: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَتَّخِذُوا إِلَهَيْنِ اثْنَيْنِ﴾ مع أن التثنية مفهومة؟","answer":"جاء «اثنين» لبيان أن النهي منصب على التعدد نفسه؛ فليست الألوهية ممنوعة وإنما الشرك فيها. ويقابله ﴿إِنَّمَا هُوَ إِلَهٌ وَاحِدٌ﴾، فيتحدد موضع النفي والإثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص558، تحت «الفائدة من التأكيد بالوصف اثنين»","url":""}]},{"id":"s16-84","number":84,"surah":16,"verses":[52],"references":[{"surah":16,"verses":[52]}],"verseLabel":"النحل: 52","question":"ما فائدة تقديم ﴿له﴾ في قوله تعالى: ﴿وله الدين واصبًا﴾؟","answer":"يفيد قصر الطاعة والعبادة على الله وحده؛ فلا يستحق الدين الدائم سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص574، تحت «فائدة القصر بتقديم شبه الجملة في وله الدين»","url":""}]},{"id":"s16-216","number":216,"surah":16,"verses":[52],"references":[{"surah":16,"verses":[52]}],"verseLabel":"النحل: 52","question":"ما دلالة وصف الدين بقوله: ﴿واصبًا﴾؟","answer":"الكلمة كناية عن الدوام والثبات؛ فطاعة الله لا تنقطع وسلطانه لا يزول كما تزول طاعة غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص575، تحت «بلاغة الكناية في كلمة واصبا»","url":""}]},{"id":"s16-85","number":85,"surah":16,"verses":[53],"references":[{"surah":16,"verses":[53]}],"verseLabel":"النحل: 53","question":"ما دلالة تنكير ﴿نعمة﴾ في قوله: ﴿وما بكم من نعمة﴾؟","answer":"وقعت النكرة في سياق العموم لتشمل كل نعمة ظاهرة وباطنة، صغيرة وكبيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص584، تحت «دلالة تنكير نعمة»","url":""}]},{"id":"s16-217","number":217,"surah":16,"verses":[53],"references":[{"surah":16,"verses":[53]}],"verseLabel":"النحل: 53","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿فمن الله﴾؟","answer":"تفيد ابتداء صدور النعم كلها من الله، فترد كل نعمة إلى المنعم وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص585، تحت «نوع من ودلالتها»","url":""}]},{"id":"s16-86","number":86,"surah":16,"verses":[53],"references":[{"surah":16,"verses":[53]}],"verseLabel":"النحل: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿تَجْأَرُونَ﴾ لا تدعون؟","answer":"الجؤار رفع الصوت بالتضرع والاستغاثة؛ فيصور شدة افتقارهم عند الضر، وتقديم «إليه» يبين أنهم حينئذ يخصون الله باللجوء إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص580، تحت «شرح المفردات تجأرون»","url":""}]},{"id":"s16-87","number":87,"surah":16,"verses":[54],"references":[{"surah":16,"verses":[54]}],"verseLabel":"النحل: 54","question":"ما دلالة ﴿إذا﴾ في قوله: ﴿إذا فريق منكم بربهم يشركون﴾؟","answer":"تفيد المفاجأة، فتكشف سرعة انقلاب فريق منهم إلى الشرك بعد أن يكشف الله عنهم الضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص592، تحت «دلالة إذا الفجائية وفائدتها»","url":""}]},{"id":"s16-218","number":218,"surah":16,"verses":[54],"references":[{"surah":16,"verses":[54]}],"verseLabel":"النحل: 54","question":"ما بلاغة تقديم ﴿بربهم﴾ في قوله: ﴿بربهم يشركون﴾؟","answer":"يفظع المقابلة؛ فهم يشركون بالرب الذي رباهم بالنعم وكشف عنهم الضر، فقدم المتعلق لإبراز قبح فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص593، تحت «بلاغة تقديم بربهم على يشركون»","url":""}]},{"id":"s16-88","number":88,"surah":16,"verses":[56],"references":[{"surah":16,"verses":[56]}],"verseLabel":"النحل: 56","question":"ما سرّ التعبير بـ﴿ما﴾ في قوله: ﴿ويجعلون لما لا يعلمون نصيبًا﴾؟","answer":"تشير ﴿ما﴾ إلى أصنام لا تعقل ولا تستحق شيئًا، ومع ذلك يجعلون لها نصيبًا من رزق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص611، تحت «سر التعبير بما»","url":""}]},{"id":"s16-219","number":219,"surah":16,"verses":[56],"references":[{"surah":16,"verses":[56]}],"verseLabel":"النحل: 56","question":"ما دلالة حذف مفعول ﴿يعلمون﴾ في الآية؟","answer":"يعمم جهلهم؛ فلا يعلمون حقيقة معبوداتهم ولا دليلًا على استحقاقها العبادة أو النصيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص612، تحت «دلالة حذف مفعول يعلمون»","url":""}]},{"id":"s16-89","number":89,"surah":16,"verses":[57],"references":[{"surah":16,"verses":[57]}],"verseLabel":"النحل: 57","question":"ما سرّ التعبير في قوله تعالى عن نسبة البنات: ﴿سُبْحَانَهُ﴾؟","answer":"قطع الحكاية بتنزيه فوري قبل ذكر ما يشتهون لأنفسهم، فظهرت بشاعة القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص624، تحت «بلاغة الاعتراض بقوله سبحانه»","url":""}]},{"id":"s16-90","number":90,"surah":16,"verses":[58],"references":[{"surah":16,"verses":[58]}],"verseLabel":"النحل: 58","question":"ما سرّ التعبير بالفعل ﴿ظل﴾ في قوله: ﴿ظل وجهه مسودًا﴾؟","answer":"يصور استمرار حال الكآبة والغم ملازمة له عند بشارته بالأنثى، لا مجرد تغير عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص634، تحت «سر اختيار التعبير بالفعل ظل»","url":""}]},{"id":"s16-220","number":220,"surah":16,"verses":[58],"references":[{"surah":16,"verses":[58]}],"verseLabel":"النحل: 58","question":"ما بلاغة وصف الوجه بأنه ﴿مسودًا﴾؟","answer":"هو كناية عن شدة الغم والحزن، حتى ظهر أثر ما في النفس على الوجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص635، تحت «بلاغة الكناية في قوله مسودا»","url":""}]},{"id":"s16-91","number":91,"surah":16,"verses":[59],"references":[{"surah":16,"verses":[59]}],"verseLabel":"النحل: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿يَتَوَارَى مِنَ الْقَوْمِ﴾؟","answer":"التواري تكلف الاختفاء، يصور العار الاجتماعي الذي صنعوه ثم أساؤوا الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص644، تحت «سر التعبير بالمواراة دون الاختفاء»","url":""}]},{"id":"s16-92","number":92,"surah":16,"verses":[60],"references":[{"surah":16,"verses":[60]}],"verseLabel":"النحل: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ مَثَلُ السَّوْءِ﴾؟","answer":"«مثل السوء» وصف النقص والقبح الذي استحقوه بأفعالهم؛ وقوبل به المثل الأعلى المختص بالله، أي كمال صفاته وتنزهه عما نسبوه إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص662، تحت «سر التعبير بالمثل»","url":""}]},{"id":"s16-93","number":93,"surah":16,"verses":[61],"references":[{"surah":16,"verses":[61]}],"verseLabel":"النحل: 61","question":"ما دلالة تقييد الإمهال بـ﴿إِلَى أَجَلٍ مُسَمًّى﴾؟","answer":"الإمهال تأخير إلى غاية محددة، وليس تركًا للمحاسبة. و«مسمى» يدل على أجل عيّنه الله وحدده، وإن خفي وقته على الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص679، تحت «دلالة وصف الأجل بقوله مسمى»","url":""}]},{"id":"s16-94","number":94,"surah":16,"verses":[62],"references":[{"surah":16,"verses":[62]}],"verseLabel":"النحل: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ﴾؟","answer":"الموصول يعم ما يكرهونه لأنفسهم من أحوال وخصال، كالبنات والشركاء والاستخفاف؛ فذكره بهذا الوصف يكشف تناقضهم في نسبة تلك الأمور إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص687، تحت «دلالة الموصول في ما يكرهون»","url":""}]},{"id":"s16-95","number":95,"surah":16,"verses":[63],"references":[{"surah":16,"verses":[63]}],"verseLabel":"النحل: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿تَاللَّهِ لَقَدْ أَرْسَلْنَا﴾؟","answer":"يثبت القسم إرسال الرسل إلى الأمم السابقة، وفيه تسلية للنبي: ما يلقاه من التكذيب قد لقيه الرسل قبله؛ فليس وحيدًا في مواجهة إعراض قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص697، تحت «موقع جملة القسم تالله لقد مما قبلها»","url":""}]},{"id":"s16-96","number":96,"surah":16,"verses":[63],"references":[{"surah":16,"verses":[63]}],"verseLabel":"النحل: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿فَزَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ﴾؟","answer":"التزيين تحسين الباطل في نظر أصحابه حتى يتعلقوا به؛ وذكر الشيطان ظاهرًا ينبه إلى مصدر هذا التضليل، في مقابلة الرسل الذين يكشفون قبح الأعمال ويدعون إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص701، تحت «بلاغة إظهار الفاعل»","url":""}]},{"id":"s16-97","number":97,"surah":16,"verses":[64],"references":[{"surah":16,"verses":[64]}],"verseLabel":"النحل: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا لِتُبَيِّنَ لَهُمُ الَّذِي اخْتَلَفُوا فِيهِ﴾؟","answer":"القصر يبرز الغاية العظمى من التنزيل: بيان الحق فيما اختلفوا فيه، لا استيعاب كل فوائده في هذه العبارة وحدها. ومن هذا البيان تكون الهداية والرحمة للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص712، تحت «بلاغة أسلوب القصر»","url":""}]},{"id":"s16-98","number":98,"surah":16,"verses":[65],"references":[{"surah":16,"verses":[65]}],"verseLabel":"النحل: 65","question":"ما سرّ ختام آية إحياء الأرض بـ﴿لِقَوْمٍ يَسْمَعُونَ﴾؟","answer":"المراد سماع تدبر وقبول؛ فالعبرة بإحياء الأرض لا ينتفع بها من يسمع الألفاظ ثم يعرض عن دلالتها. وذكر السماع يعرض بالغافلين الذين لم يستجيبوا للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص728، تحت «بلاغة الكناية في لقوم يسمعون»","url":""}]},{"id":"s16-99","number":99,"surah":16,"verses":[66],"references":[{"surah":16,"verses":[66]}],"verseLabel":"النحل: 66","question":"ما دلالة الجمع بين الفرث والدم واللبن؟","answer":"موضع العبرة خروج اللبن خالصًا سائغًا، مع أن منشأه في باطن الأنعام بين الفرث والدم؛ فلا يحمل لون الدم ولا رائحة الفرث. فالمقابلة تبرز صفاء النعمة وعجيب القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص741، تحت «غرض الترتيب في من بين فرث ودم»","url":""}]},{"id":"s16-100","number":100,"surah":16,"verses":[67],"references":[{"surah":16,"verses":[67]}],"verseLabel":"النحل: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾؟","answer":"خُصّ الرزق بوصف الحسن دون السَّكَر؛ وفي المقابلة تنبيه إلى اختلاف ما يصنعه الناس من الثمرات. وعلى تفسير السَّكَر بالمسكر، تتضمن العبارة تعريضًا بعدم حسنه، ولو كان نزولها قبل تحريمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص750، تحت «سر تقييد «ورزقًا حسنًا» دون السكر»","url":""}]},{"id":"s16-101","number":101,"surah":16,"verses":[68],"references":[{"surah":16,"verses":[68]}],"verseLabel":"النحل: 68","question":"ما نكتة الانتقال إلى قوله: ﴿وأوحى ربك إلى النحل﴾ في سياق النعم؟","answer":"انتقل السياق من تعداد النعم العامة إلى مشهد تفصيلي عجيب في خلق النحل وهدايته، ليستدل القارئ من دقة الصنعة على المنعم وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص757، تحت «نكتة تغيير أسلوب التذكير بالنعم»","url":""}]},{"id":"s16-221","number":221,"surah":16,"verses":[68],"references":[{"surah":16,"verses":[68]}],"verseLabel":"النحل: 68","question":"ما دلالة الفعل ﴿أوحى﴾ في هداية النحل؟","answer":"يدل على إلهام خفي سريع أودعه الله في فطرة النحل، فصدر نظامه الدقيق من تسخير وهداية لا من تعليم بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص758، تحت «دلالة الفعل أوحى مادة وصيغة»","url":""}]},{"id":"s16-222","number":222,"surah":16,"verses":[68],"references":[{"surah":16,"verses":[68]}],"verseLabel":"النحل: 68","question":"ما دلالة قوله ﴿ربك﴾ في آية النحل؟","answer":"إضافة الرب إلى النبي تستحضر عناية المربي ومدبر الخلق، وتصل نعمة هداية النحل برسالة التذكير التي يخاطب بها النبي قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص758، تحت «دلالة الإضافة في قوله ربك»","url":""}]},{"id":"s16-102","number":102,"surah":16,"verses":[68],"references":[{"surah":16,"verses":[68]}],"verseLabel":"النحل: 68","question":"ما سرّ خطاب النحل بصيغة المؤنث في قوله تعالى: ﴿اتَّخِذِي﴾؟","answer":"أُنّث ضمير الخطاب في «اتخذي» لأن النحل جمع نحلة، فناسبه التأنيث. فالتوجيه المذكور هنا لغوي متعلق باسم الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص759، تحت «بلاغة التأنيث في ضمير الخطاب»","url":""}]},{"id":"s16-103","number":103,"surah":16,"verses":[68],"references":[{"surah":16,"verses":[68]}],"verseLabel":"النحل: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿اتَّخِذِي مِنَ الْجِبَالِ بُيُوتًا وَمِنَ الشَّجَرِ وَمِمَّا يَعْرِشُونَ﴾؟","answer":"قدّمت الجبال لأن أكثر بيوت النحل تكون فيها، ثم الشجر، ثم ما يبنيه الناس؛ ففي الترتيب مراعاة لكثرة هذه المساكن. ويذكر المصدر أيضًا وجهًا يتعلق بتفاوت مراتب العسل بحسب مواضع بيوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص761، 762، تحت «نكتة الترتيب في أماكن الاتخاذ الثلاثة»","url":""}]},{"id":"s16-104","number":104,"surah":16,"verses":[69],"references":[{"surah":16,"verses":[69]}],"verseLabel":"النحل: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلِي مِنْ كُلِّ الثَّمَرَاتِ﴾ مع أنها لا تأكل الثمار كلها؟","answer":"«مِن» للتبعيض؛ فالمعنى أن تأخذ مما تشتهي من الثمرات، لا أن يلزمها استيعاب كل ثمرة. وأُطلقت الثمرات على الأزهار باعتبار ما تؤول إليه؛ إذ تصير الأزهار ثمرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص762، 763، تحت «دلالة حرف الجر «مِنْ» في «مِنْ كُلِّ الثَّمَرَاتِ»؛ بلاغة إطلاق الثمرات على الزهور»","url":""}]},{"id":"s16-105","number":105,"surah":16,"verses":[69],"references":[{"surah":16,"verses":[69]}],"verseLabel":"النحل: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاسْلُكِي سُبُلَ رَبِّكِ ذُلُلًا﴾؟","answer":"جمع السبل يشعر بكثرتها وتنوعها، وإضافتها إلى الرب تذكّر بأنه خالقها والمهيّئ لسلوكها. و«ذللًا» في التوجيه المذكور حال من النحل: تسلك منقادة مذللة، وذلك من آثار تسخير الله لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص763، 764، تحت «نكتة التعبير بـ«السبل» جمعًا؛ سر إضافة السبل إلى «ربك»؛ سر تقييد الفعل بالحال «ذللًا»»","url":""}]},{"id":"s16-106","number":106,"surah":16,"verses":[69],"references":[{"surah":16,"verses":[69]}],"verseLabel":"النحل: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿يَخْرُجُ مِنْ بُطُونِهَا شَرَابٌ﴾، دون أن يقال عسل؟","answer":"اختير اسم الجنس «شراب» لإبراز جهة الانتفاع بالعسل، وهو ما يتصل بقوله بعده: ﴿فِيهِ شِفَاءٌ لِلنَّاسِ﴾. وسُمّي شرابًا لأنه مائع يُشرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص766، تحت «سرّ التعبير عن العسل بالشراب»","url":""}]},{"id":"s16-107","number":107,"surah":16,"verses":[69],"references":[{"surah":16,"verses":[69]}],"verseLabel":"النحل: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿مُخْتَلِفٌ أَلْوَانُهُ﴾؟","answer":"الجملة صفة للشراب، وتلفت إلى تنوع ألوان العسل مع خروجه من هذا المخلوق الضعيف؛ فيكون اختلافه نفسه موضع اعتبار بقدرة الله وإنعامه، فضلًا عن نفعه غذاءً وشفاءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص767، تحت «دلالة موقع قوله «مختلف ألوانه»»","url":""}]},{"id":"s16-108","number":108,"surah":16,"verses":[69],"references":[{"surah":16,"verses":[69]}],"verseLabel":"النحل: 69","question":"ما سرّ ختم آية النحل بقوله تعالى: ﴿لِقَوْمٍ يَتَفَكَّرُونَ﴾؟","answer":"لأن الاعتبار بنظام النحل وما يخرج منه يحتاج إلى إعمال فكر دقيق في أحواله العجيبة. والمضارع يناسب تجدد التفكر كلما تجددت مشاهدة هذه النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص771، 772، تحت «دلالة المضارع «يتفكرون» مادة وصيغة»","url":""}]},{"id":"s16-109","number":109,"surah":16,"verses":[70],"references":[{"surah":16,"verses":[70]}],"verseLabel":"النحل: 70","question":"ما غرض تقديم اسم الله في قوله: ﴿والله خلقكم ثم يتوفاكم﴾؟","answer":"يقرر اختصاص الله بالخلق والتوفي، ويرد النعمتين وتدبير العمر كله إلى فاعل واحد لا شريك له.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص776، تحت «غرض تقديم المسند إليه»","url":""}]},{"id":"s16-223","number":223,"surah":16,"verses":[70],"references":[{"surah":16,"verses":[70]}],"verseLabel":"النحل: 70","question":"ما دلالة ﴿ثم﴾ في قوله: ﴿ثم يتوفاكم﴾؟","answer":"تفيد تراخي الوفاة عن الخلق وامتداد أطوار الحياة بينهما، فتوجز الرحلة الإنسانية من البدء إلى الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص777، تحت «دلالة «ثم» في قوله «ثم يتوفاكم»»","url":""}]},{"id":"s16-110","number":110,"surah":16,"verses":[70],"references":[{"surah":16,"verses":[70]}],"verseLabel":"النحل: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿أَرْذَلِ الْعُمُرِ﴾؟","answer":"أُضيف الوصف إلى العمر، والمقصود حال الإنسان في مرحلة الهرم وضعف القوى؛ فالمدة نفسها لا توصف بالشرف أو الخسة. ونسبة الرذالة إلى العمر مجاز عقلي يبرز ما قد يصيب الإنسان فيه من ضعف بعد قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص779، تحت «بلاغة المجاز العقلي في قوله «أرذل العمر»»","url":""}]},{"id":"s16-111","number":111,"surah":16,"verses":[71],"references":[{"surah":16,"verses":[71]}],"verseLabel":"النحل: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا الَّذِينَ فُضِّلُوا بِرَادِّي رِزْقِهِمْ﴾؟","answer":"يضرب السياق مثلًا يبطل التسوية بين الله وغيره: فالذين فُضّلوا في الرزق لا يجعلون مماليكهم شركاء مساويين لهم فيه، فكيف يجعلون لله شركاء من خلقه؟ والمقصود إلزامهم بما لا يرضونه لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص791، 792، تحت «بلاغة التشبيه الضمني التمثيلي في قوله «فما الذين فضلوا»»","url":""}]},{"id":"s16-112","number":112,"surah":16,"verses":[72],"references":[{"surah":16,"verses":[72]},{"surah":30,"verses":[21]}],"verseLabel":"النحل: 72؛ الروم: 21","question":"ما معنى قوله تعالى: ﴿من أنفسكم أزواجًا﴾؟","answer":"أي من جنسكم الإنساني؛ فالمجانسة أدعى إلى الألفة والتفاهم، وهي من تمام نعمة الله على الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص16، تحت «معنى الأنفسية في قوله «من أنفسكم»»","url":""}]},{"id":"s16-224","number":224,"surah":16,"verses":[72],"references":[{"surah":16,"verses":[72]},{"surah":30,"verses":[21]}],"verseLabel":"النحل: 72؛ الروم: 21","question":"ما الصورة في قوله تعالى: ﴿لتسكنوا إليها﴾؟","answer":"صور طمأنينة الزوج إلى زوجه بسكون المضطرب إلى موضع أمنه، فدل على الراحة النفسية والألفة العميقة في هذه الصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص136، تحت «بلاغة الاستعارة في «لتسكنوا»»","url":""}]},{"id":"s16-113","number":113,"surah":16,"verses":[72],"references":[{"surah":16,"verses":[72]}],"verseLabel":"النحل: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿بَنِينَ وَحَفَدَةً﴾؟","answer":"العطف يبرز تنوع النعمة وتكاملها. ومن التوجيهات المذكورة تفسير الحفدة بمن يسرع في المعونة والخدمة؛ فتجتمع نعمة البنوة ونعمة العون. وقُدّم البنون للاهتمام بهم ومباشرة الصلة بهم، ثم ذُكر الحفدة لاتساع النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص20، تحت «دلالة العطف والترتيب في «بنين وحفدة»»","url":""}]},{"id":"s16-114","number":114,"surah":16,"verses":[73],"references":[{"surah":16,"verses":[73]}],"verseLabel":"النحل: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿عَبْدًا مَمْلُوكًا لَا يَقْدِرُ عَلَى شَيْءٍ﴾؟","answer":"«مملوك» يعيّن المراد بالعبد، لأن العبودية لله تشمل البشر جميعًا. ثم يزيد وصفُه بالعجز الصورةَ وضوحًا؛ فالمثل يقابل العاجز الذي لا يملك التصرف بمن رزقه الله قدرة على الإنفاق، لإبطال التسوية بين الله والمعبودات العاجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص64، 66، تحت «سر تقييد العبد بالوصف بلفظ «مملوك»؛ علة وصف العبد المملوك بأنه «لا يقدر على شيء»»","url":""}]},{"id":"s16-115","number":115,"surah":16,"verses":[75],"references":[{"surah":16,"verses":[75]}],"verseLabel":"النحل: 75","question":"ما دلالة مقابلة الأبكم بمن يأمر بالعدل في مثل سورة النحل؟","answer":"يجمع المثل صفات العجز وعدم النفع، ويقابلها بمن يأمر بالعدل ويسير على صراط مستقيم. ثم ينكر الاستفهام التسوية بينهما؛ ليظهر بطلان التسوية بين المعبود العاجز والخالق القادر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص91، 92، 99، تحت «سر وصفه بالبكم بلفظ «أبكم»؛ سر وصفه بأنه «لا يقدر على شيء»؛ بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s16-116","number":116,"surah":16,"verses":[77],"references":[{"surah":16,"verses":[77]}],"verseLabel":"النحل: 77","question":"ما سرّ تقديم غيب السماوات والأرض قبل أمر الساعة؟","answer":"ينتقل السياق من عموم الغيب الذي يختص الله بعلمه إلى الساعة، وهي من أعظم ما جادلوا فيه من الغيب. ثم يبيّن سهولة إقامتها على الله، فيجتمع الاستدلال بكمال العلم وشمول القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص118، 119، تحت «دلالة الواو في قوله «وما أمر الساعة»؛ سر تخصيص الساعة بالذكر»","url":""}]},{"id":"s16-117","number":117,"surah":16,"verses":[77],"references":[{"surah":16,"verses":[77]}],"verseLabel":"النحل: 77","question":"ما سرّ التعبير في قوله تعالى في الساعة: ﴿كَلَمْحِ الْبَصَرِ أَوْ هُوَ أَقْرَبُ﴾؟","answer":"يشبّه وقوع الساعة بلمح البصر لتقريب سرعة حصولها وسهولتها على الله. ومن توجيهات «أو هو أقرب» الترقي في تصوير السرعة؛ فلا ينحصر المقصود في مقدار لمح البصر، بل الأمر أهون وأسرع عند تعلق الإرادة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص121، 122، 123، تحت «بلاغة التشبيه في قوله «كلمح البصر»؛ دلالة «أو» في قوله «أو هو أقرب»»","url":""}]},{"id":"s16-118","number":118,"surah":16,"verses":[77],"references":[{"surah":16,"verses":[77]}],"verseLabel":"النحل: 77","question":"ما سرّ تخصيص الساعة بالذكر بعد غيب السماوات والأرض؟","answer":"لأن الساعة كانت موضع إنكار وجدال، فناسب إفرادها بعد ذكر الغيب. وإقامتها وبعث الأجساد بعد موتها من أعظم ما يدل على تمام علم الله وشمول قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص119، تحت «سر تخصيص الساعة بالذكر»","url":""}]},{"id":"s16-119","number":119,"surah":16,"verses":[78],"references":[{"surah":16,"verses":[78]}],"verseLabel":"النحل: 78","question":"ما سرّ تقديم السمع على الأبصار والأفئدة؟","answer":"من وجوه التقديم أن السمع طريق تلقي الوحي، وله منزلة عظيمة في تحصيل العلم وفهم الرسالة. ثم ذُكر البصر، وجُعلت الأفئدة خاتمة هذه الوسائل لأن بها الوعي والحفظ؛ فيناسب الترتيب سياقَ الامتنان بأدوات المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص141، 142، تحت «بلاغة الترتيب بين «السمع والأبصار والأفئدة»»","url":""}]},{"id":"s16-120","number":120,"surah":16,"verses":[79],"references":[{"surah":16,"verses":[79]}],"verseLabel":"النحل: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿مُسَخَّرَاتٍ فِي جَوِّ السَّمَاءِ﴾؟","answer":"وصف الطير بالتسخير يوجّه النظر إلى ما هيّأه الله لها من أسباب الطيران. وذكر جو السماء يصوّر ارتفاعها في فضاء بعيد عن الأرض، فيزداد ظهور دلالة القدرة في بقائها محلّقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص154، 155، 156، تحت «سر التقييد بالحال في «مسخرات»؛ سر إضافة الجو إلى السماء في السياق؛ سر التعبير بلفظ «مسخرات» وأثره في المعنى»","url":""}]},{"id":"s16-121","number":121,"surah":16,"verses":[79],"references":[{"surah":16,"verses":[79]}],"verseLabel":"النحل: 79","question":"ما دلالة القصر في قوله: ﴿ما يمسكهن إلا الله﴾؟","answer":"يقصر إمساك الطير في الجو على قدرة الله وتسخيره، فينفي استقلال الأسباب الظاهرة بهذا النظام العجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص157، تحت «بلاغة أسلوب القصر ونوعه في السياق»","url":""}]},{"id":"s16-225","number":225,"surah":16,"verses":[79],"references":[{"surah":16,"verses":[79]}],"verseLabel":"النحل: 79","question":"لماذا عبّر عن بقاء الطير في الجو بالإمساك؟","answer":"صور حفظها من السقوط كأن قدرة الله تمسكها، فأبرز استمرار العناية والتسخير في كل لحظة من طيرانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص158، تحت «نكتة التعبير بالإمساك مادة وصيغة»","url":""}]},{"id":"s16-122","number":122,"surah":16,"verses":[80],"references":[{"surah":16,"verses":[80]}],"verseLabel":"النحل: 80","question":"ما سرّ وصف البيوت بأنها ﴿سَكَنًا﴾؟","answer":"ينقل التعبير النظر من بناء البيت إلى غايته: الراحة والقرار والطمأنينة، وسكون الجوارح عن الحركة والاضطراب؛ فيبرز النعمة التي يجدها الإنسان في مسكنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص176، تحت «دلالة التعبير بـ«سكنًا»»","url":""}]},{"id":"s16-123","number":123,"surah":16,"verses":[81],"references":[{"surah":16,"verses":[81]}],"verseLabel":"النحل: 81","question":"لماذا اكتفى بذكر الحر في ﴿سَرَابِيلَ تَقِيكُمُ الْحَرَّ﴾ ولم يذكر البرد؟","answer":"هذا من الاكتفاء بذكر أحد المتقابلين، لدلالة السياق على أن الملابس تقي الحر والبرد. وخصّ الحر بالذكر لمناسبة حال المخاطبين الذين يغلب عليهم العيش في بلاد حارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص197، 198، تحت «بلاغة الاكتفاء في قوله «تقيكم الحر»»","url":""}]},{"id":"s16-124","number":124,"surah":16,"verses":[81],"references":[{"surah":16,"verses":[81]}],"verseLabel":"النحل: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿سَرَابِيلَ تَقِيكُمْ بَأْسَكُمْ﴾؟","answer":"المراد هنا الدروع وما يُلبس لاتقاء أذى الحرب، بعد ذكر الملابس الواقية من الحر. وإضافة البأس إلى المخاطبين تشير إلى بأس بعضهم على بعض؛ فتتعدد جهات النعمة بين الوقاية في المعيشة والوقاية في القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص199، 200، تحت «فائدة تكرار لفظتي «سرابيل تقيكم»؛ فائدة الإضافة في قوله «بأسكم»»","url":""}]},{"id":"s16-125","number":125,"surah":16,"verses":[83],"references":[{"surah":16,"verses":[83]}],"verseLabel":"النحل: 83","question":"لماذا قال: ﴿يعرفون نعمت الله﴾ ولم يقل يعلمونها؟","answer":"المعرفة تدل على ظهور النعمة وتميزها لديهم بعد إدراك آثارها، فلا يبقى إنكارهم ناشئًا عن خفاء أو جهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص215، تحت «سر اختيار فعل المعرفة»","url":""}]},{"id":"s16-226","number":226,"surah":16,"verses":[83],"references":[{"surah":16,"verses":[83]}],"verseLabel":"النحل: 83","question":"ما أثر ﴿ثم﴾ في قوله: ﴿ثم ينكرونها﴾؟","answer":"تفيد الاستبعاد والتراخي الرتبي؛ إذ كان مقتضى معرفتهم النعمة أن يشكروها، فجاء الإنكار بعدها أشد قبحًا وعجبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص216، تحت «أثر حرف العطف «ثم»»","url":""}]},{"id":"s16-126","number":126,"surah":16,"verses":[84],"references":[{"surah":16,"verses":[84]}],"verseLabel":"النحل: 84","question":"ما دلالة قوله تعالى: ﴿مِنْ كُلِّ أُمَّةٍ شَهِيدًا﴾؟","answer":"تقديم ﴿مِنْ كُلِّ أُمَّةٍ﴾ يفيد أن لكل أمة شهيدها المختص بها. وهو نبيها الذي يشهد عليها، فتظهر دقة إقامة الحجة على الأمم بما بلغها من رسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص225، 226، تحت «فائدة تقديم الجار والمجرور «من كل»؛ لطيفة استعمال لفظ الشهادة في «شهيدًا»»","url":""}]},{"id":"s16-127","number":127,"surah":16,"verses":[86],"references":[{"surah":16,"verses":[86]}],"verseLabel":"النحل: 86","question":"ما دلالة التناسب بين ﴿أَشْرَكُوا﴾ و﴿شُرَكَاءَهُمْ﴾ في قوله تعالى: ﴿وَإِذَا رَأَى الَّذِينَ أَشْرَكُوا شُرَكَاءَهُمْ﴾؟","answer":"بين «أشركوا» و«شركاءهم» جناس اشتقاق يربط اللفظين ويؤكد نسبة الشرك إليهم. فهذه المعبودات لا تستحق الشركة لله، وإنما صارت شركاء في زعم عابديها؛ وبذلك يكشف التعبير فساد اعتقادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص245، تحت «علة الجناس في قوله «أشركوا شركاءهم»»","url":""}]},{"id":"s16-128","number":128,"surah":16,"verses":[88],"references":[{"surah":16,"verses":[88]}],"verseLabel":"النحل: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿زِدْنَاهُمْ عَذَابًا فَوْقَ الْعَذَابِ﴾؟","answer":"الزيادة تناسب اجتماع الكفر والصد عن سبيل الله: لم يقتصروا على ضلال أنفسهم، بل سعوا في إضلال غيرهم. فكانت زيادة العذاب مقابلة لزيادة جرمهم وإفسادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص265، تحت «دلالة الإخبار عن زيادة العذاب للكافرين»","url":""}]},{"id":"s16-129","number":129,"surah":16,"verses":[88],"references":[{"surah":16,"verses":[88]}],"verseLabel":"النحل: 88","question":"ما سرّ ختم الآية بقوله ﴿بِمَا كَانُوا يُفْسِدُونَ﴾ دون «يكفرون»؟","answer":"لأن سبب زيادة العذاب هنا إفسادهم بإضلال الناس والصد عن سبيل الله، لا مجرد كفرهم. فلفظ الفساد يبيّن الجرم المتعدي الذي استحقوا بسببه هذه الزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص267، تحت «إيثار التعبير بلفظ الفساد دون الكفر في فاصلة الآية»","url":""}]},{"id":"s16-130","number":130,"surah":16,"verses":[89],"references":[{"surah":16,"verses":[89]}],"verseLabel":"النحل: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ﴾ بصيغة نزّل؟","answer":"التضعيف في «نزّلنا» يناسب التدرج والتنجيم؛ فقد نزل القرآن مفرّقًا بحسب الحوادث وما تقتضيه الحكمة. فالصيغة تلائم كيفية نزوله شيئًا بعد شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص275، 276، تحت «سر استعمال صيغة «نزّل» دون «أنزل»»","url":""}]},{"id":"s16-131","number":131,"surah":16,"verses":[89],"references":[{"surah":16,"verses":[89]}],"verseLabel":"النحل: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿تِبْيَانًا﴾ لا بيانًا؟","answer":"يفيد «تبيانًا» في هذا السياق المبالغة في البيان؛ فالكتاب منزل لإيضاح ما يحتاج إليه الناس في هدايتهم وأمر دينهم. وجاء المصدر مؤكدًا لوظيفته في البيان والكشف.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص277، تحت «إيثار لفظ «تبيانًا» دون «بيانًا»»","url":""}]},{"id":"s16-132","number":132,"surah":16,"verses":[89],"references":[{"surah":16,"verses":[89]}],"verseLabel":"النحل: 89","question":"ما سرّ ترتيب أوصاف الكتاب: تبيانًا وهدى ورحمة وبشرى؟","answer":"يتدرج الترتيب من التبيان الذي تقوم به الهداية، إلى الهدى الذي تتحقق به الرحمة، ثم البشرى التي يتقدم بها الإخبار بما يسرّ المؤمنين. فالأوصاف مترابطة بحسب آثارها وغاياتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص278، 279، تحت «علة ترتيب المعاني الواصفة للكتاب»","url":""}]},{"id":"s16-133","number":133,"surah":16,"verses":[90],"references":[{"surah":16,"verses":[90]}],"verseLabel":"النحل: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ﴾؟","answer":"ذكر اسم الجلالة يضفي على الأمر مهابة وتعظيمًا، لأنه أمر المستحق للكمال. وقُدّم العدل الذي يقوم به أداء الواجب، ثم الإحسان الذي يتجاوزه إلى الفضل؛ فيترقى السياق من القدر اللازم إلى الزيادة في الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص284، 287، 288، تحت «إيثار استعمال الاسم الأحسن «الله» دون اسم الله «الرب»؛ سر ترتيب المأمورات في الآية»","url":""}]},{"id":"s16-134","number":134,"surah":16,"verses":[90],"references":[{"surah":16,"verses":[90]}],"verseLabel":"النحل: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿ذِي الْقُرْبَى﴾ بالإفراد؟","answer":"الإفراد يجعل الخطاب متناولًا كل ذي قرابة على حدة؛ فيتوجه الاعتناء إلى كل فرد، ولا يكتفى بالنظر إلى الأقارب باعتبارهم جماعة. وهذا أدعى إلى توثيق صلة الأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص289، تحت «سر إفراد «ذي»»","url":""}]},{"id":"s16-135","number":135,"surah":16,"verses":[90],"references":[{"surah":16,"verses":[90]}],"verseLabel":"النحل: 90","question":"ما دلالة الجمع بين الفحشاء والمنكر والبغي؟","answer":"الفحشاء ما عظم قبحه، وعطف المنكر يوسّع النهي ليشمل ما يُنكر من المعاصي عمومًا. ثم خُصّ البغي، وهو التجاوز والعدوان، بالذكر اهتمامًا بالنهي عنه؛ وفي مقابلته للعدل تأكيد لقبح الاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص291، 292، 293، تحت «سر إيثار لفظ «الفحشاء» دون «الفاحشة» أو «الفواحش»؛ دلالة عطف «المنكر» على «الفحشاء»؛ إيثار لفظ «البغي» دون لفظ «الظلم»»","url":""}]},{"id":"s16-136","number":136,"surah":16,"verses":[90],"references":[{"surah":16,"verses":[90]}],"verseLabel":"النحل: 90","question":"ما سرّ ختم آية العدل والإحسان بقوله تعالى: ﴿لَعَلَّكُمْ تَذَكَّرُونَ﴾؟","answer":"لأن فضل هذه المأمورات وقبح هذه المنهيات مما تدركه النفوس ولا يحتاج إلى بحث خفي. فناسب الحث على استحضارها والتذكر بها؛ إذ يدعو ذلك إلى الامتثال وترك القبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص294، 295، تحت «إيثار لفظ «التذكر» دون غيره»","url":""}]},{"id":"s16-137","number":137,"surah":16,"verses":[91],"references":[{"surah":16,"verses":[91]}],"verseLabel":"النحل: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَنْقُضُوا الْأَيْمَانَ﴾ لا تنكثوا؟","answer":"النقض يستعمل في حلّ البناء والحبل والعقد بعد إحكامها، فاستعير لإبطال العهد. وهو أنسب هنا لتعظيم جناية الإخلال بالأيمان بعد توكيدها، في مقابل الأمر بالوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص307، تحت «سر إيثار لفظ النقض دون النكث»","url":""}]},{"id":"s16-138","number":138,"surah":16,"verses":[91],"references":[{"surah":16,"verses":[91]}],"verseLabel":"النحل: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقَدْ جَعَلْتُمُ اللَّهَ عَلَيْكُمْ كَفِيلًا﴾؟","answer":"تقديم «عليكم» يخصّ المخاطبين بهذه الشهادة: أنتم الذين استشهدتم بالله على أنفسكم حين حلفتم. وفي ذلك تهويل لنقض اليمين وتذكير بما ألزموا به أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص309، 310، تحت «سر تقديم الجار والمجرور «عليكم» على المفعول الثاني «كفيلًا»»","url":""}]},{"id":"s16-139","number":139,"surah":16,"verses":[92],"references":[{"surah":16,"verses":[92]}],"verseLabel":"النحل: 92","question":"ما دلالة تشبيه ناقض العهد بالتي نقضت غزلها؟","answer":"يشبّه ناقض العهد بمن تحكم غزلها ثم تحلّه بيدها؛ فيصوّر إبطال المرء ما أنفق جهده في إحكامه. والغرض تشنيع هذا الفعل وإظهار سفه فاعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص318، تحت «دلالة التشبيه في الآية وأثره»","url":""}]},{"id":"s16-140","number":140,"surah":16,"verses":[92],"references":[{"surah":16,"verses":[92]}],"verseLabel":"النحل: 92","question":"ما دلالة قوله: ﴿أن تكون أمة هي أربى من أمة﴾؟","answer":"حوّل المصدر المؤول معنى تفوق جماعة إلى علة متصورة لنقض الأيمان، ففضح اتخاذ كثرة فريق ذريعةً للتقلب في العهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص323، تحت «دلالة التعبير بالمصدر المؤول»","url":""}]},{"id":"s16-227","number":227,"surah":16,"verses":[92],"references":[{"surah":16,"verses":[92]}],"verseLabel":"النحل: 92","question":"لماذا اختير لفظ ﴿أربى﴾ في وصف أمة؟","answer":"يفيد الزيادة والنماء، فيصور جماعة أكثر عددًا أو قوة، ويكشف أن باعث نقض العهد منفعة متوهمة تتبع الطرف الأقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص323، تحت «سر إيثار لفظ «أربى»»","url":""}]},{"id":"s16-141","number":141,"surah":16,"verses":[92],"references":[{"surah":16,"verses":[92]}],"verseLabel":"النحل: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّمَا يَبْلُوكُمُ اللَّهُ بِهِ﴾؟","answer":"فُصلت الجملة لتعلّل ما يقع من تفاوت بين الجماعات: إنه ابتلاء يظهر به الوفاء بالعهد. و«إنما» تقصر هذا التفاوت على كونه اختبارًا في هذا المقام، فلا يجعل ذريعة إلى نقض الأيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص324، تحت «علة فصل جملة «إنما يبلوكم الله به» عما قبلها؛ بلاغة الحصر بـ«إنما»»","url":""}]},{"id":"s16-142","number":142,"surah":16,"verses":[94],"references":[{"surah":16,"verses":[94]}],"verseLabel":"النحل: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿فَتَزِلَّ قَدَمٌ بَعْدَ ثُبُوتِهَا﴾؟","answer":"صُوّر الانحراف عن الاستقامة بعد التمكن منها بزلة قدم بعد رسوخها؛ فالمعنى النفسي والديني يصير مشهدًا محسوسًا للسقوط بعد الثبات. وفيه تحذير من أثر اتخاذ الأيمان خديعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص352، تحت «بلاغة الاستعارة في جملة «فتزل قدم بعد ثبوتها»»","url":""}]},{"id":"s16-143","number":143,"surah":16,"verses":[94],"references":[{"surah":16,"verses":[94]}],"verseLabel":"النحل: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿بَعْدَ ثُبُوتِهَا﴾ لا ثباتها؟","answer":"يفيد المصدر تحقق الرسوخ قبل الزلة، فيشتد به تصوير الانتقال من حال إلى ضدها. ويذكر المصدر توجيهًا لغويًا يخص «الثبوت» هنا بالرسوخ المعنوي والمجازي، فيناسب ثبات المرء على العهد والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص351، تحت «نكتة التعبير بالثبوت دون الثبات»","url":""}]},{"id":"s16-144","number":144,"surah":16,"verses":[94],"references":[{"surah":16,"verses":[94]}],"verseLabel":"النحل: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَذُوقُوا السُّوءَ﴾؟","answer":"صُوّر الإحساس بالسوء بذوق طعام مرّ مستبشع، فينقل أثر العذاب من معنى مجرد إلى تجربة حسية مباشرة. ويؤكد التعبير شدة إدراكهم عاقبة فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص353، 354، تحت «بلاغة الاستعارة التبعية المكنية في «وتذوقوا السوء»»","url":""}]},{"id":"s16-145","number":145,"surah":16,"verses":[95],"references":[{"surah":16,"verses":[95]}],"verseLabel":"النحل: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَشْتَرُوا بِعَهْدِ اللَّهِ ثَمَنًا قَلِيلًا﴾؟","answer":"صُوّر استبدال الوفاء بالعهد بحظ دنيوي بصورة المعاوضة والشراء. و«قليلًا» تكشف ضآلة كل عوض يؤخذ بإزاء نقض عهد الله، مهما بدا كثيرًا، إذا قيس بما عنده من الثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص363، 364، 365، تحت «بلاغة المجاز بالاستعارة في «ولا تشتروا»؛ توجيه الصفة «قليلًا»»","url":""}]},{"id":"s16-146","number":146,"surah":16,"verses":[96],"references":[{"surah":16,"verses":[96]}],"verseLabel":"النحل: 96","question":"لماذا قيل: ﴿ما عندكم ينفد وما عند الله باق﴾؟","answer":"عبّر عن متاع الناس بالمضارع لتجدد نفاده، وعن ثواب الله باسم الفاعل لإفادة ثبات بقائه ودوامه؛ فبرز التفاوت بين الزائل والدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص374، تحت «بلاغة العدول عن المضارع إلى اسم الفاعل في وصف ما عند الله»","url":""}]},{"id":"s16-147","number":147,"surah":16,"verses":[96],"references":[{"surah":16,"verses":[96]}],"verseLabel":"النحل: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ صَبَرُوا﴾ لا الصابرين؟","answer":"الموصول وصلته يبرزان الصبر علة للجزاء. ويذكر المصدر أن التعبير بالفعل يفتح باب الرجاء لمن تحقق منه الصبر، ولو لم يصر وصفًا دائمًا له؛ فكيف بمن جعله سجيّة ثابتة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص376، 377، تحت «سر التعبير بالاسم الموصول «الذين»؛ سر العدول من «الصابرين» إلى «الذين صبروا»»","url":""}]},{"id":"s16-148","number":148,"surah":16,"verses":[97],"references":[{"surah":16,"verses":[97]}],"verseLabel":"النحل: 97","question":"لماذا صرّح بـ﴿مِنْ ذَكَرٍ أَوْ أُنْثَى﴾ مع أن ﴿من﴾ تعم؟","answer":"لزيادة تأكيد شمول الوعد للرجال والنساء وإزالة توهم اختصاصه بالذكور. فالتصريح يقرر أن مناط هذا الجزاء العمل الصالح مع الإيمان، ويصحح تصورات تنقص المرأة من حقها فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص385، 386، تحت «فائدة التصريح بالذكر والأنثى مع دلالة «من» على العموم»","url":""}]},{"id":"s16-149","number":149,"surah":16,"verses":[97],"references":[{"surah":16,"verses":[97]}],"verseLabel":"النحل: 97","question":"ما سر تنكير ﴿حياة﴾ في قوله: ﴿فلنحيينه حياة طيبة﴾؟","answer":"يفيد التعظيم والتفخيم؛ فهي حياة متميزة بالرضا والطمأنينة وحسن العيش، لا مجرد بقاء جسدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص390، تحت «نكتة تنكير الحياة»","url":""}]},{"id":"s16-150","number":150,"surah":16,"verses":[98],"references":[{"surah":16,"verses":[98]}],"verseLabel":"النحل: 98","question":"ما دلالة الأمر في قوله: ﴿فاستعذ بالله﴾ عند قراءة القرآن؟","answer":"يرشد إلى الالتجاء إلى الله وطلب الحماية من وساوس الشيطان قبل التلاوة، لتصفو النفس لتدبر الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص400، تحت «بيان التعبير بالأمر»","url":""}]},{"id":"s16-228","number":228,"surah":16,"verses":[98],"references":[{"surah":16,"verses":[98]}],"verseLabel":"النحل: 98","question":"لماذا نصت الآية على الاستعاذة عند القراءة؟","answer":"لأن المقام مقام دفع عدو يصد عن الفهم والعمل، فناسبه طلب العصمة من شره، أما البسملة فمقصودها البدء باسم الله والتبرك به.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص403، تحت «إيثار الاستعاذة على البسملة»","url":""}]},{"id":"s16-151","number":151,"surah":16,"verses":[98],"references":[{"surah":16,"verses":[98]}],"verseLabel":"النحل: 98","question":"ما سرّ تعريف القرآن وإظهار اسمه في آية الاستعاذة؟","answer":"في التعريف وإظهار اسم القرآن تذكير بعظم المقروء: إنه الكتاب الجامع لصفات الكمال والتبيان. ويبرز الاسم معنى الجمع والضم، بدل الاكتفاء بضمير يعود إلى الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص399، تحت «وجها تعريف القرآن وإظهاره»","url":""}]},{"id":"s16-152","number":152,"surah":16,"verses":[99],"references":[{"surah":16,"verses":[99]}],"verseLabel":"النحل: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿لَيْسَ لَهُ سُلْطَانٌ﴾ لا قدرة؟","answer":"لفظ السلطان يجمع معاني التسلط والولاية والاستيلاء والتمكن، ويستعمل أيضًا للحجة. واختياره هنا ينفي عن الشيطان هذا السلطان على أهل الإيمان والتوكل، فلا يجد في اعتمادهم على ربهم مدخلًا يستولي به عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص408، 409، تحت «إيثار لفظ السلطان دون غيره»","url":""}]},{"id":"s16-153","number":153,"surah":16,"verses":[99],"references":[{"surah":16,"verses":[99]}],"verseLabel":"النحل: 99","question":"ما سر قوله: ﴿على ربهم يتوكلون﴾ بلفظ الرب وإضافته إليهم؟","answer":"يستحضر رعايته وتربيته للمؤمنين، فيقوى اعتمادهم على من يتولى شؤونهم ويحفظهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص410، تحت «إيثار لفظ الرب دون غيره وإضافته إلى ضمير المؤمنين»","url":""}]},{"id":"s16-229","number":229,"surah":16,"verses":[99],"references":[{"surah":16,"verses":[99]}],"verseLabel":"النحل: 99","question":"لماذا قدم ﴿على ربهم﴾ في قوله: ﴿وعلى ربهم يتوكلون﴾؟","answer":"يفيد تخصيص التوكل بالله وحده؛ فهم يأخذون بالأسباب ولا يعتمدون في النتيجة إلا على ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص410، تحت «نكتة تقديم شبه الجملة على الفعل»","url":""}]},{"id":"s16-154","number":154,"surah":16,"verses":[101],"references":[{"surah":16,"verses":[101]}],"verseLabel":"النحل: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا بَدَّلْنَا آيَةً مَكَانَ آيَةٍ﴾ لا نسخنا؟","answer":"التبديل يبرز وضع آية مكان آية، فيجمع رفع ما سبق وإقامة غيره مقامه وفق الحكمة والمصلحة. فهو يصوّر في السياق معنى الاستبدال، لا مجرد الرفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص420، 421، تحت «إيثار لفظ التبديل دون النسخ والتعويض»","url":""}]},{"id":"s16-155","number":155,"surah":16,"verses":[101],"references":[{"surah":16,"verses":[101]}],"verseLabel":"النحل: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ﴾ اعتراضًا؟","answer":"وقعت الجملة بين الشرط وجوابه لتدفع تهمة الافتراء، وتقرر أن تبديل الآية نابع من علم الله وحكمته ومراعاته للمصالح. فهي تنبّه إلى أن تبدل الحكم ليس تناقضًا ولا تصرفًا من الرسول من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص422، 423، تحت «فائدة جملة الاعتراض»","url":""}]},{"id":"s16-156","number":156,"surah":16,"verses":[102],"references":[{"surah":16,"verses":[102]}],"verseLabel":"النحل: 102","question":"ما سرّ تقديم الهدى على البشرى في وصف القرآن؟","answer":"الهداية هي المقصود الأول الذي يسعى إليه المسلم، والبشرى ثمرة الاهتداء. فقُدّم الأصل والأهم، ثم ما يترتب عليه من البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص436، تحت «إيثار الوصفين الهدى والبشرى دون غيرهما ومراعاة الترتيب بينهما»","url":""}]},{"id":"s16-157","number":157,"surah":16,"verses":[102],"references":[{"surah":16,"verses":[102]}],"verseLabel":"النحل: 102","question":"ما دلالة تسمية جبريل ﴿روح القدس﴾؟","answer":"الروح تشير إلى أن الوحي يحيي القلوب، والقدس إلى الطهر؛ ففي الاسم تشريف للملك وتنزيه لمصدر القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص433، تحت «بلاغة إضافة الروح إلى القدس»","url":""}]},{"id":"s16-230","number":230,"surah":16,"verses":[102],"references":[{"surah":16,"verses":[102]}],"verseLabel":"النحل: 102","question":"كيف يسند تنزيل القرآن إلى جبريل مع أن الله أنزله؟","answer":"الله هو المنزل أمرًا ووحيًا، وجبريل مباشر النزول بالتبليغ؛ فالإسنادان يبينان الآمر والواسطة ولا تعارض بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص433، تحت «وجه إسناد الإنزال إلى روح القدس بعد إسناده إليه تعالى»","url":""}]},{"id":"s16-158","number":158,"surah":16,"verses":[103],"references":[{"surah":16,"verses":[103]}],"verseLabel":"النحل: 103","question":"ما دلالة قولهم: ﴿إِنَّمَا يُعَلِّمُهُ بَشَرٌ﴾؟","answer":"قصدوا قصر مصدر ما يأتي به الرسول على تعليم بشر، نافيـن عنه الوحي. واختيار «إنما» يصوّر دعواهم الباطلة كأنها حقيقة مقررة، مع ما في وصف المعلّم بأنه بشر من جحود مصدر القرآن الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص447، 448، تحت «بلاغة القصر بـ«إنما»؛ دلالة التعبير بقولهم «بشر» دون غيره»","url":""}]},{"id":"s16-159","number":159,"surah":16,"verses":[103],"references":[{"surah":16,"verses":[103]}],"verseLabel":"النحل: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿لِسَانُ الَّذِي يُلْحِدُونَ إِلَيْهِ أَعْجَمِيٌّ﴾ لا أعجم؟","answer":"يربط المصدر هذا الوصف بالعجمة وعدم الإبانة، ويرى في صيغة النسبة تقوية لهذا المعنى حتى كأن العجمة تمكنت من صاحب اللسان. وفي مقابلة ذلك بالقرآن العربي المبين إبطال لدعوى أن هذا الشخص مصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص455، 456، تحت «براعة التعبير بقوله «أعجمي»؛ سر العدول عن «أعجم» إلى «أعجمي»»","url":""}]},{"id":"s16-160","number":160,"surah":16,"verses":[103],"references":[{"surah":16,"verses":[103]}],"verseLabel":"النحل: 103","question":"لماذا وصف لسان القرآن بـ﴿عَرَبِيٌّ مُبِينٌ﴾ لا فصيح؟","answer":"الفصاحة داخلة في وصف العربية، أما «مبين» فتزيد بيان أثر القرآن: يوضح المعاني والحقائق ويكشفها للسامعين. فالوصف يبرز وظيفة البيان، لا جودة الألفاظ وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص458، تحت «سر إيثار الوصف بالإبانة دون الفصاحة»","url":""}]},{"id":"s16-161","number":161,"surah":16,"verses":[104],"references":[{"surah":16,"verses":[104]}],"verseLabel":"النحل: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ لَا يُؤْمِنُونَ﴾ لا الكافرون؟","answer":"الصلة تذكر الصفة التي تعلق بها الحكم: امتناعهم عن الإيمان بالآيات. والمضارع المنفي يصوّر استمرار هذا الامتناع وتجدد رفضهم، فيربط حرمانهم من الهداية بإعراضهم المتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص466، 467، تحت «سر العدول عن التعبير بالكافرين إلى «الذين لا يؤمنون»؛ دلالة التعبير بالمضارع المنفي»","url":""}]},{"id":"s16-162","number":162,"surah":16,"verses":[105],"references":[{"surah":16,"verses":[105]}],"verseLabel":"النحل: 105","question":"ما دلالة القصر في قوله: ﴿إنما يفتري الكذب الذين لا يؤمنون بآيات الله﴾؟","answer":"يحصر اختلاق الكذب فيمن لا يؤمن بآيات الله، فينفيه عن الرسول ويبين أن تهمة المشركين عائدة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص477، تحت «دلالة القصر»","url":""}]},{"id":"s16-163","number":163,"surah":16,"verses":[105],"references":[{"surah":16,"verses":[105]}],"verseLabel":"النحل: 105","question":"ما سر التذييل بقوله: ﴿وأولئك هم الكاذبون﴾؟","answer":"أكد بضمير الفصل والقصر أن الكذب صفتهم المحققة، فصار التذييل حكمًا عامًا يرد افتراءهم على الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص483، تحت «بلاغة القصر في جملة التذييل»","url":""}]},{"id":"s16-164","number":164,"surah":16,"verses":[106],"references":[{"surah":16,"verses":[106]}],"verseLabel":"النحل: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ﴾؟","answer":"جاءت الجملة حالًا تقيد الاستثناء: يقع الإكراه على القول الظاهر مع بقاء القلب ثابتًا على الإيمان. ووصف الاطمئنان يصور رسوخ التصديق رغم الخطر والاضطراب الخارجي، فيميز هذه الحال ممن رضي بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص498، 499، تحت «بلاغة موقع جملة «وقلبه مطمئن بالإيمان»؛ نكتة اصطفاء وصف الاطمئنان للقلب»","url":""}]},{"id":"s16-165","number":165,"surah":16,"verses":[106],"references":[{"surah":16,"verses":[106]}],"verseLabel":"النحل: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿قَلْبُهُ﴾ لا فؤاده؟","answer":"يناسب القلب هنا معنى استقرار الإيمان وثباته، وقد قُيّد بالاطمئنان لبيان ذلك. ويذكر المصدر أن الفؤاد أنسب في أصل دلالته للتوقد والتحرق والتوثب، فلا يلائم هذا المقام كما يلائمه القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص498، تحت «سر التعبير بالقلب دون الفؤاد»","url":""}]},{"id":"s16-166","number":166,"surah":16,"verses":[106],"references":[{"surah":16,"verses":[106]}],"verseLabel":"النحل: 106","question":"ما دلالة قوله: ﴿شرح بالكفر صدرًا﴾؟","answer":"الشرح يدل على التوسعة؛ فصور من يختار الكفر راضيًا بأنه فتح له صدره وقبله اختيارًا، لا مكرهًا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص504، تحت «سر التعبير بفعل الشرح»","url":""}]},{"id":"s16-231","number":231,"surah":16,"verses":[106],"references":[{"surah":16,"verses":[106]}],"verseLabel":"النحل: 106","question":"لماذا قال: ﴿شرح بالكفر صدرًا﴾ ولم يقل قلبًا؟","answer":"الصدر موضع الانفساح والاحتواء، فالتعبير يصور إحاطة الكفر بباطنه واستقباله له على سعة، مع بقاء القلب موضع الاعتقاد في الداخل.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص506، تحت «سر التعبير بـ«صدرًا» دون القلب»","url":""}]},{"id":"s16-167","number":167,"surah":16,"verses":[106],"references":[{"surah":16,"verses":[106]}],"verseLabel":"النحل: 106","question":"ما سرّ تقديم ﴿فَعَلَيْهِمْ غَضَبٌ مِنَ اللَّهِ﴾؟","answer":"تقديم «عليهم» يلفت إلى اختصاصهم بهذا الوعيد واستحقاقهم الغضب بسبب رضاهم بالكفر، وفيه بيان أنهم ألحقوه بأنفسهم باختيارهم. كما يناسب تقديمَ الخبر على النكرة المراد تعظيمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص507، تحت «دلالة تقديم المسند في قوله «فعليهم غضب»»","url":""}]},{"id":"s16-168","number":168,"surah":16,"verses":[107],"references":[{"surah":16,"verses":[107]}],"verseLabel":"النحل: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿اسْتَحَبُّوا الْحَيَاةَ الدُّنْيَا عَلَى الْآخِرَةِ﴾؟","answer":"الاستحباب هنا يتجاوز الميل إلى الإيثار: قدّموا الدنيا على الآخرة وطلبوا حظها. وتفيد الصيغة، في التوجيه المذكور، شدة التعلق والتكلف في طلب المحبوب، لا مجرد حب عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص517، 518، تحت «نكتة التعبير بالحب في قوله «استحبوا»؛ براعة التعبير بقوله «استحبوا»»","url":""}]},{"id":"s16-169","number":169,"surah":16,"verses":[108],"references":[{"surah":16,"verses":[108]}],"verseLabel":"النحل: 108","question":"لماذا قال: ﴿طبع الله على قلوبهم﴾ ولم يقل ختم؟","answer":"الطبع أدل على ثبات الأثر وتمكنه حتى يصير كالعلامة الملازمة؛ وهو مناسب لاستحكام إعراضهم بعد اختيارهم الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص526، تحت «سر التعبير بالطبع دون الختم»","url":""}]},{"id":"s16-170","number":170,"surah":16,"verses":[108],"references":[{"surah":16,"verses":[108]}],"verseLabel":"النحل: 108","question":"ما سرّ إفراد السمع وجمع الأبصار؟","answer":"من التوجيهات المذكورة أن السمع مصدر، والمصدر لا يلزمه الجمع، مع اتحاد جنس متعلقه وهو الصوت. أما الأبصار فتتفاوت جهاتها ومرئياتها وطرائق الاعتبار بها، فناسبها الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص531، 532، تحت «سر التعبير بالإفراد في قوله «وسمعهم»؛ سر التعبير بالجمع «وأبصارهم» دون المفرد»","url":""}]},{"id":"s16-171","number":171,"surah":16,"verses":[109],"references":[{"surah":16,"verses":[109]}],"verseLabel":"النحل: 109","question":"ما سر قوله: ﴿هم الخاسرون﴾ في جملة اسمية مقصورة؟","answer":"تفيد الاسمية ثبوت الخسارة، ويفيد القصر أنهم المستحقون لتمامها؛ لأنهم استبدلوا بالآخرة عرض الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص541، تحت «علة التعبير بالجملة الاسمية في الخسارة»","url":""}]},{"id":"s16-172","number":172,"surah":16,"verses":[110],"references":[{"surah":16,"verses":[110]}],"verseLabel":"النحل: 110","question":"ما دلالة حذف متعلقات ﴿هَاجَرُوا﴾ و﴿جَاهَدُوا﴾ و﴿صَبَرُوا﴾؟","answer":"حذف جهة الهجرة يشمل صورها دون حصرها في وجهة واحدة. وفي الجهاد والصبر يوجّه الحذف العناية إلى تحقق الفعلين نفسيهما، مع علم المخاطب بما يقتضيه السياق، فلا يتقيد الثناء بمفعول مذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص549، 552، تحت «دلالة حذف متعلق «هاجروا»؛ سر حذف مفعول «جاهدوا» وحذف متعلق «صبروا»»","url":""}]},{"id":"s16-173","number":173,"surah":16,"verses":[110],"references":[{"surah":16,"verses":[110]}],"verseLabel":"النحل: 110","question":"ما سرّ تقديم ﴿لَغَفُورٌ﴾ على ﴿رَحِيمٌ﴾؟","answer":"المغفرة سلامة من أثر الذنب، والرحمة إنعام وإحسان؛ فناسب أن يقدم رفع الضرر ثم يذكر ما يعقبه من الفضل. وفي الترتيب طمأنة للمؤمنين بوعد العفو والإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص557، 558، تحت «فائدة تقديم «لغفور» على «رحيم»»","url":""}]},{"id":"s16-174","number":174,"surah":16,"verses":[111],"references":[{"surah":16,"verses":[111]}],"verseLabel":"النحل: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلُّ نَفْسٍ تُجَادِلُ عَنْ نَفْسِهَا﴾؟","answer":"«كل نفس» تنص على شمول الموقف لكل إنسان. والمضارع يستحضر مشهد المجادلة، واختيارها يصور شدة تمسك النفس بما ترجوه سبيلًا إلى النجاة، مع انشغال كل امرئ بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص563، 564، 565، تحت «فائدة استعمال «كل» دون جمع النفس؛ نكتة اختيار «تجادل» دون تدافع»","url":""}]},{"id":"s16-175","number":175,"surah":16,"verses":[111],"references":[{"surah":16,"verses":[111]}],"verseLabel":"النحل: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا عَمِلَتْ﴾ لا ما قدمت؟","answer":"العمل يعم ما قام به الإنسان في الدنيا من خير أو شر. أما التقديم فقد يغلب في المقام الذي يراد فيه ما قدّمه المرء للثواب؛ فناسب لفظ العمل هنا شمول الجزاء لجميع الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص568، تحت «فائدة ذكر مفردة العمل دون لفظ التقديم»","url":""}]},{"id":"s16-176","number":176,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما دلالة إسناد الأمن والكفر والعذاب إلى القرية؟","answer":"المراد أهلها، لكن إسناد أحوالهم إلى القرية يصور أثرها وقد عم المكان كله؛ فتبدو النعمة ثم عاقبة جحودها مشهدًا شاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص578، تحت «بلاغة المجاز العقلي»","url":""}]},{"id":"s16-177","number":177,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما أثر إسناد الإتيان إلى الرزق في قوله: ﴿يأتيها رزقها﴾؟","answer":"يصوّر الرزق كأنه يقصد أهل القرية ويصل إليهم ميسرًا، من غير عناء شديد في طلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص581، تحت «بلاغة إسناد الإتيان إلى الرزق»","url":""}]},{"id":"s16-232","number":232,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما دلالة قوله: ﴿رزقها رغدًا﴾؟","answer":"يبين سعة الرزق وهناءه وسهولة الانتفاع به، فلا يقتصر وصف النعمة على مجرد وجود القوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص582، تحت «بلاغة تقييد إتيان الرزق بـ«رغدًا»»","url":""}]},{"id":"s16-233","number":233,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما أثر قوله: ﴿من كل مكان﴾ في وصف رزق القرية؟","answer":"يفيد كثرة موارده وتنوع جهاته، فتكتمل صورة النعمة المحيطة التي كان حقها الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص583، تحت «دلالة التعبير بصيغة العموم»","url":""}]},{"id":"s16-178","number":178,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما سر جمع الذوق واللباس في قوله: ﴿فأذاقها الله لباس الجوع والخوف﴾؟","answer":"الإذاقة تصور الإحساس المباشر المتمكن بالألم، واللباس يصور إحاطة الجوع والخوف وملازمتهما؛ فاجتمع الباطن المحسوس والأثر المحيط.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص588، تحت «براعة اجتماع استعارات فريدة ومعان تليدة»","url":""}]},{"id":"s16-179","number":179,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا كَانُوا يَصْنَعُونَ﴾ لا يعملون؟","answer":"الصنع يبرز تعمدهم الكفر وتفننهم فيه حتى صار عادة راسخة. والمضارع يصوّر تجدده واستمراره؛ فليس المقصود هفوة عابرة، بل سلوكًا يداومون عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص595، 596، تحت «سر إيثار لفظ «يصنعون»؛ نكتة التعبير بالفعل المضارع»","url":""}]},{"id":"s16-180","number":180,"surah":16,"verses":[113],"references":[{"surah":16,"verses":[113]}],"verseLabel":"النحل: 113","question":"ما دلالة قوله: ﴿وهم ظالمون﴾ بعد أخذ العذاب لهم؟","answer":"الجملة حالية، واسميتها تقرر رسوخهم في الظلم وقت العقوبة؛ فظهر أن العذاب أخذهم وهم مقيمون على الكفر والتكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص601، تحت «بلاغة الاسمية في جملة الفاصلة»","url":""}]},{"id":"s16-181","number":181,"surah":16,"verses":[114],"references":[{"surah":16,"verses":[114]}],"verseLabel":"النحل: 114","question":"ما سرّ تقديم ﴿حَلَالًا﴾ على ﴿طَيِّبًا﴾؟","answer":"الحلال هو الأصل في إباحة الأكل، والطيب وصف تابع يكمل الانتفاع به واستطابته. فقُدّم ما تقوم عليه مشروعية الأكل، ثم ذُكر ما يصف جودته وملاءمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص609، تحت «نكتة تقديم «حلالًا» على «طيبًا»»","url":""}]},{"id":"s16-182","number":182,"surah":16,"verses":[114],"references":[{"surah":16,"verses":[114]}],"verseLabel":"النحل: 114","question":"ما سرّ إفراد ﴿نِعْمَتَ اللَّهِ﴾ في آية الأكل والشكر؟","answer":"يذكر المصدر أن المراد في هذا السياق نعمة الأكل من الرزق الحلال الطيب، أو نعمة المباحات من الطعام في مجموعها. فلحظها نعمة واحدة جامعة، فناسب إفرادها بعد الأمر بالأكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص610، تحت «نكتة إفراد «نعمت الله»»","url":""}]},{"id":"s16-184","number":184,"surah":16,"verses":[115],"references":[{"surah":16,"verses":[115]}],"verseLabel":"النحل: 115","question":"لماذا قيل: ﴿وما أهل لغير الله به﴾ ولم يصرح بالأصنام؟","answer":"لفظ «غير» مع الموصول يعم كل ما ذبح متوجهًا به إلى سوى الله، فلا يحصر الحكم في أصنام مسماة، وفيه إيجاز وشمول.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص616، تحت «نكتة استعمال «لغير الله» دون التصريح بالأصنام»","url":""}]},{"id":"s16-185","number":185,"surah":16,"verses":[115],"references":[{"surah":16,"verses":[115]}],"verseLabel":"النحل: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنِ اضْطُرَّ﴾ لا أُجبر؟","answer":"الاضطرار أعم؛ فقد ينشأ من حاجة ملجئة داخلية، وقد يكون بسبب ضغط خارجي. أما الإجبار فيغلب فيه حمل الغير للإنسان على الفعل؛ فاختير الأعم لاستيعاب صور الضرورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص618، 619، تحت «نكتة اختيار لفظ الاضطرار دون الإجبار»","url":""}]},{"id":"s16-186","number":186,"surah":16,"verses":[115],"references":[{"surah":16,"verses":[115]}],"verseLabel":"النحل: 115","question":"ما مناسبة ختام حكم المضطر بقوله تعالى: ﴿إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"غفور للمضطر فيما أكل، رحيم به حين رخّص له عند الاضطرار؛ فجمع له العفو والرخصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص621، 622، تحت «نكتة جمع وصفي «غفور رحيم»»","url":""}]},{"id":"s16-187","number":187,"surah":16,"verses":[116],"references":[{"surah":16,"verses":[116]}],"verseLabel":"النحل: 116","question":"ما دلالة إسناد وصف الكذب إلى الألسنة في الآية؟","answer":"في الإسناد إلى الألسنة تشنيع لافترائهم، إذ يجعل أدوات البيان نفسها تباشر الكذب على الله. ويكشف أنهم يطلقون من القول ما يعلمون بطلانه في أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص630، تحت «نكتة إسناد وصف الكذب إلى الألسن»","url":""}]},{"id":"s16-188","number":188,"surah":16,"verses":[116],"references":[{"surah":16,"verses":[116]}],"verseLabel":"النحل: 116","question":"ما سر قوله: ﴿تفتروا على الله الكذب﴾ بدل أن تكذبوا؟","answer":"الافتراء يبرز الاختلاق المتعمد، وذكر الكذب معه يؤكد قبح الصنيع وشناعة نسبة الحكم المصنوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص633، تحت «نكتة ذكر افتراء الكذب دون الكذب مباشرة»","url":""}]},{"id":"s16-234","number":234,"surah":16,"verses":[116],"references":[{"surah":16,"verses":[116]}],"verseLabel":"النحل: 116","question":"لماذا قدم ﴿على الله﴾ على ﴿الكذب﴾؟","answer":"يركز التقديم على عظم الجناية؛ فهي ليست خبرًا كاذبًا فحسب، بل كذب متعمد منسوب إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص634، تحت «فائدة تقديم الجار والمجرور على المفعول»","url":""}]},{"id":"s16-189","number":189,"surah":16,"verses":[117],"references":[{"surah":16,"verses":[117]}],"verseLabel":"النحل: 117","question":"ما دلالة وصف منفعة الافتراء بأنها ﴿متاع قليل﴾؟","answer":"يحقر ما ينالونه في الدنيا، فهو محدود زائل مهما بدا كبيرًا، فلا يساوي ما يترتب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص638، تحت «بلاغة وصف المتاع بالقليل»","url":""}]},{"id":"s16-235","number":235,"surah":16,"verses":[117],"references":[{"surah":16,"verses":[117]}],"verseLabel":"النحل: 117","question":"ما أثر عطف قوله: ﴿ولهم عذاب أليم﴾ على المتاع القليل؟","answer":"يجمع لهم بين حقارة المكسب العاجل وفداحة الجزاء الآجل، فتظهر خسارة من آثر الزائل على النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص639، تحت «دلالة الواو في قوله «ولهم عذاب أليم»»","url":""}]},{"id":"s16-190","number":190,"surah":16,"verses":[119],"references":[{"surah":16,"verses":[119]}],"verseLabel":"النحل: 119","question":"ما سرّ إعادة ﴿إِنَّ رَبَّكَ﴾ في قوله تعالى: ﴿إِنَّ رَبَّكَ مِنْ بَعْدِهَا لَغَفُورٌ رَحِيمٌ﴾؟","answer":"أعيد صدر الجملة بعد طول الفصل لإحكام اتصال الخبر بمن وعدهم الله بالمغفرة. وفي الإعادة أيضًا توكيد للوعد وتنويه به، حتى لا يضيع مع امتداد الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص658، تحت «نكتة فصل جملة «إن ربك من بعدها»»","url":""}]},{"id":"s16-191","number":191,"surah":16,"verses":[119],"references":[{"surah":16,"verses":[119]}],"verseLabel":"النحل: 119","question":"ما سر حذف مفعول ﴿أَصْلَحُوا﴾؟","answer":"ليعم إصلاح الاعتقاد والعمل وما أفسدته الجهالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص658، تحت «نكتة حذف متعلق «وأصلحوا»»","url":""}]},{"id":"s16-192","number":192,"surah":16,"verses":[120],"references":[{"surah":16,"verses":[120]}],"verseLabel":"النحل: 120","question":"ما سر وصف إبراهيم عليه السلام وحده بأنه ﴿أُمَّةً﴾؟","answer":"من توجيهات الوصف أنه إمام يُؤتم به، وأن ما قام به من خصال الخير يعادل ما تتوزعه جماعة. وفيه تعظيم لمنزلته وبيان اجتماع وجوه الهدى فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص667، 668، تحت «بلاغة المجاز في الوصف بالأمة»","url":""}]},{"id":"s16-193","number":193,"surah":16,"verses":[120],"references":[{"surah":16,"verses":[120]}],"verseLabel":"النحل: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿قَانِتًا لِلَّهِ حَنِيفًا﴾؟","answer":"«قانتًا» تصفه بالطاعة المستقرة لله، و«حنيفًا» تصفه بالميل عن الباطل إلى الحق. فاجتمع له دوام العبودية وصحة الوجهة، وجاء الوصفان دالين على تمكنهما فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص668، 669، تحت «دلالة البناء الصرفي لقوله «قانتًا»؛ البناء الصرفي لقوله «حنيفًا»»","url":""}]},{"id":"s16-194","number":194,"surah":16,"verses":[120],"references":[{"surah":16,"verses":[120]}],"verseLabel":"النحل: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَمْ يَكُ مِنَ الْمُشْرِكِينَ﴾ بحذف النون؟","answer":"حذف النون جائز للتخفيف في هذا التركيب المجزوم، ويذكر المصدر كثرة الاستعمال في تعليله. ومن توجيهاته البلاغية مناسبة هذا التخفيف لقوة نفي الشرك عن إبراهيم وبراءته منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص671، تحت «دلالة الموقع النحوي لقوله «ولم يك»»","url":""}]},{"id":"s16-195","number":195,"surah":16,"verses":[121],"references":[{"surah":16,"verses":[121]}],"verseLabel":"النحل: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿شَاكِرًا لِأَنْعُمِهِ﴾ بجمع القلة؟","answer":"من التوجيهات المذكورة التنبيه بالأدنى على الأعلى: كان إبراهيم شاكرًا للنعم وإن قلّت، فكيف بالكثيرة؟ فجمع القلة يمدح استيعاب شكره، ولا يحصر نعم الله في عدد قليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص672، تحت «غرض التعبير بجمع القلة «لأنعمه»»","url":""}]},{"id":"s16-196","number":196,"surah":16,"verses":[121],"references":[{"surah":16,"verses":[121]}],"verseLabel":"النحل: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿اجْتَبَاهُ﴾؟","answer":"الاجتباء يتضمن الاختيار والإعداد والتهيئة. وفصل الجملة يناسب بيان ما منحه الله لإبراهيم بعد ذكر خصاله، وتقديم الاجتباء على الهداية من تقديم السبب على ثمرته في هذا السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص672، 673، 683، تحت «نكتة فصل جملة «اجتباه»؛ غرض تقديم الاجتباء على الهداية؛ الاجتباء والاصطفاء»","url":""}]},{"id":"s16-197","number":197,"surah":16,"verses":[122],"references":[{"surah":16,"verses":[122]}],"verseLabel":"النحل: 122","question":"ما سر تقديم ﴿فِي الدُّنْيَا﴾ و﴿فِي الْآخِرَةِ﴾؟","answer":"في تقديم «في الدنيا» عناية بموطن الإيتاء وتشويق إلى الحسنة المذكورة بعده. وتقديم «في الآخرة» يبرز مقام إبراهيم فيها ويشوّق إلى الحكم بأنه من الصالحين؛ فيتضح الإكرام في الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص676، 677، تحت «نكتة تقديم شبه الجملة «في الدنيا»؛ نكتة تقديم شبه الجملة «في الآخرة»»","url":""}]},{"id":"s16-198","number":198,"surah":16,"verses":[123],"references":[{"surah":16,"verses":[123]}],"verseLabel":"النحل: 123","question":"ما دلالة الأمر: ﴿اتبع ملة إبراهيم﴾؟","answer":"يدعو إلى الثبات على أصول الحنيفية الجامعة للتوحيد، ويبين أن رسالة محمد امتداد لدين الأنبياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص679، تحت «دلالة الأمر باتباع الملة»","url":""}]},{"id":"s16-236","number":236,"surah":16,"verses":[123],"references":[{"surah":16,"verses":[123]}],"verseLabel":"النحل: 123","question":"ما سر إضافة الملة إلى إبراهيم؟","answer":"تعظم شأن الملة وصاحبها، وتلزم من يدعي الانتساب إليه بحقيقة دينه: إخلاص العبادة لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص680، تحت «نكتة الإضافة في «ملة إبراهيم»»","url":""}]},{"id":"s16-199","number":199,"surah":16,"verses":[124],"references":[{"surah":16,"verses":[124]}],"verseLabel":"النحل: 124","question":"ما دلالة القصر في قوله: ﴿إنما جعل السبت على الذين اختلفوا فيه﴾؟","answer":"يخص تكليف السبت بالذين اختلفوا فيه، فيبين أنه تشريع خاص بهم لا أصل من ملة إبراهيم الحنيفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص690، تحت «بلاغة القصر في مطلع الآية»","url":""}]},{"id":"s16-237","number":237,"surah":16,"verses":[124],"references":[{"surah":16,"verses":[124]}],"verseLabel":"النحل: 124","question":"ما دلالة الفعل ﴿جعل﴾ في شأن السبت؟","answer":"يفيد فرض تعظيم السبت وترتيب أحكامه عليهم بتشريع ملزم، لا مجرد اختيار عادة زمنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص690، تحت «نكتة التعبير بـ«جعل» مادة وصيغة»","url":""}]},{"id":"s16-238","number":238,"surah":16,"verses":[124],"references":[{"surah":16,"verses":[124]}],"verseLabel":"النحل: 124","question":"ما أثر تعدية ﴿جعل﴾ بحرف ﴿على﴾؟","answer":"تشعر بالتكليف والإلزام وبما فيه من ثقل عليهم بسبب اختلافهم، فناسبت خصوصية الحكم بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص691، تحت «نكتة تعدية الجعل بـ«على»»","url":""}]},{"id":"s16-200","number":200,"surah":16,"verses":[124],"references":[{"surah":16,"verses":[124]}],"verseLabel":"النحل: 124","question":"ما سر تقديم ﴿فِيهِ﴾ في قوله تعالى: ﴿فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ﴾؟","answer":"قُدّمت ﴿فيه﴾ على خبر «كان» لأن ما وقع فيه الاختلاف هو مدار الحديث وسبب الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص694، تحت «نكتة تقديم شبه الجملة «فيه»»","url":""}]},{"id":"s16-201","number":201,"surah":16,"verses":[125],"references":[{"surah":16,"verses":[125]}],"verseLabel":"النحل: 125","question":"لماذا جمعت الدعوة بين الحكمة والموعظة الحسنة؟","answer":"الحكمة تقيم البرهان وتضع الخطاب في موضعه، والموعظة تحرك القلب بالترغيب والترهيب؛ فتكامل خطاب العقل والوجدان.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص702، تحت «فائدة عطف الموعظة على الحكمة»","url":""}]},{"id":"s16-239","number":239,"surah":16,"verses":[125],"references":[{"surah":16,"verses":[125]}],"verseLabel":"النحل: 125","question":"لماذا أفرد الجدال بقوله: ﴿وجادلهم بالتي هي أحسن﴾؟","answer":"لأن الجدال يواجه معارضةً مباشرة فاحتاج أمرًا مستقلًا وقيدًا زائدًا بأحسن الطرق، اتقاء تحول الحجة إلى خصومة منفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص703، تحت «نكتة تغاير النظم في قوله «وجادلهم»»","url":""}]},{"id":"s16-202","number":202,"surah":16,"verses":[126],"references":[{"surah":16,"verses":[126]}],"verseLabel":"النحل: 126","question":"ما دلالة الشرط في قوله: ﴿وإن عاقبتم فعاقبوا بمثل ما عوقبتم به﴾؟","answer":"جعل العقوبة أمرًا مفروض الوقوع لا مطلوبًا، ثم قيد الرد بالمماثلة حتى لا يتجاوز قدر الاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص715، تحت «بلاغة التعبير بالجملة الشرطية»","url":""}]},{"id":"s16-240","number":240,"surah":16,"verses":[126],"references":[{"surah":16,"verses":[126]}],"verseLabel":"النحل: 126","question":"ما دلالة قوله بعد إباحة المقابلة: ﴿ولئن صبرتم لهو خير للصابرين﴾؟","answer":"نكر الخير لتعظيم ما في الصبر من فضل وعاقبة حسنة، فرغب في العفو بعد أن قرر حق المقابلة العادلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص717، تحت «نكتة تنكير «خير»»","url":""}]},{"id":"s16-203","number":203,"surah":16,"verses":[126],"references":[{"surah":16,"verses":[126]}],"verseLabel":"النحل: 126","question":"ما سر حذف مفعول ﴿عَاقَبْتُمْ﴾؟","answer":"حذف المفعول يعمم من يقع عليه الرد ممن يستحقه، ويوجه العناية إلى الفعل وضابطه: أن يكون بمثل ما وقع من الاعتداء، دون تجاوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص715، تحت «غرض حذف مفعول «عاقبتم»»","url":""}]},{"id":"s16-204","number":204,"surah":16,"verses":[127],"references":[{"surah":16,"verses":[127]}],"verseLabel":"النحل: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ﴾؟","answer":"الأمر يدعو إلى الثبات والدوام على الصبر، ثم يقرر القصر أن تحققه إنما يكون بتوفيق الله ومعونته. فتقترن المطالبة بالصبر بالتنبيه إلى مصدر القوة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص718، 719، تحت «دلالة الأمر في فعل الأمر «واصبر»؛ بلاغة القصر في قوله «وما صبرك إلا بالله»»","url":""}]},{"id":"s16-205","number":205,"surah":16,"verses":[127],"references":[{"surah":16,"verses":[127]}],"verseLabel":"النحل: 127","question":"ما دلالة حذف النون في ﴿وَلَا تَكُ فِي ضَيْقٍ﴾ في النحل، مع إثباتها في ﴿وَلَا تَكُنْ فِي ضَيْقٍ﴾ في النمل؟","answer":"الأصل النحوي يجيز حذف النون هنا للتخفيف، كما يجيز إثباتها في نحو آية النمل. ويذكر المصدر وجهًا بلاغيًا للحذف في النحل: المبالغة في التسلية، كأن المطلوب محو أقل أثر للضيق من النفس. فهذا توجيه لدلالة الحذف، لا حكم بأن الإثبات يضعف النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص719، 720، تحت «دلالة الموقع النحوي لقوله «تك»»، وتتمة شرح حذف النون في صدر ص720","url":""}]},{"id":"s16-206","number":206,"surah":16,"verses":[127],"references":[{"surah":16,"verses":[127]}],"verseLabel":"النحل: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي ضَيْقٍ﴾ لا ذا ضيق؟","answer":"صُوّر الغم والأسف بضيـق المكان، وجُعل ظرفًا يحيط بالنفس. فالتعبير يرسم شدة استيلاء الضيق، ويأتي النهي تسلية للرسول وتحذيرًا من الاستغراق في الحزن بسبب مكرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص720، تحت «نكتة التعبير في قوله «في ضيق»؛ بلاغة الاستعارة في قوله «في ضيق»»","url":""}]},{"id":"s16-207","number":207,"surah":16,"verses":[128],"references":[{"surah":16,"verses":[128]}],"verseLabel":"النحل: 128","question":"ما مناسبة ختام السورة بقوله تعالى: ﴿إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوْا وَالَّذِينَ هُمْ مُحْسِنُونَ﴾؟","answer":"جاءت الخاتمة تعليلًا لما سبق من الأمر بالصبر والنهي عن الحزن والضيق. والمعية معية تأييد ونصر وولاية؛ فتطمئن المتقين المحسنين، ويجمع الوصفان اجتناب الشر والإقبال على الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص721، 722، 723، تحت «نكتة فصل قوله «إن الله مع الذين اتقوا»؛ دلالة دخول «مع» في السياق؛ نكتة عطف قوله «والذين هم محسنون»»","url":""}]},{"id":"s17-1","number":1,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر افتتاح السورة بـ﴿سُبْحَانَ﴾ قبل خبر الإسراء؟","answer":"لتهيئة السامع لخبر عجيب يدل على عظيم القدرة، وتنزيه الله عن العجز عن هذا الحدث الخارق للعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص748، 749، تحت «براعة الاستهلال بذكر التسبيح»","url":""}]},{"id":"s17-2","number":2,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر التعبير بـ﴿أَسْرَى بِعَبْدِهِ﴾ لا «سرى بعبده»؟","answer":"من التوجيهات التي يذكرها المصدر أن «أسرى» متعدٍّ، أي أسرى البراقَ بعبده؛ وفي ذلك إيماء إلى عناية الله برسوله. ويذكر أيضًا قول من يجعل «أسرى» و«سرى» بمعنى واحد، فلا ينحصر الفرق في التعدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص750، 751، تحت «سر التعبير بفعل «أسرى»»","url":""}]},{"id":"s17-3","number":3,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر التعبير بـ﴿بِعَبْدِهِ﴾ لا «برسوله»؟","answer":"لأن العبودية أعلى مقامات القرب والرفعة، وفي وصفه بها تشريف له مع سد باب الغلو فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص751، تحت «فائدة التعبير بعنوان العبودية دون الرسالة أو النبوة»","url":""}]},{"id":"s17-4","number":4,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر ذكر ﴿لَيْلًا﴾ مع أن الإسراء لا يكون إلا ليلًا؟","answer":"من أغراض ذكره تأكيد وقوع الإسراء ليلًا، ومن دلالة تنكيره أن الرحلة العظيمة وقعت في بعض ليلة، فيظهر ما فيها من خرق للعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص752، تحت «سر التقييد بالظرف «ليلًا»؛ غرض تنكير «ليلًا»»","url":""}]},{"id":"s17-5","number":5,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما دلالة وصف المسجد بـ﴿الْأَقْصَى﴾؟","answer":"هو وصف تفضيل يبين شدة بعده عن المسجد الحرام، فيبرز طول المسافة التي قطعت في بعض ليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص756، 757، تحت «دلالة التعبير بـ«الأقصى»؛ نكتة ذكر مبدأ الإسراء ونهايته»","url":""}]},{"id":"s17-6","number":6,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر التعبير بـ﴿بَارَكْنَا حَوْلَهُ﴾ لا «باركنا فيه»؟","answer":"ليعم الخير المسجد وما حوله؛ فإذا ثبتت البركة لما أحاط به كان ثبوتها فيه من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص759، تحت «بلاغة الكناية والمجاز المرسل»","url":""}]},{"id":"s17-7","number":7,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما دلالة ﴿مِنْ﴾ في قوله تعالى: ﴿لِنُرِيَهُ مِنْ آيَاتِنَا﴾؟","answer":"هي للتبعيض؛ فما أُريه النبي ﷺ بعض آيات الله، وفي ذلك إشارة إلى كثرة آيات قدرته وعظمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص761، تحت «معنى الحرف «من» ودلالته»","url":""}]},{"id":"s17-8","number":8,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما مناسبة ختام آية الإسراء بقوله تعالى: ﴿إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ﴾؟","answer":"على عود الضمير إلى الله، يبين الختام إحاطته بأقوال عبده وأحواله وعنايته به، ويتضمن وعيدًا للمكذبين. ويذكر المصدر احتمال عود الضمير إلى النبي ﷺ؛ فيكون تقريرًا لتحقق سماعه وإبصاره للآيات وردًّا على من يكذبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص762، تحت «بلاغة التوكيد والتعليل في جملة التذييل»","url":""}]},{"id":"s17-9","number":9,"surah":17,"verses":[2],"references":[{"surah":17,"verses":[2]}],"verseLabel":"الإسراء: 2","question":"ما سر التعبير في قوله تعالى: ﴿آتَيْنَا مُوسَى الْكِتَابَ﴾ بالإيتاء لا الإعطاء؟","answer":"الإيتاء إيصال للمقصود مطلقًا، بخلاف الإعطاء الذي يغلب اتصاله بالعطية والمناولة؛ فناسب إنزال الكتاب وإيصاله إلى موسى عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص768، تحت «دلالة التعبير بالإيتاء دون الإعطاء»","url":""}]},{"id":"s17-10","number":10,"surah":17,"verses":[2],"references":[{"surah":17,"verses":[2]}],"verseLabel":"الإسراء: 2","question":"ما سر التعبير بـ﴿بَنِي إِسْرَائِيلَ﴾ لا «اليهود»؟","answer":"للتذكير بأصلهم ونسبتهم إلى نبي كريم، وبما يقتضيه ذلك من اتباع الهدى والوفاء بالميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص771، تحت «سر التعبير ببني إسرائيل دون اليهود»","url":""}]},{"id":"s17-11","number":11,"surah":17,"verses":[2],"references":[{"surah":17,"verses":[2]}],"verseLabel":"الإسراء: 2","question":"ما مناسبة قوله تعالى: ﴿أَلَّا تَتَّخِذُوا مِنْ دُونِي وَكِيلًا﴾ بعد ذكر الكتاب؟","answer":"لأن الكتاب هدى إلى إفراد الله بالاعتماد والعبادة، فلا يُتخذ من دونه من يفوض إليه الأمر استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص771، 773، تحت «توجيه القراءات القرآنية في «ألا تتخذوا»؛ سر التعبير بلفظ «وكيلًا»»","url":""}]},{"id":"s17-12","number":12,"surah":17,"verses":[3],"references":[{"surah":17,"verses":[3]}],"verseLabel":"الإسراء: 3","question":"ما دلالة تذكير بني إسرائيل بأنهم ﴿ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ﴾؟","answer":"تذكير لهم بنجاة أصولهم مع نوح وبالنعمة عليهم، وحث لهم على الاقتداء بشكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص777، 778، 780، تحت «دلالة النصب في «ذرية»؛ بلاغة فن الإدماج في براعة التعبير؛ توجيه تخصيص صفة الشكور بالذكر»","url":""}]},{"id":"s17-13","number":13,"surah":17,"verses":[3],"references":[{"surah":17,"verses":[3]}],"verseLabel":"الإسراء: 3","question":"ما سر وصف نوح عليه السلام بأنه ﴿عَبْدًا﴾؟","answer":"للتنويه بكمال إخلاصه وخضوعه لله؛ فالعبودية مقام غاية التذلل لمن له غاية الإفضال والإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص780، تحت «دلالة وصف نوح بالعبودية دون الرسالة أو النبوة»","url":""}]},{"id":"s17-14","number":14,"surah":17,"verses":[3],"references":[{"surah":17,"verses":[3]}],"verseLabel":"الإسراء: 3","question":"ما دلالة وصف نوح عليه السلام بـ﴿شَكُورًا﴾ بصيغة «فعول»؟","answer":"تدل صيغة المبالغة على كثرة شكره حتى صار الشكر وصفًا معروفًا ملازمًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص781، تحت «سر اختيار صيغة فعول «شكورًا»»","url":""}]},{"id":"s17-15","number":15,"surah":17,"verses":[4],"references":[{"surah":17,"verses":[4]}],"verseLabel":"الإسراء: 4","question":"ما سر تعدية ﴿قَضَيْنَا﴾ بـ﴿إِلَى﴾ في قوله تعالى: ﴿وَقَضَيْنَا إِلَى بَنِي إِسْرَائِيلَ﴾؟","answer":"ضُمّن القضاء معنى الإيحاء والإبلاغ، فجمع حتم الأمر وإيصاله إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص785، تحت «دلالة تعدية قضى بـ«إلى»»","url":""}]},{"id":"s17-16","number":16,"surah":17,"verses":[4],"references":[{"surah":17,"verses":[4]}],"verseLabel":"الإسراء: 4","question":"ما دلالة توكيد الفعلين في قوله تعالى: ﴿لَتُفْسِدُنَّ﴾ و﴿لَتَعْلُنَّ﴾؟","answer":"اللام جواب لقسم مقدر، وجاءت نون التوكيد الثقيلة لتقرير تحقق الإفساد والعلو المخبَر بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص787، 789، تحت «نوع اللام في «لتفسدن»؛ دلالة التأكيد في «لتفسدن» مع صيغة المضارع؛ معنى الواو ودلالتها»","url":""}]},{"id":"s17-17","number":17,"surah":17,"verses":[4],"references":[{"surah":17,"verses":[4]}],"verseLabel":"الإسراء: 4","question":"ما دلالة وصف العلو بقوله تعالى: ﴿عُلُوًّا كَبِيرًا﴾؟","answer":"يفخم ما يبلغونه من الاستكبار والتسلط، ويصور اتساع أثره وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص790، تحت «سر وصف العلو بالكبير دون العظيم والكثير»","url":""}]},{"id":"s17-18","number":18,"surah":17,"verses":[5],"references":[{"surah":17,"verses":[5]}],"verseLabel":"الإسراء: 5","question":"ما دلالة التعبير بالمجيء في قوله تعالى: ﴿جاء وعد أولاهما﴾؟","answer":"يقرر المجيء تحقق الوعد وحصوله عند حلول وقته، فلا يتخلف العقاب الموعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص794، تحت «دلالة التعبير بالمجيء دون الإتيان»","url":""}]},{"id":"s17-194","number":194,"surah":17,"verses":[5],"references":[{"surah":17,"verses":[5]}],"verseLabel":"الإسراء: 5","question":"ما بلاغة المجاز في قوله تعالى: ﴿جاء وعد أولاهما﴾؟","answer":"المقصود مجيء وقت الوعد أو العقاب، فحذف المضاف وأقيم الوعد مقامه إيجازًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص795، تحت «بلاغة المجاز بحذف المضاف»","url":""}]},{"id":"s17-19","number":19,"surah":17,"verses":[5],"references":[{"surah":17,"verses":[5]}],"verseLabel":"الإسراء: 5","question":"ما دلالة وصف العباد بقوله تعالى: ﴿أُولِي بَأْسٍ شَدِيدٍ﴾؟","answer":"البأس قوة يظهر أثرها في الحرب والبطش، ووصفه بالشديد يصور قوة العقوبة المسلطة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص798، 799، تحت «سر التعبير بقوله «أولي»؛ دلالة التعبير بالبأس دون القوة»","url":""}]},{"id":"s17-20","number":20,"surah":17,"verses":[5],"references":[{"surah":17,"verses":[5]}],"verseLabel":"الإسراء: 5","question":"ما سر التعبير في قوله تعالى: ﴿فَجَاسُوا خِلَالَ الدِّيَارِ﴾؟","answer":"الجوس تتبع وتخلل باستقصاء، و﴿خلال الديار﴾ يصور دخولهم بين المساكن وانتشارهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص799، 800، تحت «دلالة التعبير بالفعل «جاسوا» ماضيًا؛ دلالة التعبير بكلمة «خلال»؛ نكتة التعبير بالديار دون البلاد أو البيوت»","url":""}]},{"id":"s17-21","number":21,"surah":17,"verses":[6],"references":[{"surah":17,"verses":[6]}],"verseLabel":"الإسراء: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿رَدَدْنَا لَكُمُ الْكَرَّةَ عَلَيْهِمْ﴾ لا «الغلبة»؟","answer":"الكرة تتضمن الرجوع وتكرر الغلبة، فتُصوّر عودة القوة بعد الانكسار، وتتابع النصر؛ فهي أبلغ هنا من مجرد ذكر غلبة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص14، تحت «دلالة التعبير بالكرة دون الغلبة»","url":""}]},{"id":"s17-22","number":22,"surah":17,"verses":[6],"references":[{"surah":17,"verses":[6]}],"verseLabel":"الإسراء: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿وَأَمْدَدْنَاكُمْ بِأَمْوَالٍ وَبَنِينَ﴾؟","answer":"الإمداد زيادة متتابعة، وذكر البنين لأنهم موضع القوة والنصرة في ذلك السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص15، 16، تحت «دلالة التعبير بـ«أمددناكم»؛ دلالة التعبير بالبنين دون الأولاد»","url":""}]},{"id":"s17-23","number":23,"surah":17,"verses":[7],"references":[{"surah":17,"verses":[7]}],"verseLabel":"الإسراء: 7","question":"ما الفرق بين الإحسان الأول والثاني في قوله: ﴿إن أحسنتم أحسنتم لأنفسكم﴾؟","answer":"الإحسان الأول فعل الطاعات، والثاني جزاؤها وثمرتها العائدة إلى أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص23، تحت «الفرق بين الإحسان الأول والآخر»","url":""}]},{"id":"s17-195","number":195,"surah":17,"verses":[7],"references":[{"surah":17,"verses":[7]}],"verseLabel":"الإسراء: 7","question":"ما دلالة اللام في قوله تعالى: ﴿أحسنتم لأنفسكم﴾؟","answer":"تبين اللام رجوع منفعة الإحسان إلى صاحبه، كما تعود إليه عاقبة الإساءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص23، تحت «معنى اللام ودلالتها»","url":""}]},{"id":"s17-24","number":24,"surah":17,"verses":[7],"references":[{"surah":17,"verses":[7]}],"verseLabel":"الإسراء: 7","question":"ما سرّ التعبير في الإساءة ﴿فَلَهَا﴾ ولم يقل «فلأنفسكم»؟","answer":"عاد الضمير إلى الأنفس المذكورة، فحصل الإيجاز من غير لبس. ومن لطائف المقابلة التصريح بذكر الأنفس في مقام الإحسان والتنويه، والاكتفاء بضميرها في مقام الإساءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص26، تحت «سر التعبير بالإضمار دون الإظهار»","url":""}]},{"id":"s17-25","number":25,"surah":17,"verses":[7],"references":[{"surah":17,"verses":[7]}],"verseLabel":"الإسراء: 7","question":"ما سرّ التعبير بقوله تعالى: ﴿وَعْدُ الْآخِرَةِ﴾ لا «الثانية»؟","answer":"لأن «الآخرة» تقابل الأولى وتوحي بأنها نهاية الكرتين وعاقبتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص28، تحت «نكتة التعبير بالآخرة دون الثانية في مقابلة الأولى»","url":""}]},{"id":"s17-26","number":26,"surah":17,"verses":[7],"references":[{"surah":17,"verses":[7]}],"verseLabel":"الإسراء: 7","question":"ما سرّ التعبير بقوله تعالى: ﴿لِيَسُوءُوا وُجُوهَكُمْ﴾؟","answer":"جعلت الإساءة واقعة على الوجوه لأنها أظهر موضع للعزة والسرور، فيظهر عليها الذل والحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص30، تحت «توجيه تخصيص الوجوه بالمساءة بالذكر»","url":""}]},{"id":"s17-27","number":27,"surah":17,"verses":[8],"references":[{"surah":17,"verses":[8]}],"verseLabel":"الإسراء: 8","question":"ما مناسبة قوله تعالى: ﴿عسى ربكم أن يرحمكم﴾ لما قبله؟","answer":"بعد ذكر العقوبة فتح لهم باب الرجاء في رحمة الله إن رجعوا إلى الطاعة، فلا يقنطوا من الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص35، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s17-196","number":196,"surah":17,"verses":[8],"references":[{"surah":17,"verses":[8]}],"verseLabel":"الإسراء: 8","question":"ما سرّ التعبير باسم الرب في قوله: ﴿عسى ربكم أن يرحمكم﴾؟","answer":"يذكرهم اسم الرب بعناية الله وتربيته وإحسانه، فيقوي الرجاء في رحمته بعد العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص37، تحت «سر التعبير باسم الله الرب»","url":""}]},{"id":"s17-28","number":28,"surah":17,"verses":[8],"references":[{"surah":17,"verses":[8]}],"verseLabel":"الإسراء: 8","question":"ما سرّ التعبير بقوله تعالى: ﴿وَإِنْ عُدْتُمْ عُدْنَا﴾ بهذه المقابلة القصيرة؟","answer":"قابل عودهم إلى الإفساد بعودة العقاب؛ فالجملة تجمع الترهيب مع الرجاء السابق في رحمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص38، 39، تحت «دلالة الواو في «وإن»؛ دلالة حذف متعلق العود»","url":""}]},{"id":"s17-29","number":29,"surah":17,"verses":[9],"references":[{"surah":17,"verses":[9]}],"verseLabel":"الإسراء: 9","question":"ما سرّ التعبير بقوله تعالى: ﴿يَهْدِي لِلَّتِي هِيَ أَقْوَمُ﴾ ولم يذكر الموصوف؟","answer":"ليعم الطريقة والملة والحال والخصلة التي هي أشد استقامة في كل شأن.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص48، تحت «بلاغة حذف الموصوف في «للتي هي أقوم»»","url":""}]},{"id":"s17-30","number":30,"surah":17,"verses":[9],"references":[{"surah":17,"verses":[9]}],"verseLabel":"الإسراء: 9","question":"ما دلالة صيغة التفضيل ﴿أقوم﴾ في وصف هداية القرآن؟","answer":"تدل على أن القرآن يهدي إلى الطريق الأعدل والأشد استقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص48، تحت «دلالة التعبير بأفعل التفضيل»","url":""}]},{"id":"s17-197","number":197,"surah":17,"verses":[9],"references":[{"surah":17,"verses":[9]}],"verseLabel":"الإسراء: 9","question":"ما دلالة حذف المفضّل عليه في قوله تعالى: ﴿للتي هي أقوم﴾؟","answer":"يوسع الحذف التفضيل، فهداية القرآن أقوم من كل طريق يخالفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص49، تحت «دلالة حذف المفضل عليه»","url":""}]},{"id":"s17-31","number":31,"surah":17,"verses":[9],"references":[{"surah":17,"verses":[9]}],"verseLabel":"الإسراء: 9","question":"ما دلالة الجمع بين هداية القرآن وبشارته للمؤمنين؟","answer":"عطف البشارة يبيّن مزية أخرى للقرآن مع هدايته: فهو يسرّ المؤمنين بوعد الأجر، ويقوّي رجاءهم ويواسيهم فيما يلقونه من أذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص49، 50، تحت «دلالة الواو في «ويبشر»؛ سر التعبير بالبشارة في «ويبشر»»","url":""}]},{"id":"s17-32","number":32,"surah":17,"verses":[10],"references":[{"surah":17,"verses":[10]}],"verseLabel":"الإسراء: 10","question":"ما سر تخصيص عدم الإيمان بـ﴿الْآخِرَةِ﴾ في هذا الوعيد؟","answer":"من وجوه تخصيصه أن إنكار الآخرة سبب للتمادي في الكفر والإجرام، وأن ذكرها يناسب ما في السياق من وعد بالأجر ووعيد بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص58، 59، تحت «سر التنصيص على عدم الإيمان باليوم الآخر»","url":""}]},{"id":"s17-33","number":33,"surah":17,"verses":[11],"references":[{"surah":17,"verses":[11]}],"verseLabel":"الإسراء: 11","question":"ما سرّ التعبير بقوله تعالى: ﴿وَيَدْعُ الْإِنْسَانُ بِالشَّرِّ دُعَاءَهُ بِالْخَيْرِ﴾؟","answer":"يصور حال الإنسان حين يعجل ولا يتأمل العواقب، فيدعو على نفسه أو أهله بالشر عند الضجر كما يدعو بالخير؛ وفي ذلك تنبيه إلى التثبت فيما يطلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص64، 65، تحت «دلالة التعبير بالمضارع «ويدع»؛ دلالة اللام في «الإنسان»»","url":""}]},{"id":"s17-34","number":34,"surah":17,"verses":[11],"references":[{"surah":17,"verses":[11]}],"verseLabel":"الإسراء: 11","question":"ما سر وصف الإنسان بـ﴿عَجُولًا﴾ لا «سريعًا»؟","answer":"العجلة طلب الشيء قبل أوانه من غير روية، أما السرعة فقد تكون محمودة بعد التثبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص67، تحت «سر اختيار وصف عجولًا»","url":""}]},{"id":"s17-35","number":35,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما سرّ التعبير بقوله تعالى: ﴿فَمَحَوْنَا آيَةَ اللَّيْلِ﴾ لا «أزلناها»؟","answer":"المحو يركّز على ذهاب الأثر أو الوصف، بخلاف الإزالة التي أصلها تنحية الشيء عن مكانه. ومن توجيهاته في الآية ذهاب أثر الضوء وإظلام الليل، فيناسب مقابلة آية الليل بآية النهار المبصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص76، تحت «سر التعبير بالمحو دون الإزالة»","url":""}]},{"id":"s17-36","number":36,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما سرّ التعبير بلفظ ﴿الابتغاء﴾؟","answer":"الابتغاء طلب شديد يجمع السعي والاهتمام بتحصيل المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص79، تحت «سر التعبير بلفظ الابتغاء»","url":""}]},{"id":"s17-198","number":198,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما دلالة تنكير ﴿فضلًا﴾ في قوله: ﴿لتبتغوا فضلًا من ربكم﴾؟","answer":"يعظم التنكير ما ييسره الله من الرزق وينبه إلى سعة وجوهه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص79، تحت «دلالة تنكير «فضلًا»»","url":""}]},{"id":"s17-37","number":37,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما سر تعليل آية النهار دون التصريح بعلة آية الليل؟","answer":"اكتُفي بما يفهم من المقابلة: النهار للإبصار والابتغاء، والليل للسكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص79، تحت «بلاغة الاكتفاء في التعليل لآية النهار دون آية الليل»","url":""}]},{"id":"s17-38","number":38,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما سرّ التعبير بلفظ ﴿التفصيل﴾؟","answer":"التفصيل بيان تام للجزئيات والدقائق، فهو أخص من مطلق البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص81، تحت «سر التعبير بلفظ التفصيل»","url":""}]},{"id":"s17-199","number":199,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما دلالة تأكيد الفعل بالمصدر في قوله: ﴿فصلناه تفصيلًا﴾؟","answer":"يقرر المصدر تمام الإيضاح وإحكامه واستيفاءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص81، تحت «دلالة التعبير بالمصدر «تفصيلًا»»","url":""}]},{"id":"s17-39","number":39,"surah":17,"verses":[13],"references":[{"surah":17,"verses":[13]}],"verseLabel":"الإسراء: 13","question":"ما سرّ التعبير بالطائر عن عمل الإنسان؟","answer":"استعير الطائر للعمل والمصير الملازم لصاحبه؛ لأنهم كانوا يتفاءلون ويتشاءمون بالطير.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص87، تحت «سر التعبير بالطائر عن العمل»","url":""}]},{"id":"s17-200","number":200,"surah":17,"verses":[13],"references":[{"surah":17,"verses":[13]}],"verseLabel":"الإسراء: 13","question":"ما بلاغة الكناية في قوله تعالى: ﴿في عنقه﴾؟","answer":"العنق كناية عما لا يفارق صاحبه، فلا مهرب للإنسان من مسؤولية اختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص88، تحت «بلاغة الكناية في التعبير بالعنق»","url":""}]},{"id":"s17-40","number":40,"surah":17,"verses":[13],"references":[{"surah":17,"verses":[13]}],"verseLabel":"الإسراء: 13","question":"ما سرّ التعبير بقوله تعالى: ﴿فِي عُنُقِهِ﴾ لا «على عنقه»؟","answer":"«في» أشد في تصوير اللزوم والتداخل، كأن العمل مطوق ثابت لا موضوع يمكن نزعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص87، تحت «دلالة التعبير بالحرف «في»»","url":""}]},{"id":"s17-41","number":41,"surah":17,"verses":[14],"references":[{"surah":17,"verses":[14]}],"verseLabel":"الإسراء: 14","question":"ما سرّ التعبير بقوله تعالى: ﴿اقْرَأْ كِتَابَكَ﴾ لا «اتل كتابك»؟","answer":"القراءة أعم من التلاوة، والمراد هنا معرفة ما أُثبت في صحيفة الأعمال والإقرار به؛ أما التلاوة ففي أصلها معنى الاتباع، وليس المقام مقام اتباع ما في الصحيفة والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص95، تحت «سر التعبير بلفظ القراءة دون التلاوة»","url":""}]},{"id":"s17-42","number":42,"surah":17,"verses":[14],"references":[{"surah":17,"verses":[14]}],"verseLabel":"الإسراء: 14","question":"ما سرّ التعبير بقوله تعالى: ﴿كَفَى بِنَفْسِكَ الْيَوْمَ عَلَيْكَ حَسِيبًا﴾؟","answer":"لأن السجل يبلغ من الوضوح أن صاحبه يحاسب نفسه بنفسه ولا يحتاج إلى شاهد أبلغ منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص96، 97، تحت «معنى الباء في «بنفسك»؛ سر اختيار التعبير بـ«حسيبًا»»","url":""}]},{"id":"s17-43","number":43,"surah":17,"verses":[15],"references":[{"surah":17,"verses":[15]}],"verseLabel":"الإسراء: 15","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾؟","answer":"صوّر الذنب حملًا ثقيلًا، وقرر عدل المسؤولية الفردية فلا تنقل تبعة نفس إلى غيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص105، 106، تحت «بلاغة العطف في «ولا تزر وازرة وزر أخرى»؛ سر التعبير عن الإثم بالوزر»","url":""}]},{"id":"s17-44","number":44,"surah":17,"verses":[15],"references":[{"surah":17,"verses":[15]}],"verseLabel":"الإسراء: 15","question":"ما سر التصريح بنفي التعذيب قبل بعثة الرسول دون ذكر الإثابة؟","answer":"لأن المقام مقام إقامة الحجة وقطع أعذار المكذبين، فناسب التصريح بنفي تعذيبهم قبل بعثة الرسول، وليس السياق سياق وعد بالإثابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص107، تحت «بلاغة الاكتفاء في التصريح بالتعذيب دون الإثابة»","url":""}]},{"id":"s17-45","number":45,"surah":17,"verses":[16],"references":[{"surah":17,"verses":[16]}],"verseLabel":"الإسراء: 16","question":"ما سرّ التعبير بقوله تعالى: ﴿إِذَا أَرَدْنَا أَنْ نُهْلِكَ قَرْيَةً﴾ بـ«إذا»؟","answer":"«إذا» تدل في أصلها على تحقق ما تدخل عليه؛ فجاءت هنا لتأكيد الوعيد وتحقيقه عند وقوع موجباته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص114، تحت «دلالة التعبير بـ«إذا»»","url":""}]},{"id":"s17-46","number":46,"surah":17,"verses":[16],"references":[{"surah":17,"verses":[16]}],"verseLabel":"الإسراء: 16","question":"ما سر تخصيص ﴿مُتْرَفِيهَا﴾ بالذكر؟","answer":"لأنهم أسرع إلى الفجور وأقدر على أسبابه، ولأنهم قادة يتبعهم غيرهم؛ فذكرهم يبرز أثر فساد القيادة في شيوع الفسق. وليس في ذلك أن من لم يفسق يحمل ذنب غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص117، تحت «سر تخصيص المترفين دون غيرهم»","url":""}]},{"id":"s17-47","number":47,"surah":17,"verses":[16],"references":[{"surah":17,"verses":[16]}],"verseLabel":"الإسراء: 16","question":"ما سرّ التعبير بقوله تعالى: ﴿فَفَسَقُوا فِيهَا﴾ لا «عليها»؟","answer":"«في» تصور تغلغل الفسق في كيان القرية وانتشاره داخلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص118، 119، تحت «سر التعبير بالظرفية في «فيها»»","url":""}]},{"id":"s17-48","number":48,"surah":17,"verses":[16],"references":[{"surah":17,"verses":[16]}],"verseLabel":"الإسراء: 16","question":"لماذا عبّر بالتدمير دون الإهلاك؟","answer":"التدمير أبلغ في استئصال البنية وآثار العمران من مجرد الإهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص120، تحت «سر التعبير بالتدمير دون الإهلاك»","url":""}]},{"id":"s17-201","number":201,"surah":17,"verses":[16],"references":[{"surah":17,"verses":[16]}],"verseLabel":"الإسراء: 16","question":"ما دلالة المصدر في قوله تعالى: ﴿فدمرناها تدميرًا﴾؟","answer":"يؤكد المصدر تمام التدمير وشموله وقوة وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص120، تحت «دلالة التعبير بالمصدر «تدميرًا»»","url":""}]},{"id":"s17-49","number":49,"surah":17,"verses":[18],"references":[{"surah":17,"verses":[18]}],"verseLabel":"الإسراء: 18","question":"ما سر تسمية الدنيا ﴿الْعَاجِلَةَ﴾ في هذا السياق؟","answer":"ليفضح قصر نظر طالبها: اختار ما يعجل وينفد وترك ما يبقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص133، 134، تحت «سر اصطفاء التعبير بـ«العاجلة»»","url":""}]},{"id":"s17-50","number":50,"surah":17,"verses":[18],"references":[{"surah":17,"verses":[18]}],"verseLabel":"الإسراء: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿عَجَّلْنَا لَهُ فِيهَا مَا نَشَاءُ لِمَنْ نُرِيدُ﴾؟","answer":"قُيّد العطاء من جهتين: مقداره بما يشاؤه الله، ومن يناله بمن يريده؛ فلا يحصل كل طالب للدنيا على مطلوبه، ولا يحصل من أُعطي على كل ما أراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص135، تحت «فائدة تقييد فعل التعجيل باسمين موصولين»","url":""}]},{"id":"s17-51","number":51,"surah":17,"verses":[18],"references":[{"surah":17,"verses":[18]}],"verseLabel":"الإسراء: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿ثُمَّ جَعَلْنَا لَهُ جَهَنَّمَ﴾؟","answer":"تفيد «ثم» ترتيب العاقبة وتراخيها بعد ما يعجّل لطالب الدنيا من متاع؛ فينتقل السياق من العطاء في العاجلة إلى المصير الذي ينتظره.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص137، تحت «دلالة استعمال حرف التراخي «ثم»»","url":""}]},{"id":"s17-52","number":52,"surah":17,"verses":[19],"references":[{"surah":17,"verses":[19]}],"verseLabel":"الإسراء: 19","question":"ما سرّ التعبير بقوله تعالى: ﴿وَسَعَى لَهَا سَعْيَهَا﴾؟","answer":"الإضافة تفيد السعي اللائق بالآخرة قدرًا ونوعًا، لا أي حركة يدعيها صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص146، تحت «براعة إضافة السعي إلى ضمير الآخرة»","url":""}]},{"id":"s17-53","number":53,"surah":17,"verses":[19],"references":[{"surah":17,"verses":[19]}],"verseLabel":"الإسراء: 19","question":"ما سر تقييد السعي للآخرة بقوله تعالى: ﴿وَهُوَ مُؤْمِنٌ﴾؟","answer":"لأن العمل لا يثمر ثواب الآخرة بلا أصل يوجهه إلى الله ويصدق بوعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص147، تحت «فائدة التقييد بجملة الحال»","url":""}]},{"id":"s17-54","number":54,"surah":17,"verses":[20],"references":[{"surah":17,"verses":[20]}],"verseLabel":"الإسراء: 20","question":"ما سرّ التعبير بقوله تعالى: ﴿كُلًّا نُمِدُّ هَؤُلَاءِ وَهَؤُلَاءِ﴾؟","answer":"قدّم «كلا» لإفادة العموم: عطاء الربوبية يصل إلى طالب الدنيا وطالب الآخرة في دار الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص151، تحت «غرض تقديم المفعول»","url":""}]},{"id":"s17-55","number":55,"surah":17,"verses":[20],"references":[{"surah":17,"verses":[20]}],"verseLabel":"الإسراء: 20","question":"ما غرض إضافة العطاء إلى الرب في قوله: ﴿عطاء ربك﴾؟","answer":"تشعر الإضافة بسعة عطاء الرب وتدبيره وإنعامه على الخلق بحسب حكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص155، تحت «غرض إضافة العطاء إلى لفظ الربوبية»","url":""}]},{"id":"s17-202","number":202,"surah":17,"verses":[20],"references":[{"surah":17,"verses":[20]}],"verseLabel":"الإسراء: 20","question":"ما دلالة قوله تعالى: ﴿وما كان عطاء ربك محظورًا﴾؟","answer":"ينفي أن يكون عطاء الرب الدنيوي محبوسًا عن الخلق؛ فيصيب المؤمن والكافر بحسب المشيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص156، تحت «دلالة التعبير بالكون المنفي»","url":""}]},{"id":"s17-56","number":56,"surah":17,"verses":[21],"references":[{"surah":17,"verses":[21]}],"verseLabel":"الإسراء: 21","question":"ما سرّ التعبير بقوله تعالى: ﴿انْظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَى بَعْضٍ﴾؟","answer":"وجّه إلى تفاوت الدنيا المشاهد ليقاس عليه تفاوت الآخرة الأعظم والأبقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص160، تحت «غرض الأمر بالنظر»","url":""}]},{"id":"s17-57","number":57,"surah":17,"verses":[22],"references":[{"surah":17,"verses":[22]}],"verseLabel":"الإسراء: 22","question":"ما سرّ تقديم ﴿مَعَ اللَّهِ﴾ في النهي عن الشرك؟","answer":"لتشنيع مجرد الجمع بين الله وغيره في العبادة، قبل النظر في ماهية الشريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص166، تحت «غرض تقديم قوله «مع الله»»","url":""}]},{"id":"s17-58","number":58,"surah":17,"verses":[22],"references":[{"surah":17,"verses":[22]}],"verseLabel":"الإسراء: 22","question":"ما دلالة الجمع بين ﴿مَذْمُومًا مَخْذُولًا﴾ في عاقبة الشرك؟","answer":"يستحق المشرك الذم إذ يشرك بخالقه المنعم عليه، ويقع في الخذلان لأنه يتخذ إلهًا لا يملك له نصرًا ولا نفعًا؛ فجُمعت خسارته في الرأي والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص168، تحت «توجيه تخصيص الذم والخذلان بالذكر»","url":""}]},{"id":"s17-59","number":59,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما سرّ التعبير بقوله تعالى: ﴿وَقَضَى رَبُّكَ﴾؟","answer":"القضاء يدل على الأمر المحكم الذي لا يقبل التردد، و«ربك» تلطف يربط التكليف بالتربية والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص173، 174، تحت «دلالة اختيار لفظة «قضى»؛ مناسبة اختيار الربوبية دون الألوهية»","url":""}]},{"id":"s17-60","number":60,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما سر عطف الإحسان إلى الوالدين على الأمر بتوحيد الله؟","answer":"لأنهما السبب الظاهر في الوجود والتربية بعد فضل الخالق، فجاء شكرهما عقب توحيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص176، تحت «مناسبة عطف بر الوالدين على توحيد الله»","url":""}]},{"id":"s17-61","number":61,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"لماذا خُصّت حالة الكبر في الوصية بالوالدين؟","answer":"لأن الكبر زمن اشتداد حاجتهما وضعفهما، فيلزم الولد مزيد الرعاية والصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص178، تحت «توجيه تخصيص حالة الكبر بالذكر»","url":""}]},{"id":"s17-203","number":203,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما غرض تقديم ﴿عندك﴾ في قوله: ﴿إما يبلغن عندك الكبر﴾؟","answer":"يجعل رعايتهما مسؤولية حاضرة في بيت الولد وتحت عنايته المباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص180، تحت «غرض تقديم الظرف»","url":""}]},{"id":"s17-62","number":62,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما سر البدء بالنهي عن كلمة ﴿أُفٍّ﴾ في الوصية بالوالدين؟","answer":"نهى عن أدنى صوت تضجر ليكون ما فوقه من الإيذاء أولى بالتحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص183، تحت «غرض النهي عن التأفف»","url":""}]},{"id":"s17-63","number":63,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما سرّ التعبير بقوله تعالى: ﴿قَوْلًا كَرِيمًا﴾؟","answer":"لم يطلب ترك الأذى فقط، بل كلامًا يكرم الوالدين ويشعرهما بالمكانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص185، تحت «دلالة التعبير بالمفعول المطلق، وتقييده بالصفة»","url":""}]},{"id":"s17-64","number":64,"surah":17,"verses":[24],"references":[{"surah":17,"verses":[24]}],"verseLabel":"الإسراء: 24","question":"ما بلاغة الاستعارة في قوله: ﴿واخفض لهما جناح الذل﴾؟","answer":"شبه لين الجانب والحماية بخفض الطائر جناحه لمن يضمه ويرعاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص189، تحت «بلاغة الاستعارة المكنية التمثيلية»","url":""}]},{"id":"s17-204","number":204,"surah":17,"verses":[24],"references":[{"surah":17,"verses":[24]}],"verseLabel":"الإسراء: 24","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من الرحمة﴾؟","answer":"تبين أن هذا التواضع للوالدين ناشئ من الرحمة والمحبة، لا من المهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص191، تحت «معنى حرف «من» ودلالته»","url":""}]},{"id":"s17-65","number":65,"surah":17,"verses":[24],"references":[{"surah":17,"verses":[24]}],"verseLabel":"الإسراء: 24","question":"ما سر الدعاء للوالدين بـ﴿رَبِّ ارْحَمْهُمَا﴾؟","answer":"اسم الرب يستحضر التربية التي تلقاها منهما، فيسأل ربه أن يجازيهما برحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص193، تحت «سر اصطفاء لفظ الربوبية»","url":""}]},{"id":"s17-66","number":66,"surah":17,"verses":[25],"references":[{"surah":17,"verses":[25]}],"verseLabel":"الإسراء: 25","question":"ما سرّ التعبير بقوله تعالى: ﴿رَبُّكُمْ أَعْلَمُ بِمَا فِي نُفُوسِكُمْ﴾ لا «بنفوسكم»؟","answer":"«في» تتناول ما يستقر ويجول داخل النفس من قصد خفي لا يطلع عليه الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص199، تحت «نكتة إيثار حرف الظرفية دون الباء»","url":""}]},{"id":"s17-67","number":67,"surah":17,"verses":[25],"references":[{"surah":17,"verses":[25]}],"verseLabel":"الإسراء: 25","question":"ما سرّ التعبير بقوله تعالى: ﴿لِلْأَوَّابِينَ غَفُورًا﴾؟","answer":"لأن البر قد تقع فيه هفوة، ففتح المغفرة لمن يكثر الرجوع إلى الله وإصلاح التقصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص201، تحت «نكتة المبالغة في استعمال صيغة «فعّال»»","url":""}]},{"id":"s17-68","number":68,"surah":17,"verses":[26],"references":[{"surah":17,"verses":[26]}],"verseLabel":"الإسراء: 26","question":"ما دلالة ترتيب ذي القربى والمسكين وابن السبيل في الأمر بالإحسان؟","answer":"يضم الترتيب أصناف المستحقين بدءًا بالأقرب: ذي القرابة، ثم المسكين المحتاج، ثم ابن السبيل الذي بَعُد عن أهله وماله؛ فيبيّن مراتب العناية بأصحاب الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص205، تحت «نكتة ترتيب المذكورين بالإحسان إليهم»","url":""}]},{"id":"s17-69","number":69,"surah":17,"verses":[27],"references":[{"surah":17,"verses":[27]}],"verseLabel":"الإسراء: 27","question":"ما سر وصف المبذرين بأنهم ﴿إِخْوَانَ الشَّيَاطِينِ﴾؟","answer":"لأنهم شابهوهم في إفساد النعمة وصرفها في غير وجهها، فالأخوة أخوة طريقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص211، تحت «بلاغة الاستعارة التصريحية»","url":""}]},{"id":"s17-70","number":70,"surah":17,"verses":[27],"references":[{"surah":17,"verses":[27]}],"verseLabel":"الإسراء: 27","question":"ما سرّ التعبير بقوله تعالى: ﴿وَكَانَ الشَّيْطَانُ لِرَبِّهِ كَفُورًا﴾؟","answer":"يربط التبذير بجذره الباطني: كفران النعمة وعدم وضعها فيما أراد المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص213، تحت «دلالة التعبير بصيغة المبالغة»","url":""}]},{"id":"s17-71","number":71,"surah":17,"verses":[28],"references":[{"surah":17,"verses":[28]}],"verseLabel":"الإسراء: 28","question":"ما دلالة التعبير بـ﴿تُعْرِضَنَّ عَنْهُمُ﴾ في حال عدم القدرة على العطاء؟","answer":"من توجيهاته أنه مجاز عن عدم النفع لعدم القدرة على العطاء، لا عن صدّ المحتاج جفاءً. ويذكر المصدر أيضًا حمله على الإعراض حياءً حين لا يجد المعطي ما يعطيه؛ لذلك أُمر بالقول اللين الذي يجبر خاطر السائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص217، تحت «معنى الإعراض بين الحقيقة والمجاز»","url":""}]},{"id":"s17-72","number":72,"surah":17,"verses":[28],"references":[{"surah":17,"verses":[28]}],"verseLabel":"الإسراء: 28","question":"لماذا عبّر عن الرزق بالرحمة في قوله: ﴿رحمة من ربك﴾؟","answer":"سمي الرزق رحمة ليظل المعطي راجيًا فضل الله لا مالكًا مستقلًا للعطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص220، تحت «دلالة التعبير عن الرزق بالرحمة مجازًا مرسلًا»","url":""}]},{"id":"s17-205","number":205,"surah":17,"verses":[28],"references":[{"surah":17,"verses":[28]}],"verseLabel":"الإسراء: 28","question":"ما سرّ إضافة الرحمة إلى الرب في قوله: ﴿رحمة من ربك﴾؟","answer":"تستحضر الإضافة عناية الرب وتدبيره وإحسانه بالنبي وبالسائلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص221، تحت «سر إضافة الرحمة إلى الرب»","url":""}]},{"id":"s17-73","number":73,"surah":17,"verses":[28],"references":[{"surah":17,"verses":[28]}],"verseLabel":"الإسراء: 28","question":"ما سرّ التعبير بقوله تعالى: ﴿قَوْلًا مَيْسُورًا﴾ لا «معروفًا»؟","answer":"الميسور كلام سهل لطيف يخفف الحرج ويعد بالخير، فكأنه عطاء ميسر حين تعذر المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص226، تحت «علة وصف القول بالميسور دون المعروف»","url":""}]},{"id":"s17-74","number":74,"surah":17,"verses":[29],"references":[{"surah":17,"verses":[29]}],"verseLabel":"الإسراء: 29","question":"ما سر تصوير البخل بيد مغلولة إلى العنق؟","answer":"يجسد شدة الإمساك بصورة يد لا تستطيع الامتداد أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص235، 236، تحت «براعة انتقاء مفردة «مغلولة» دون مقبوضة؛ براعة الاستعارة التمثيلية لحال الشحيح»","url":""}]},{"id":"s17-75","number":75,"surah":17,"verses":[29],"references":[{"surah":17,"verses":[29]}],"verseLabel":"الإسراء: 29","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَبْسُطْهَا كُلَّ الْبَسْطِ﴾؟","answer":"لم ينه عن البسط بل عن استغراقه، فدل على الاقتصاد بين البخل والإسراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص240، تحت «نكتة التقييد بـ«كل» النائب عن المفعول المطلق، مضافًا إلى المصدر»","url":""}]},{"id":"s17-76","number":76,"surah":17,"verses":[30],"references":[{"surah":17,"verses":[30]}],"verseLabel":"الإسراء: 30","question":"ما سرّ التعبير بقوله تعالى: ﴿إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ... وَيَقْدِرُ﴾ بعد الأمر بالاعتدال؟","answer":"ليعلّم أن تفاوت الرزق بتدبير خبير، فلا يحمل الضيق على بخل ولا السعة على إسراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص249، تحت «بلاغة تذييل جمل الأوامر السابقة بهذه الآية»","url":""}]},{"id":"s17-77","number":77,"surah":17,"verses":[30],"references":[{"surah":17,"verses":[30]}],"verseLabel":"الإسراء: 30","question":"ما سرّ تقديم ﴿بِعِبَادِهِ﴾ في ﴿كَانَ بِعِبَادِهِ خَبِيرًا بَصِيرًا﴾؟","answer":"يفيد الاهتمام بالعباد والتشويق إلى الخبر عن إحاطة علم الله بهم؛ فبسط الرزق وتقديره يجريان على علم بأحوالهم وما يصلحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص253، تحت «سر تقديم شبه الجملة «بعباده» على الخبر»","url":""}]},{"id":"s17-78","number":78,"surah":17,"verses":[31],"references":[{"surah":17,"verses":[31]}],"verseLabel":"الإسراء: 31","question":"ما سرّ التعبير هنا بـ﴿خَشْيَةَ إِمْلَاقٍ﴾ وفي الأنعام ﴿مِنْ إِمْلَاقٍ﴾؟","answer":"هنا الفقر متوقع فقدم رزق الأولاد: ﴿نحن نرزقهم وإياكم﴾؛ وهناك الفقر واقع فقدم رزق الآباء: ﴿نحن نرزقكم وإياهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص261، 262، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s17-79","number":79,"surah":17,"verses":[31],"references":[{"surah":17,"verses":[31]}],"verseLabel":"الإسراء: 31","question":"ما دلالة وصف قتل الأولاد بأنه ﴿خِطْئًا كَبِيرًا﴾؟","answer":"«خِطئًا» في هذه القراءة إثم، ووصفه بالكبير يعظّم الجريمة وينفّر منها. وجاء التصريح بشدة قبحها لإبطال استحسانها في نفوس من اعتادها خوفًا من الفقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص264، 265، تحت «توجيه القراءات في قوله «خطئًا»؛ نكتة وصف «خطئًا» بـ«كبيرًا»»","url":""}]},{"id":"s17-80","number":80,"surah":17,"verses":[32],"references":[{"surah":17,"verses":[32]}],"verseLabel":"الإسراء: 32","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَقْرَبُوا الزِّنَا﴾ لا «ولا تزنوا»؟","answer":"ليحرم الفعل وكل الطرق والمقدمات التي تقرب إليه، فيسد الباب قبل الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص270، تحت «بلاغة إيثار «ولا تقربوا» في النهي عن الزنى دون ولا تزنوا»","url":""}]},{"id":"s17-81","number":81,"surah":17,"verses":[32],"references":[{"surah":17,"verses":[32]}],"verseLabel":"الإسراء: 32","question":"ما سرّ التعبير بقوله تعالى: ﴿إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا﴾؟","answer":"جمع قبح الفعل في ذاته وقبح الطريق الذي يفضي إليه من اختلاط الأنساب وفساد المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص272، 273، 274، تحت «سر التعبير بلفظ «فاحشة» دون غيره؛ دلالة كلمة «وساء» ووجه التعبير بها عن قبح الزنى؛ بلاغة الاستعارة في التعبير عن الطريق بالسبيل»","url":""}]},{"id":"s17-82","number":82,"surah":17,"verses":[33],"references":[{"surah":17,"verses":[33]}],"verseLabel":"الإسراء: 33","question":"ما سرّ التعبير بقوله تعالى: ﴿النَّفْسَ الَّتِي حَرَّمَ اللَّهُ﴾؟","answer":"أظهر اسم الجلالة ليعظم حرمة النفس؛ فالاعتداء عليها انتهاك لما حرمه الله نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص280، تحت «سر التعبير باسم الجلالة دون غيره»","url":""}]},{"id":"s17-83","number":83,"surah":17,"verses":[33],"references":[{"surah":17,"verses":[33]}],"verseLabel":"الإسراء: 33","question":"ما سرّ التعبير بقوله تعالى: ﴿فَقَدْ جَعَلْنَا لِوَلِيِّهِ سُلْطَانًا﴾؟","answer":"يجمع لفظ السلطان معنى الحجة والحق الذي أثبته الله لولي المقتول في القصاص أو الدية أو العفو. ويبين المصدر أن استيفاء القصاص يكون بإشراف ولي الأمر، فلا يعني السلطان إطلاق يد الولي في القتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص286، 287، تحت «سر التعبير بالمصدر «سلطانًا»؛ بلاغة الإجمال في اختيار مفردة «سلطانًا»»","url":""}]},{"id":"s17-84","number":84,"surah":17,"verses":[33],"references":[{"surah":17,"verses":[33]}],"verseLabel":"الإسراء: 33","question":"ما دلالة النهي عن الإسراف في القتل بعد إثبات الحق لولي المقتول؟","answer":"حتى لا يتحول إنصاف المظلوم إلى ظلم جديد بتجاوز القاتل إلى غيره أو التمثيل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص288، تحت «دلالة النهي عن الإسراف في القتل»","url":""}]},{"id":"s17-85","number":85,"surah":17,"verses":[34],"references":[{"surah":17,"verses":[34]}],"verseLabel":"الإسراء: 34","question":"ما سر التعبير بـ﴿وَلَا تَقْرَبُوا﴾ في شأن مال اليتيم؟","answer":"النهي عن القربان يبالغ في حماية مال اليتيم ويحذر من التصرف فيه بغير حق؛ والاستثناء ﴿إِلَّا بِالَّتِي هِيَ أَحْسَنُ﴾ يوجّه إلى حفظه واستثماره لمصلحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص295، 296، تحت «بلاغة التعبير بالنهي عن قربان مال اليتيم»","url":""}]},{"id":"s17-86","number":86,"surah":17,"verses":[34],"references":[{"surah":17,"verses":[34]}],"verseLabel":"الإسراء: 34","question":"ما سر حذف متعلق ﴿مَسْئُولًا﴾ في قوله تعالى: ﴿إِنَّ الْعَهْدَ كَانَ مَسْئُولًا﴾؟","answer":"حُذف متعلق السؤال اكتفاءً بدلالة الحال؛ فالسياق يبيّن أن السؤال عن الوفاء بالعهد أو نقضه، فلا حاجة إلى التصريح به.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص304، تحت «سر حذف متعلق «مسؤولًا»»","url":""}]},{"id":"s17-87","number":87,"surah":17,"verses":[35],"references":[{"surah":17,"verses":[35]}],"verseLabel":"الإسراء: 35","question":"ما سرّ التعبير بقوله تعالى: ﴿وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ﴾؟","answer":"القسطاس هو الميزان، ويحتمل معنى العدل؛ ووصفه بالمستقيم يؤكد ضرورة سلامة معيار الوزن والتحري فيه حتى يتحقق الإنصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص311، 312، تحت «دلالة الباء في «بالقسطاس»؛ علة الاكتفاء بوصف القسطاس بالمستقيم؛ بلاغة التصريح بالوصف مع اشتمال الموصوف عليه»","url":""}]},{"id":"s17-88","number":88,"surah":17,"verses":[35],"references":[{"surah":17,"verses":[35]}],"verseLabel":"الإسراء: 35","question":"ما سرّ التعبير بقوله تعالى: ﴿ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا﴾؟","answer":"العدل خير في الحال، وأحسن عاقبةً ومرجعًا في الثقة والرزق والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص314، 315، تحت «دلالة مجيء «وأحسن تأويلًا» بعد «ذلك خير»؛ معنى التأويل ودلالة صيغة التفعيل»","url":""}]},{"id":"s17-89","number":89,"surah":17,"verses":[36],"references":[{"surah":17,"verses":[36]}],"verseLabel":"الإسراء: 36","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ﴾؟","answer":"«تقف» تتبع الأثر؛ فالنهي يشمل اتباع الظن في القول والحكم والسلوك بلا علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص319، 320، 321، تحت «بلاغة المجاز المرسل في قوله «ولا تقف»؛ سر التعبير بـ«ما» دون غيرها؛ سر تنكير «علم»»","url":""}]},{"id":"s17-90","number":90,"surah":17,"verses":[36],"references":[{"surah":17,"verses":[36]}],"verseLabel":"الإسراء: 36","question":"ما سر تخصيص ﴿السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ﴾ بالذكر في المسؤولية؟","answer":"جمع منافذ المعرفة الظاهرة وباطن الفهم، ليحمّل الإنسان مسؤولية طريق العلم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص323، تحت «نكتة تخصيص هذه الأعضاء بالذكر»","url":""}]},{"id":"s17-91","number":91,"surah":17,"verses":[36],"references":[{"surah":17,"verses":[36]}],"verseLabel":"الإسراء: 36","question":"ما سرّ التعبير بقوله تعالى: ﴿الْفُؤَادَ﴾ لا «القلب»؟","answer":"الفؤاد يستحضر القلب في حال التوقد والإدراك، وهو الأنسب لمقام التثبت والشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص324، تحت «لطيف الإشارة بذكر الفؤاد دون القلب»","url":""}]},{"id":"s17-92","number":92,"surah":17,"verses":[37],"references":[{"surah":17,"verses":[37]},{"surah":31,"verses":[18]}],"verseLabel":"الإسراء: 37؛ لقمان: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا﴾ لا «فرحًا»؟","answer":"في الإسراء، المرح فرح يتجاوز إلى البطر والخيلاء، أما الفرح فقد يكون محمودًا. وفي لقمان أيضًا تصوّر مشية المرح التبختر والكبر، فيكون النهي عنها نهيًا عن التكبر بصوره؛ ويذكّر ذكر الأرض الإنسان بأصله وحدوده فيحمله على التواضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص333، تحت «سر التعبير بالمرح دون الفرح»","url":""}]},{"id":"s17-93","number":93,"surah":17,"verses":[37],"references":[{"surah":17,"verses":[37]}],"verseLabel":"الإسراء: 37","question":"ما دلالة مواجهة المتكبر بقوله: ﴿لن تخرق الأرض﴾؟","answer":"تحطم العبارة وهمه؛ فلن يشق الأرض بقوة خطوه مهما تكبر وتبختر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص335، تحت «دلالة التعبير بالخرق»","url":""}]},{"id":"s17-206","number":206,"surah":17,"verses":[37],"references":[{"surah":17,"verses":[37]}],"verseLabel":"الإسراء: 37","question":"ما دلالة قوله تعالى: ﴿ولن تبلغ الجبال طولًا﴾؟","answer":"تضع كبره أمام ضخامة الجبال، فلن يبلغها طولًا مهما انتفخ وتعاظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص336، تحت «دلالة ذكر قوله «ولن تبلغ الجبال طولًا»»","url":""}]},{"id":"s17-94","number":94,"surah":17,"verses":[38],"references":[{"surah":17,"verses":[38]}],"verseLabel":"الإسراء: 38","question":"ما سر إفراد اسم الإشارة ﴿ذَلِكَ﴾ بعد تعدد الوصايا؟","answer":"جُمعت الخصال في اسم إشارة مفرد لإبراز وحدتها وتكاملها، واستوائها في وجوب الانقياد لحكم الله فيها؛ فلا ينتقي المرء بعض الوصايا ويترك بعضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص344، تحت «بلاغة العدول عن الجمع إلى الإفراد في «ذلك»»","url":""}]},{"id":"s17-95","number":95,"surah":17,"verses":[38],"references":[{"surah":17,"verses":[38]}],"verseLabel":"الإسراء: 38","question":"ما سرّ تقديم ﴿عِنْدَ رَبِّكَ﴾ على ﴿مَكْرُوهًا﴾؟","answer":"قدّم الظرف للاهتمام بكون هذه الأفعال مكروهة عند الله، فيشتد التنفير منها؛ وذكر الرب يذكّر بقبح مقابلة إحسان المنعم بمعصيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص346، 347، تحت «بلاغة تقديم «عند ربك» على «مكروهًا»؛ فائدة التعبير بالربوبية في «عند ربك»»","url":""}]},{"id":"s17-96","number":96,"surah":17,"verses":[39],"references":[{"surah":17,"verses":[39]}],"verseLabel":"الإسراء: 39","question":"ما سر وصف هذه الوصايا بأنها ﴿مِنَ الْحِكْمَةِ﴾؟","answer":"لإحكام هذه التكاليف وكمالها، وموافقة العقل لصحتها، واشتراك الشرائع في أصولها؛ فهي تجمع التوحيد والطاعات والتوجه إلى الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص353، تحت «نكتة كون التكاليف المشار إليها من الحكمة»","url":""}]},{"id":"s17-97","number":97,"surah":17,"verses":[39],"references":[{"surah":17,"verses":[39]}],"verseLabel":"الإسراء: 39","question":"ما سر تكرار النهي عن الشرك في ختام سلسلة الوصايا؟","answer":"ليطوق الأحكام بالتوحيد أولًا وآخرًا، فكل الأخلاق بين أصلها وعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص354، تحت «نكتة تكرار النهي عن اتخاذ إله مع الله»","url":""}]},{"id":"s17-98","number":98,"surah":17,"verses":[39],"references":[{"surah":17,"verses":[39]}],"verseLabel":"الإسراء: 39","question":"ما سر اختلاف الخاتمتين: ﴿مَذْمُومًا مَخْذُولًا﴾ و﴿مَلُومًا مَدْحُورًا﴾؟","answer":"الأولى حال المشرك في الدنيا بين الذم والخذلان، والثانية عاقبته في جهنم بين اللوم والطرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص356، تحت «الموازنة بين الآيتين 39 و22 من السورة»","url":""}]},{"id":"s17-99","number":99,"surah":17,"verses":[40],"references":[{"surah":17,"verses":[40]}],"verseLabel":"الإسراء: 40","question":"ما سرّ التعبير بقوله تعالى: ﴿أَفَأَصْفَاكُمْ رَبُّكُمْ بِالْبَنِينَ﴾؟","answer":"الاستفهام يفضح تناقضهم: زعموا لأنفسهم ما يحبون ونسبوا إلى الله ما يكرهون.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص362، 363، 364، تحت «غرض التعبير بالاستفهام «أفأصفاكم»؛ سر التقييد بقوله «بالبنين»»","url":""}]},{"id":"s17-100","number":100,"surah":17,"verses":[41],"references":[{"surah":17,"verses":[41]}],"verseLabel":"الإسراء: 41","question":"ما سرّ التعبير بقوله تعالى: ﴿صَرَّفْنَا فِي هَذَا الْقُرْآنِ﴾؟","answer":"التصريف تنويع الحجج والأمثال والأساليب حتى تتفتح للحق طرق متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص373، تحت «معنى التصريف ودلالته في سياق الآية»","url":""}]},{"id":"s17-101","number":101,"surah":17,"verses":[41],"references":[{"surah":17,"verses":[41]}],"verseLabel":"الإسراء: 41","question":"ما سر حذف مفعول ﴿صَرَّفْنَا﴾ في هذه الآية؟","answer":"لإفادة العموم؛ فيشمل التصريف ما يسوقه القرآن لإبطال أقوالهم من أدلة ومواعظ وأمثال وترغيب وترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص374، 375، تحت «غرض حذف المفعول به من الفعل «صرفنا»»","url":""}]},{"id":"s17-102","number":102,"surah":17,"verses":[41],"references":[{"surah":17,"verses":[41]}],"verseLabel":"الإسراء: 41","question":"ما دلالة القصر في قوله: ﴿وما يزيدهم إلا نفورًا﴾؟","answer":"يقصر أثر عنادهم عند سماع القرآن على ازدياد النفور، فيكشف أن الخلل في إرادتهم لا في وضوح الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص376، تحت «غرض التعبير بأسلوب القصر»","url":""}]},{"id":"s17-207","number":207,"surah":17,"verses":[41],"references":[{"surah":17,"verses":[41]}],"verseLabel":"الإسراء: 41","question":"ما دلالة المضارع في قوله: ﴿يزيدهم﴾؟","answer":"يصوّر تجدد نفورهم كلما تجدد سماع البيان، لا نفورًا وقع مرة وانتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص377، تحت «دلالة التعبير بالمضارع «يزيدهم»»","url":""}]},{"id":"s17-103","number":103,"surah":17,"verses":[42],"references":[{"surah":17,"verses":[42]}],"verseLabel":"الإسراء: 42","question":"ما دلالة الشرط في قوله: ﴿لو كان معه آلهة كما يقولون لابتغوا إلى ذي العرش سبيلًا﴾؟","answer":"يفرض زعمهم جدلًا ثم يلزمهم ببطلانه: فلو وُجدت آلهة لظهر افتقارها إلى الله أو طلبها مغالبته، وكلا الوجهين يهدم دعوى الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص380، تحت «غرض التعبير بأسلوب الشرط»","url":""}]},{"id":"s17-208","number":208,"surah":17,"verses":[42],"references":[{"surah":17,"verses":[42]}],"verseLabel":"الإسراء: 42","question":"ما دلالة وصف الله بـ﴿ذي العرش﴾ في الرد على المشركين؟","answer":"يستحضر كمال ملك الله وسلطانه في مقابل عجز ما يعبدون وافتقاره إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص383، تحت «إيثار التعبير بالمجرور مضافًا «ذي العرش»»","url":""}]},{"id":"s17-104","number":104,"surah":17,"verses":[43],"references":[{"surah":17,"verses":[43]}],"verseLabel":"الإسراء: 43","question":"ما سرّ التعبير بقوله تعالى: ﴿عُلُوًّا كَبِيرًا﴾ بعد ﴿سُبْحَانَهُ وَتَعَالَى﴾؟","answer":"المصدر يؤكد تنزه الله وعلوه الحقيقي، ووصفه بالكبير يبالغ في بيان براءته مما نسبوه إليه من شريك أو ولد؛ فهو كمال لا تلحقه دعاواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص389، تحت «دلالة التعبير بالمفعول المطلق «علوًا»؛ سر وصف المفعول المطلق بلفظ «كبيرًا»»","url":""}]},{"id":"s17-105","number":105,"surah":17,"verses":[44],"references":[{"surah":17,"verses":[44]}],"verseLabel":"الإسراء: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ﴾؟","answer":"النفي والاستثناء يستغرقان كل موجود، فيتحول الكون كله إلى شاهد توحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص397، تحت «سر التعبير بأسلوب الاستغراق في «وإن من شيء»»","url":""}]},{"id":"s17-106","number":106,"surah":17,"verses":[44],"references":[{"surah":17,"verses":[44]}],"verseLabel":"الإسراء: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿لَا تَفْقَهُونَ تَسْبِيحَهُمْ﴾ لا «لا تسمعون»؟","answer":"الفقه فهم المعنى، فلا يلزم من عدم فهم التسبيح نفي وقوعه. ويذكر المصدر أن الاستدراك يدفع توهم أن تسبيح الكائنات يماثل كلام الإنسان الذي يدركه السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص399، 401، تحت «دلالة العطف في «ولكن لا تفقهون»؛ الفقه والعلم»","url":""}]},{"id":"s17-107","number":107,"surah":17,"verses":[44],"references":[{"surah":17,"verses":[44]}],"verseLabel":"الإسراء: 44","question":"ما سر ختام آية تسبيح الكائنات بقوله تعالى: ﴿حَلِيمًا غَفُورًا﴾؟","answer":"مع أن الكون يسبحه والإنسان يقصر أو يشرك، يمهله بحلمه ويفتح له المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص400، تحت «نكتة الاقتران بين الاسمين الجليلين»","url":""}]},{"id":"s17-108","number":108,"surah":17,"verses":[45],"references":[{"surah":17,"verses":[45]}],"verseLabel":"الإسراء: 45","question":"ما دلالة وصف الحجاب بـ﴿مَسْتُورًا﴾ عند قراءة القرآن؟","answer":"من توجيهاته أن «مستورًا» بمعنى ساتر، إسنادًا للوصف على سبيل المجاز؛ ومن توجيهاته أنه حجاب خفي لا تدركه الأبصار. والسياق يصور الحاجز الذي يحول دون انتفاع المكذبين بالقرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص408، 409، تحت «بلاغة المجاز العقلي في الحجاب المستور»","url":""}]},{"id":"s17-109","number":109,"surah":17,"verses":[46],"references":[{"surah":17,"verses":[46]},{"surah":18,"verses":[57]}],"verseLabel":"الإسراء: 46؛ الكهف: 57","question":"ما سرّ التعبير بقوله تعالى: ﴿عَلَى قُلُوبِهِمْ أَكِنَّةً﴾ و﴿فِي آذَانِهِمْ وَقْرًا﴾؟","answer":"في الإسراء والكهف، تصور «على» الأكنة مستعلية على القلوب متمكنة منها، كالأغطية الحاجبة للفهم. وتصور «في» الوقر مستقرًا في الآذان، فلا ينتفع أصحابها بالسماع؛ فيجتمع حجب الفهم وثقل السمع في تصوير الإعراض عن القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص416، تحت «نكتة حرف الظرفية «في» مقابل حرف الاستعلاء «على»»","url":""}]},{"id":"s17-110","number":110,"surah":17,"verses":[46],"references":[{"surah":17,"verses":[46]}],"verseLabel":"الإسراء: 46","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَّوْا عَلَى أَدْبَارِهِمْ نُفُورًا﴾؟","answer":"«على أدبارهم» كناية عن شدة الإعراض عن القرآن والتوحيد، و«نفورًا» يزيد تصوير هذا الصدود وتأكيده؛ فليس موقفهم مجرد ترك للاستماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص420، 421، تحت «سر تقييد الفعل «ولوا» بالجار والمجرور؛ سر تقييد الفعل بـ«نفورًا»»","url":""}]},{"id":"s17-111","number":111,"surah":17,"verses":[47],"references":[{"surah":17,"verses":[47]}],"verseLabel":"الإسراء: 47","question":"ما سرّ التعبير بقوله تعالى: ﴿نَحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِ﴾؟","answer":"يكشف أن استماعهم لم يكن طلب هدى بل ترصدًا واستهزاء، والله أعلم بدافع السماع الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص424، 425، 426، 427، تحت «نكتة التعبير باسم الموصول «ما»؛ معنى الباء في «به» ودلالتها؛ سر تقييد الفعل بالحال المؤولة»","url":""}]},{"id":"s17-112","number":112,"surah":17,"verses":[47],"references":[{"surah":17,"verses":[47]}],"verseLabel":"الإسراء: 47","question":"ما سر الإخبار عنهم بالمصدر في قوله تعالى: ﴿وَإِذْ هُمْ نَجْوَى﴾؟","answer":"النجوى تناجيهم وتآمرهم، ووصفهم بالمصدر مبالغة في كثرة التناجي حتى كأنهم صاروا نجوى. والجملة الاسمية تصور ثباتهم عليه، مع إحاطة علم الله باستماعهم وتناجيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص429، تحت «دلالة التعبير بالمسند مصدرًا»","url":""}]},{"id":"s17-113","number":113,"surah":17,"verses":[48],"references":[{"surah":17,"verses":[48]},{"surah":25,"verses":[9]}],"verseLabel":"الإسراء: 48؛ الفرقان: 9","question":"ما دلالة الاستفهام بـ﴿كيف﴾ في قوله: ﴿انظر كيف ضربوا لك الأمثال﴾؟","answer":"يدعو إلى التعجب من طرائق افترائهم المتناقضة على الرسول، لا إلى السؤال عن هيئة مجهولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص436، تحت «غرض الاستفهام بـ«كيف»»","url":""}]},{"id":"s17-209","number":209,"surah":17,"verses":[48],"references":[{"surah":17,"verses":[48]},{"surah":25,"verses":[9]}],"verseLabel":"الإسراء: 48؛ الفرقان: 9","question":"ما دلالة تعريف ﴿الأمثال﴾ في قوله: ﴿ضربوا لك الأمثال﴾؟","answer":"يشير إلى الأوصاف والاتهامات المعروفة التي كرروها في حق الرسول، فيستحضر بطلانها وتناقضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص437، تحت «سر تعريف المفعول «الأمثال» بأل»","url":""}]},{"id":"s17-210","number":210,"surah":17,"verses":[48],"references":[{"surah":17,"verses":[48]},{"surah":25,"verses":[9]}],"verseLabel":"الإسراء: 48؛ الفرقان: 9","question":"ما دلالة تنكير ﴿سبيلًا﴾ في قوله: ﴿فلا يستطيعون سبيلًا﴾؟","answer":"يعمم نفي كل طريق يبلغون به إلى حجة مستقيمة أو غرض صحيح، بعد أن أضلّتهم أمثالهم الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص522، تحت «غرض تنكير سبيلًا»","url":""}]},{"id":"s17-114","number":114,"surah":17,"verses":[49],"references":[{"surah":17,"verses":[49]}],"verseLabel":"الإسراء: 49","question":"ما دلالة الجمع بين ﴿عِظَامًا وَرُفَاتًا﴾ في اعتراض منكري البعث؟","answer":"جمعوا ذكر العظام وما يتفتت ويبلى من بقايا الجسد، ليؤكدوا ما يرونه من فناء الأجسام ويتخذوه ذريعة لاستبعاد البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص445، تحت «دلالة العطف في لفظ «ورفاتًا»»","url":""}]},{"id":"s17-115","number":115,"surah":17,"verses":[50],"references":[{"surah":17,"verses":[50]}],"verseLabel":"الإسراء: 50","question":"ما دلالة الرد على منكري البعث بقوله تعالى: ﴿كُونُوا حِجَارَةً أَوْ حَدِيدًا﴾؟","answer":"حتى لو تحولوا في وهمهم إلى أصلب ما يعرفون، فلن يعجز الخالق عن إعادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص455، 456، 457، تحت «بلاغة التعبير بالأمر «كونوا» رغم عجزهم؛ نكتة تنكير الحجارة والحديد»","url":""}]},{"id":"s17-116","number":116,"surah":17,"verses":[51],"references":[{"surah":17,"verses":[51]}],"verseLabel":"الإسراء: 51","question":"ما سرّ التعبير بقوله تعالى: ﴿أَوْ خَلْقًا مِمَّا يَكْبُرُ فِي صُدُورِكُمْ﴾؟","answer":"عمم إلى أي خلق يرونه أشد امتناعًا، فيقطع كل مهرب يتخيله المنكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص459، 460، 461، تحت «نكتة تنكير «خلقًا»؛ نكتة التعبير بالاسم الموصول «ما»؛ نكتة إيثار الصدور على القلوب»","url":""}]},{"id":"s17-117","number":117,"surah":17,"verses":[52],"references":[{"surah":17,"verses":[52]}],"verseLabel":"الإسراء: 52","question":"ما دلالة تصوير البعث بقوله تعالى: ﴿يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِ﴾؟","answer":"صوّر البعث دعوةً من الله تعقبها استجابة لا يملكون التخلف عنها؛ و﴿بحمده﴾ تحتمل أنهم يبعثون حامدين، أو مستجيبين لأمره وطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص473، 474، 475، تحت «معنى «يدعوكم» بين الحقيقة والمجاز؛ معنى الفاء في قوله «فتستجيبون»؛ معاني الحمد في قوله «بحمده»»","url":""}]},{"id":"s17-118","number":118,"surah":17,"verses":[52],"references":[{"surah":17,"verses":[52]}],"verseLabel":"الإسراء: 52","question":"ما دلالة استقصارهم اللبث بقولهم إنه لم يكن ﴿إِلَّا قَلِيلًا﴾؟","answer":"يصور القصر استقصارهم زمن اللبث عند البعث؛ فمدة الحياة الدنيا تبدو قليلة في مقابلة الآخرة. ويذكر المصدر أن تقديرهم قد يكون خاطئًا يعقبه الندم على تفويت العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص476، 477، تحت «نكتة التعبير بـ«تظنون»؛ بلاغة القصر في «إن لبثتم إلا قليلًا»؛ نكتة تنكير «قليلًا»»","url":""}]},{"id":"s17-119","number":119,"surah":17,"verses":[53],"references":[{"surah":17,"verses":[53]}],"verseLabel":"الإسراء: 53","question":"ما سرّ التعبير بقوله تعالى: ﴿يَقُولُوا الَّتِي هِيَ أَحْسَنُ﴾ ولم يقل «قولًا حسنًا»؟","answer":"أمر باختيار الأحسن من البدائل، لأن كلمة صحيحة بعبارة خشنة قد تفتح باب النزاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص485، تحت «فائدة التعبير بصيغة التفضيل»","url":""}]},{"id":"s17-120","number":120,"surah":17,"verses":[53],"references":[{"surah":17,"verses":[53]}],"verseLabel":"الإسراء: 53","question":"ما سر تعليل الأمر بأحسن القول بأن ﴿الشَّيْطَانَ يَنْزَغُ بَيْنَهُمْ﴾؟","answer":"لأن الشيطان يستثمر الكلمة المحتملة ويحول الخلاف الصغير إلى عداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص485، 486، 487، تحت «نكتة فصل «إن الشيطان ينزغ بينهم»؛ نكتة التعبير بـ«ينزغ» مادة وصيغة؛ بلاغة الاستعارة في التعبير بالنزغ»","url":""}]},{"id":"s17-121","number":121,"surah":17,"verses":[54],"references":[{"surah":17,"verses":[54]}],"verseLabel":"الإسراء: 54","question":"ما سرّ التعبير بقوله تعالى: ﴿رَبُّكُمْ أَعْلَمُ بِكُمْ﴾ بعد الأمر بأحسن القول؟","answer":"ليمنع المؤمن من تزكية نفسه والحكم النهائي على غيره؛ فمصائر العباد إلى علم ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص494، تحت «نكتة فصل الآية عن سابقاتها»","url":""}]},{"id":"s17-122","number":122,"surah":17,"verses":[55],"references":[{"surah":17,"verses":[55]}],"verseLabel":"الإسراء: 55","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَقَدْ فَضَّلْنَا بَعْضَ النَّبِيِّينَ عَلَى بَعْضٍ﴾؟","answer":"ليرد اعتراضهم على اختيار محمد؛ فالتفضيل بين الرسل سنة ربانية لا حق للمقترحين فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص512، 513، 514، تحت «معنى الواو في «ولقد»؛ معنى «قد» ونكتة دخولها على «فضلنا»؛ علة تفضيل بعض الأنبياء دون تعيين»","url":""}]},{"id":"s17-123","number":123,"surah":17,"verses":[55],"references":[{"surah":17,"verses":[55]}],"verseLabel":"الإسراء: 55","question":"ما سر تخصيص داود بإيتاء الزبور في سياق تفضيل الأنبياء؟","answer":"من وجوه تخصيصه التنبيه إلى أن التفضيل بالوحي والعلم والدين، لا بالملك والمال؛ فذُكر كتابه مع ما كان له من ملك عظيم. وفيه أيضًا رد على من يحصر إنزال الكتب في موسى عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص516، تحت «سر النص على داود دون الأنبياء»","url":""}]},{"id":"s17-124","number":124,"surah":17,"verses":[56],"references":[{"surah":17,"verses":[56]}],"verseLabel":"الإسراء: 56","question":"ما سرّ التعبير بقوله تعالى: ﴿فَلَا يَمْلِكُونَ كَشْفَ الضُّرِّ عَنْكُمْ وَلَا تَحْوِيلًا﴾؟","answer":"نفى قدرتهم على إزالة الضر وعلى نقله إلى جهة أخرى، فاستوعب وجهي الخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص529، 530، تحت «معنى الواو في «ولا تحويلًا»؛ نكتة تنكير «تحويلًا»؛ علة تقديم كشف الضر على تحويله»","url":""}]},{"id":"s17-125","number":125,"surah":17,"verses":[57],"references":[{"surah":17,"verses":[57]}],"verseLabel":"الإسراء: 57","question":"ما دلالة وصف الذين يدعوهم المشركون بأنهم ﴿يَبْتَغُونَ إِلَى رَبِّهِمُ الْوَسِيلَةَ﴾؟","answer":"من يعبدونهم هم أنفسهم عباد يطلبون القرب من الله، فكيف يُجعل المحتاج إلهًا؟","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص535، تحت «غرض الاستهلال باسم الإشارة البعيد»","url":""}]},{"id":"s17-126","number":126,"surah":17,"verses":[58],"references":[{"surah":17,"verses":[58]}],"verseLabel":"الإسراء: 58","question":"ما سرّ التعبير بقوله تعالى: ﴿وَإِنْ مِنْ قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا﴾؟","answer":"الأسلوب يقرر حتمية ما توعد الله به القرى. ويذكر المصدر وجهين: عموم القرى، فيكون إهلاك الصالحة بالموت وفناء العمران، ومعاقبة الظالمة بالعذاب؛ أو تقدير وصف «الظالمة»، فيختص الوعيد بالقرى المكذبة، وهو الوجه الذي يرجحه المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص550، تحت «بلاغة القصر ونوعه»","url":""}]},{"id":"s17-127","number":127,"surah":17,"verses":[58],"references":[{"surah":17,"verses":[58]}],"verseLabel":"الإسراء: 58","question":"ما دلالة تنكير ﴿قَرْيَةٍ﴾ في قوله تعالى: ﴿وَإِنْ مِنْ قَرْيَةٍ﴾؟","answer":"التنكير في سياق النفي، مع «من» المؤكدة للاستغراق، يفيد شمول الحكم لأفراد الجنس المقصود. ويختلف نطاقه بحسب التفسير: جميع القرى، أو جميع القرى الظالمة على تقدير هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص548، 549، 550، تحت «معنى «من» في «من قرية»؛ نكتة تنكير «قرية»»","url":""}]},{"id":"s17-128","number":128,"surah":17,"verses":[59],"references":[{"surah":17,"verses":[59]}],"verseLabel":"الإسراء: 59","question":"ما سر وصف الناقة بأنها ﴿مُبْصِرَةً﴾؟","answer":"أي آية واضحة تُبصر الناس بالحق، أو ذات علامة ظاهرة لا تلتبس.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص570، 571، تحت «بلاغة استعارة لفظ «مبصرة» للناقة؛ بلاغة المجاز العقلي في إضافة الإبصار إلى الناقة»","url":""}]},{"id":"s17-129","number":129,"surah":17,"verses":[59],"references":[{"surah":17,"verses":[59]}],"verseLabel":"الإسراء: 59","question":"ما سرّ التعبير بقوله تعالى: ﴿وَمَا نُرْسِلُ بِالْآيَاتِ إِلَّا تَخْوِيفًا﴾؟","answer":"من توجيهاته أن الآيات المقترحة إنذار بما يعقب تكذيبها من العذاب، لا استجابة لمجرد التعنت. ويذكر المصدر أيضًا معنى حمل الناس على الاعتبار والتصديق خوفًا من عقوبة التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص574، تحت «نكتة ذكر التخويف في مقام إرسال الآيات»","url":""}]},{"id":"s17-130","number":130,"surah":17,"verses":[60],"references":[{"surah":17,"verses":[60]}],"verseLabel":"الإسراء: 60","question":"ما دلالة وصف الرؤيا بأنها ﴿فتنة للناس﴾؟","answer":"لأن الخبر الخارق يكشف المصدق من المكابر، فصار امتحانًا يميز مواقف الناس من الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص588، تحت «سر التعبير بقوله «فتنة»»","url":""}]},{"id":"s17-211","number":211,"surah":17,"verses":[60],"references":[{"surah":17,"verses":[60]}],"verseLabel":"الإسراء: 60","question":"لماذا أُسندت الفتنة إلى الشجرة الملعونة؟","answer":"لأن خبرها الغيبي صار سببًا لامتحان الناس؛ فصدّقه المؤمن وسخر منه المكابر، فنُسبت الفتنة إليها باعتبار أثر خبرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص590، تحت «دلالة إسناد الفتنة إلى الشجرة»","url":""}]},{"id":"s17-131","number":131,"surah":17,"verses":[61],"references":[{"surah":17,"verses":[61]}],"verseLabel":"الإسراء: 61","question":"ما دلالة قول إبليس: ﴿أَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا﴾؟","answer":"الاستفهام إنكار واستكبار، وذكر الطين يبرز العلة التي توهمها إبليس للامتناع: احتقار أصل آدم المادي. ومن التوجيهات إعراب «طينًا» حالًا، أي خلقته من هذا الجنس؛ فليس المقصود تقرير صحة قياس إبليس.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص606، 607، تحت «دلالة الاستفهام الإنكاري في قوله «أأسجد»؛ دلالة التقييد بالحال «طينًا»؛ سر التعبير بقوله «طينًا»»","url":""}]},{"id":"s17-132","number":132,"surah":17,"verses":[62],"references":[{"surah":17,"verses":[62]}],"verseLabel":"الإسراء: 62","question":"ما دلالة قول إبليس: ﴿لَأَحْتَنِكَنَّ ذُرِّيَّتَهُ﴾؟","answer":"الاحتناك أخذ الدابة بحنكها وقيادها؛ فصوّر طمعه في الاستيلاء على أكثر البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص619، 620، 621، تحت «براعة الاستعارة في قوله «لأحتنكن»؛ سر التعبير بقوله «لأحتنكن»»","url":""}]},{"id":"s17-133","number":133,"surah":17,"verses":[63],"references":[{"surah":17,"verses":[63]}],"verseLabel":"الإسراء: 63","question":"ما دلالة الرد على إبليس بقوله تعالى: ﴿اذْهَبْ﴾؟","answer":"أمر إهانة وتهديد: امض في اختيارك، وسترى أنت وأتباعك الجزاء الموفور.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص627، 628، تحت «دلالة فعل الأمر «اذهب» بين المجاز والحقيقة»","url":""}]},{"id":"s17-134","number":134,"surah":17,"verses":[64],"references":[{"surah":17,"verses":[64]}],"verseLabel":"الإسراء: 64","question":"ما سرّ التعبير بقوله تعالى: ﴿وَاسْتَفْزِزْ مَنِ اسْتَطَعْتَ مِنْهُمْ بِصَوْتِكَ﴾؟","answer":"الاستفزاز استخفاف يزعج الإنسان من موضعه، والصوت يشمل كل دعوة تثيره إلى المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص637، 638، 639، تحت «إيثار لفظ «استفزز» دون غيره؛ بلاغة المجاز في تخصيص الاستفزاز بصوت إبليس؛ بلاغة المجاز المرسل في التعبير بالصوت عن النداء»","url":""}]},{"id":"s17-135","number":135,"surah":17,"verses":[64],"references":[{"surah":17,"verses":[64]}],"verseLabel":"الإسراء: 64","question":"ما سرّ التعبير بقوله تعالى: ﴿وَأَجْلِبْ عَلَيْهِمْ بِخَيْلِكَ وَرَجِلِكَ﴾؟","answer":"يصور جمع أعوان الإغواء ووسائله بصورة جيش يحشد فرسانه ومشاته؛ فيستحضر كثرة المداخل التي يهاجم بها الشيطان الإنسان وتكاملها في إضلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص644، تحت «بلاغة الاستعارة في تمثيل صراع إبليس مع البشر»","url":""}]},{"id":"s17-136","number":136,"surah":17,"verses":[64],"references":[{"surah":17,"verses":[64]}],"verseLabel":"الإسراء: 64","question":"ما سر وصف وعد الشيطان بأنه ﴿غُرُورًا﴾؟","answer":"لأنه يزين منفعة عاجلة ويخفي خسارتها، فحقيقته خداع لا وعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص650، تحت «علة إيثار لفظ «غرورًا»»","url":""}]},{"id":"s17-137","number":137,"surah":17,"verses":[65],"references":[{"surah":17,"verses":[65]}],"verseLabel":"الإسراء: 65","question":"ما سرّ التعبير بقوله تعالى: ﴿لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ﴾؟","answer":"يطَمئن عباد الله أن الشيطان يوسوس ولا يملك إجبار القلب الذي احتمى بربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص656، تحت «فائدة نفي سلطان إبليس على عباد الله المؤمنين»","url":""}]},{"id":"s17-138","number":138,"surah":17,"verses":[66],"references":[{"surah":17,"verses":[66]}],"verseLabel":"الإسراء: 66","question":"ما سرّ التعبير بقوله تعالى: ﴿يُزْجِي لَكُمُ الْفُلْكَ﴾؟","answer":"الإزجاء سوق الشيء برفق؛ يصور السفن الضخمة منقادة بتدبير الله فوق البحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص665، تحت «سر انتخاب لفظ الإزجاء دون غيره»","url":""}]},{"id":"s17-139","number":139,"surah":17,"verses":[67],"references":[{"surah":17,"verses":[67]}],"verseLabel":"الإسراء: 67","question":"ما سرّ التعبير بقوله تعالى: ﴿ضَلَّ مَنْ تَدْعُونَ إِلَّا إِيَّاهُ﴾ عند ضر البحر؟","answer":"غاب عن وعيهم كل معبود وبقي الله وحده؛ فالشدّة تكشف التوحيد الكامن تحت الوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص677، 678، تحت «دلالة الفعل الماضي «ضل»؛ بلاغة حذف متعلق الفعل «ضل»؛ بلاغة الاستثناء في الآية»","url":""}]},{"id":"s17-140","number":140,"surah":17,"verses":[67],"references":[{"surah":17,"verses":[67]}],"verseLabel":"الإسراء: 67","question":"ما دلالة التعبير بالماضي في قوله: ﴿وكان الإنسان كفورًا﴾؟","answer":"يشير إلى رسوخ هذا الخلق وتكرره في تاريخ الإنسان، لا إلى موقف طارئ بعد نجاة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص683، تحت «بلاغة التعبير بفعل الكون ماضيًا»","url":""}]},{"id":"s17-212","number":212,"surah":17,"verses":[67],"references":[{"surah":17,"verses":[67]}],"verseLabel":"الإسراء: 67","question":"ما دلالة صيغة المبالغة ﴿كفورًا﴾؟","answer":"تصوّر كثرة كفران الإنسان للنعم وشدة عودته إلى الإعراض بعد النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص684، تحت «بلاغة صيغة المبالغة في «كفورًا»»","url":""}]},{"id":"s17-141","number":141,"surah":17,"verses":[68],"references":[{"surah":17,"verses":[68]}],"verseLabel":"الإسراء: 68","question":"ما سر التخويف بالخسف في البر بعد النجاة من البحر؟","answer":"ليبيّن أن الأمان ليس في المكان؛ من نجاهم في البحر قادر أن يأخذهم في اليابسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص691، 692، 695، تحت «بلاغة الاستفهام في «أفأمنتم»؛ بلاغة الكناية في الآية»","url":""}]},{"id":"s17-142","number":142,"surah":17,"verses":[69],"references":[{"surah":17,"verses":[69]}],"verseLabel":"الإسراء: 69","question":"ما سرّ التعبير بقوله تعالى: ﴿قَاصِفًا مِنَ الرِّيحِ﴾؟","answer":"القاصف ريح شديدة تكسر ما تمر به، فتلائم مشهد السفن المحطمة والغرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص707، 708، 716، تحت «دلالة وصف الريح بـ«قاصفًا» بالتذكير؛ القاصف والعاصف»","url":""}]},{"id":"s17-143","number":143,"surah":17,"verses":[70],"references":[{"surah":17,"verses":[70]}],"verseLabel":"الإسراء: 70","question":"ما معنى تكريم بني آدم في قوله: ﴿ولقد كرمنا بني آدم﴾؟","answer":"هو تفضيل عام بما وهبهم الله من العقل والنطق وحسن الصورة والتسخير، فيشمل أصل النوع الإنساني.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص721، تحت «معنى التكريم في الآية»","url":""}]},{"id":"s17-213","number":213,"surah":17,"verses":[70],"references":[{"surah":17,"verses":[70]}],"verseLabel":"الإسراء: 70","question":"ما دلالة حذف وجوه التكريم في قوله: ﴿ولقد كرمنا بني آدم﴾؟","answer":"يفتح الحذف المعنى لتعدد صور التكريم وكثرتها، فلا يحصرها في نعمة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص722، تحت «دلالة حذف أوجه التكريم»","url":""}]},{"id":"s17-144","number":144,"surah":17,"verses":[70],"references":[{"surah":17,"verses":[70]}],"verseLabel":"الإسراء: 70","question":"ما دلالة الجمع بين الحمل في البر والبحر؟","answer":"لاستيعاب وجهي التنقل المعروفين وإظهار تسخير البيئتين المتباينتين للإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص723، 724، تحت «دلالة الواو «وحملناهم»؛ دلالة إسناد «وحملناهم» إلى نا؛ معنى حرف الجر «في»»","url":""}]},{"id":"s17-145","number":145,"surah":17,"verses":[71],"references":[{"surah":17,"verses":[71]}],"verseLabel":"الإسراء: 71","question":"ما سرّ التعبير بقوله تعالى: ﴿نَدْعُو كُلَّ أُنَاسٍ بِإِمَامِهِمْ﴾؟","answer":"الإمام ما يُؤتم به، وفيه توجيهات منها نبي الأمة أو كتابها أو من اقتدت به في الخير والشر، وقيل كتاب الأعمال. وإضافته إليهم تربط كل جماعة بما انتسبت إليه أو بما يشهد عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص735، تحت «فائدة الإضافة في «بإمامهم»»","url":""}]},{"id":"s17-146","number":146,"surah":17,"verses":[71],"references":[{"surah":17,"verses":[71]}],"verseLabel":"الإسراء: 71","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا يُظْلَمُونَ فَتِيلًا﴾؟","answer":"الفتيل خيط دقيق في شق النواة؛ اختير لتصوير انتفاء أدنى قدر من الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص740، 741، تحت «دلالة الإفراد في «فتيلًا»؛ بلاغة نيابة «فتيلًا» عن المفعول المطلق؛ بلاغة الكناية في «ولا يظلمون فتيلًا»»","url":""}]},{"id":"s17-147","number":147,"surah":17,"verses":[72],"references":[{"surah":17,"verses":[72]}],"verseLabel":"الإسراء: 72","question":"ما دلالة ربط عمى الآخرة بعمى الدنيا؟","answer":"يربط الشرط بين الإعراض عن دلائل الهدى في الدنيا وعاقبته في الآخرة. ومن توجيهات العمى الثاني عمى البصيرة، فيكون المعرض هناك أشد حيرة وأبعد عن طريق النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص748، 750، 751، تحت «فائدة اسم الشرط «من»؛ معنى الفاء في «فهو» ودلالتها؛ دلالة الاختلاف في «أعمى» الثانية»","url":""}]},{"id":"s17-148","number":148,"surah":17,"verses":[73],"references":[{"surah":17,"verses":[73]}],"verseLabel":"الإسراء: 73","question":"ما سرّ التعبير بقوله تعالى: ﴿لَيَفْتِنُونَكَ عَنِ الَّذِي أَوْحَيْنَا إِلَيْكَ﴾؟","answer":"عُدّي فعل الفتنة بـ«عن» لتضمينه معنى الصرف؛ فجمع التعبير بين محاولة اختباره وفتنته ومحاولة إبعاده عن الوحي. والموصول يستحضر أن الذي يريدون صرفه عنه وحي من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص762، 763، 768، تحت «أثر تعدية الفعل بحرف الجر «عن»؛ سر التعبير بالاسم الموصول؛ الفتن والصرف»","url":""}]},{"id":"s17-149","number":149,"surah":17,"verses":[74],"references":[{"surah":17,"verses":[74]}],"verseLabel":"الإسراء: 74","question":"ما دلالة ﴿لولا﴾ في قوله: ﴿ولولا أن ثبتناك﴾؟","answer":"تفيد أن الركون امتنع بسبب تثبيت الله، فتقرر عصمته وعناية الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص771، تحت «معنى لولا وبلاغة أسلوب الشرط»","url":""}]},{"id":"s17-214","number":214,"surah":17,"verses":[74],"references":[{"surah":17,"verses":[74]}],"verseLabel":"الإسراء: 74","question":"ما دلالة إسناد التثبيت إلى ضمير العظمة في قوله: ﴿ثبتناك﴾؟","answer":"يظهر أن الثبات فضل من الله وقوة عنايته برسوله، لا اعتمادًا على قدرة بشرية مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص772، تحت «بلاغة إسناد الفعل إلى ضمير العظمة»","url":""}]},{"id":"s17-150","number":150,"surah":17,"verses":[75],"references":[{"surah":17,"verses":[75]}],"verseLabel":"الإسراء: 75","question":"ما دلالة مضاعفة العذاب على فرض الركون في قوله تعالى: ﴿ضِعْفَ الْحَيَاةِ وَضِعْفَ الْمَمَاتِ﴾؟","answer":"هذا وعيد على فرض الركون، مع أن الآية السابقة أثبتت التثبيت والعصمة منه. ومضاعفة الجزاء تناسب عظم المنزلة والمسؤولية وما قد يترتب على الاقتداء بصاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص779، 780، 781، 782، تحت «دلالة حذف الموصوف في الآية»","url":""}]},{"id":"s17-151","number":151,"surah":17,"verses":[76],"references":[{"surah":17,"verses":[76]}],"verseLabel":"الإسراء: 76","question":"ما سرّ التعبير بقوله تعالى: ﴿لَيَسْتَفِزُّونَكَ مِنَ الْأَرْضِ﴾؟","answer":"الاستفزاز إزعاج بعنف وخفة، فيصور محاولتهم اقتلاعه من وطنه لا مجرد إخراجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص791، تحت «علة إيثار فعل الإخراج»","url":""}]},{"id":"s17-152","number":152,"surah":17,"verses":[77],"references":[{"surah":17,"verses":[77]}],"verseLabel":"الإسراء: 77","question":"ما سرّ التعبير بقوله تعالى: ﴿سُنَّةَ مَنْ قَدْ أَرْسَلْنَا قَبْلَكَ﴾؟","answer":"يثبت أن إخراج الرسل يعقبه هلاك المكذبين، وأن ما يواجهه ليس حادثًا بلا نظير.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص799، تحت «دلالة التعبير بالمصدر المؤكد «سنة»»","url":""}]},{"id":"s17-153","number":153,"surah":17,"verses":[78],"references":[{"surah":17,"verses":[78]}],"verseLabel":"الإسراء: 78","question":"ما دلالة ربط إقامة الصلاة بـ﴿دُلُوكِ الشَّمْسِ﴾؟","answer":"الدلوك ميل الشمس، ومن تفسيراته زوالها عن وسط السماء ومن تفسيراته غروبها. وربط إقامة الصلاة بهذه العلامة المشهودة يحدد وقتها، ثم يمتد البيان إلى غسق الليل ويخص الفجر بالذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص14، تحت «دلالة إضافة الدلوك إلى الشمس»","url":""}]},{"id":"s17-154","number":154,"surah":17,"verses":[78],"references":[{"surah":17,"verses":[78]}],"verseLabel":"الإسراء: 78","question":"ما سر تسمية صلاة الفجر ﴿قُرْآنَ الْفَجْرِ﴾؟","answer":"سميت الصلاة بجزء منها، وهو القراءة، تنويهًا بشأنها فيها؛ إذ تطول قراءة الفجر ويُجهر بها، فيظهر هذا الركن ويشهده المصلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص16، تحت «بلاغة المجاز المرسل في «وقرآن الفجر»»","url":""}]},{"id":"s17-155","number":155,"surah":17,"verses":[78],"references":[{"surah":17,"verses":[78]}],"verseLabel":"الإسراء: 78","question":"ما دلالة وصف قرآن الفجر بأنه ﴿مَشْهُودًا﴾؟","answer":"من معاني كونه مشهودًا اجتماع ملائكة الليل وملائكة النهار لشهوده؛ وفي وصفه بذلك تنويه بفضله وحث على العناية به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص18، تحت «بلاغة الكناية في لفظ مشهودًا»","url":""}]},{"id":"s17-156","number":156,"surah":17,"verses":[79],"references":[{"surah":17,"verses":[79]}],"verseLabel":"الإسراء: 79","question":"ما سر إيثار لفظ ﴿نافلة﴾ في قيام الليل؟","answer":"النافلة زيادة، فالتعبير ينوه بما خُص به النبي من زيادة في وظيفة العبادة والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص23، تحت «إيثار لفظ نافلة دون تهجدًا»","url":""}]},{"id":"s17-215","number":215,"surah":17,"verses":[79],"references":[{"surah":17,"verses":[79]}],"verseLabel":"الإسراء: 79","question":"ما سر إيثار البعث في قوله: ﴿عسى أن يبعثك ربك مقامًا محمودًا﴾؟","answer":"يناسب المقام المحمود الذي يظهر يوم القيامة؛ فالبعث انتقال إلى المقام الذي يحمده فيه الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص24، تحت «إيثار لفظ البعث دون غيره»","url":""}]},{"id":"s17-157","number":157,"surah":17,"verses":[80],"references":[{"surah":17,"verses":[80]}],"verseLabel":"الإسراء: 80","question":"ما دلالة إضافة المدخل والمخرج إلى الصدق؟","answer":"تجعل الصدق ملازمًا لبدايات الانتقال ونهاياته، فلا يكون دخول ولا خروج إلا بحق وعاقبة محمودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص34، تحت «فائدة إضافة المدخل والمخرج إلى الصدق»","url":""}]},{"id":"s17-216","number":216,"surah":17,"verses":[80],"references":[{"surah":17,"verses":[80]}],"verseLabel":"الإسراء: 80","question":"ما سر تقديم ﴿مدخل صدق﴾ على ﴿مخرج صدق﴾؟","answer":"يرتب الدعاء على ما يستقبل من الدخول ثم ما يعقبه من الخروج، ويطلب صلاح الحال في الوجهتين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص35، تحت «سر تقديم الإدخال على الإخراج»","url":""}]},{"id":"s17-158","number":158,"surah":17,"verses":[80],"references":[{"surah":17,"verses":[80]}],"verseLabel":"الإسراء: 80","question":"ما دلالة تنكير ﴿سلطانًا﴾ في الدعاء؟","answer":"يفيد طلب سلطان عظيم كافٍ لما يواجهه الرسول، من حجة أو قدرة يؤيد الله بها الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص36، تحت «إيثار لفظ سلطانًا منكّرًا»","url":""}]},{"id":"s17-217","number":217,"surah":17,"verses":[80],"references":[{"surah":17,"verses":[80]}],"verseLabel":"الإسراء: 80","question":"ما سر وصف السلطان بأنه ﴿نصيرًا﴾؟","answer":"يبين أن الغرض منه نصرة الحق وإظهار الدين، لا مجرد العلو والتمكن.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص36، تحت «سر وصف السلطان بالنصير»","url":""}]},{"id":"s17-159","number":159,"surah":17,"verses":[81],"references":[{"surah":17,"verses":[81]}],"verseLabel":"الإسراء: 81","question":"ما سر التعبير بـ﴿زهق الباطل﴾ في مقابل ﴿جاء الحق﴾؟","answer":"يقابل ظهور الحق وثباته بذهاب الباطل واضمحلاله، ويصوّر زواله كزهوق الروح.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص40، تحت «سر التعبير بالفعل زهق مقابلًا للفعل جاء»","url":""}]},{"id":"s17-218","number":218,"surah":17,"verses":[81],"references":[{"surah":17,"verses":[81]}],"verseLabel":"الإسراء: 81","question":"ما دلالة التذييل: ﴿إن الباطل كان زهوقًا﴾؟","answer":"يقرر أن الزوال طبيعة الباطل مهما طال ظهوره، فيحوّل المشهد الخاص إلى قاعدة عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص43، تحت «فن التذييل»","url":""}]},{"id":"s17-160","number":160,"surah":17,"verses":[82],"references":[{"surah":17,"verses":[82]}],"verseLabel":"الإسراء: 82","question":"ما دلالة وصف القرآن بأنه ﴿شفاء﴾؟","answer":"يزيل عن المؤمنين أمراض الشبهات وضلال العقائد وفساد الأعمال والأخلاق، فشبّه أثره في القلوب بأثر الدواء في الأبدان.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص49، تحت «بلاغة المجاز في لفظ شفاء»","url":""}]},{"id":"s17-219","number":219,"surah":17,"verses":[82],"references":[{"surah":17,"verses":[82]}],"verseLabel":"الإسراء: 82","question":"كيف أُسندت زيادة الخسار إلى القرآن مع أنه هداية؟","answer":"نُسبت الزيادة إليه لأنه سبب ظهور عناد الظالمين عند سماعه، أما منشأ الخسار الحقيقي فهو إعراضهم وكفرهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص52، تحت «بلاغة المجاز العقلي في إسناد الزيادة إلى القرآن»","url":""}]},{"id":"s17-161","number":161,"surah":17,"verses":[83],"references":[{"surah":17,"verses":[83]}],"verseLabel":"الإسراء: 83","question":"ما سرّ التعبير بقوله تعالى: ﴿نَأَى بِجَانِبِهِ﴾ لا «ابتعد»؟","answer":"يصوّر الإعراض بحركة الجنب المتكبر، كأنه يصرف نفسه كلها عن المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص61، تحت «إيثار التعبير بنأي الجانب»","url":""}]},{"id":"s17-162","number":162,"surah":17,"verses":[83],"references":[{"surah":17,"verses":[83]}],"verseLabel":"الإسراء: 83","question":"ما دلالة التعبير بـ﴿يَئُوسًا﴾ عند مس الشر؟","answer":"صيغة «يئوس» تبالغ في وصف القنوط؛ ويقابل السياق يأسه عند مس الشر بإعراضه عند النعمة، فيكشف اختلال موقفه في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص65، تحت «نكتة إيثار المصدر يئوسًا وتنكيره»","url":""}]},{"id":"s17-163","number":163,"surah":17,"verses":[84],"references":[{"surah":17,"verses":[84]}],"verseLabel":"الإسراء: 84","question":"ما سرّ التعبير بقوله تعالى: ﴿كُلٌّ يَعْمَلُ عَلَى شَاكِلَتِهِ﴾؟","answer":"الشاكلة الهيئة والطبع والطريقة؛ فالعمل يخرج كاشفًا للبنية الداخلية لصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص70، 71، 74، تحت «بلاغة المجاز في «شاكلته»؛ الشاكلة والمثل والنظير»","url":""}]},{"id":"s17-164","number":164,"surah":17,"verses":[85],"references":[{"surah":17,"verses":[85]}],"verseLabel":"الإسراء: 85","question":"ما دلالة الجواب عن الروح بأنها ﴿من أمر ربي﴾؟","answer":"يرد السائلين من طلب الإحاطة بسر الروح إلى أصل كافٍ: هي من شأن الله وتكوينه الذي لا يحيطون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص81، تحت «معنى من وسر تخصيص الأمر بالذكر»","url":""}]},{"id":"s17-220","number":220,"surah":17,"verses":[85],"references":[{"surah":17,"verses":[85]}],"verseLabel":"الإسراء: 85","question":"ما دلالة إيثار وصف الربوبية في قوله: ﴿من أمر ربي﴾؟","answer":"يستحضر تدبير الله وتربيته وخلقه، ويصل أمر الروح مباشرة بسلطان الرب الذي انفرد بسرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص82، تحت «إيثار الربوبية دون غيرها»","url":""}]},{"id":"s17-165","number":165,"surah":17,"verses":[85],"references":[{"surah":17,"verses":[85]}],"verseLabel":"الإسراء: 85","question":"ما دلالة تعريف ﴿العلم﴾ في قوله: ﴿وما أوتيتم من العلم إلا قليلًا﴾؟","answer":"يستغرق جنس العلم المتاح للبشر، فيبين أن مجموعه محدود أمام علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص83، تحت «دلالة تعريف العلم»","url":""}]},{"id":"s17-221","number":221,"surah":17,"verses":[85],"references":[{"surah":17,"verses":[85]}],"verseLabel":"الإسراء: 85","question":"ما دلالة تنكير ﴿قليلًا﴾ في قوله: ﴿إلا قليلًا﴾؟","answer":"يزيد في تصوير ضآلة ما أوتيه البشر من العلم، فلا يحيطون بكل أسرار الخلق ومنها الروح.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص84، تحت «وجه تنكير قليلًا»","url":""}]},{"id":"s17-166","number":166,"surah":17,"verses":[86],"references":[{"surah":17,"verses":[86]}],"verseLabel":"الإسراء: 86","question":"ما سرّ التعبير بقوله تعالى: ﴿لَنَذْهَبَنَّ بِالَّذِي أَوْحَيْنَا إِلَيْكَ﴾؟","answer":"ذكّر أن بقاء القرآن فضل متجدد؛ فالذي أنزله قادر على رفعه ولا يستبقيه أحد سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص90، تحت «وجه تعدية الفعل بالباء في لنذهبن بالذي»","url":""}]},{"id":"s17-167","number":167,"surah":17,"verses":[87],"references":[{"surah":17,"verses":[87]}],"verseLabel":"الإسراء: 87","question":"ما دلالة الاستثناء في قوله تعالى: ﴿إِلَّا رَحْمَةً مِنْ رَبِّكَ﴾؟","answer":"من توجيه الاستثناء: لكن رحمة من ربك أبقت الوحي ولم تذهب به. فبعد بيان القدرة على رفعه، يذكّر التعبير بفضل الله ورحمته في إنزاله وإبقائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص95، تحت «دلالة الاستثناء بين الانقطاع والاتصال»","url":""}]},{"id":"s17-168","number":168,"surah":17,"verses":[88],"references":[{"surah":17,"verses":[88]}],"verseLabel":"الإسراء: 88","question":"ما دلالة الجمع بين الإنس والجن في تحدي الإتيان بمثل القرآن؟","answer":"ليستوعب جميع العقلاء القادرين على البيان، ثم ينفي قدرتهم ولو تعاونوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص103، تحت «فائدة اجتماع الثقلين في السياق المحكم»","url":""}]},{"id":"s17-169","number":169,"surah":17,"verses":[88],"references":[{"surah":17,"verses":[88]}],"verseLabel":"الإسراء: 88","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا﴾؟","answer":"حتى لا ينسب عجزهم إلى التفرق؛ فالمساندة القصوى لا تنتج مثل القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص108، تحت «سر التعبير بأداة لو»","url":""}]},{"id":"s17-170","number":170,"surah":17,"verses":[89],"references":[{"surah":17,"verses":[89]}],"verseLabel":"الإسراء: 89","question":"ما سرّ التعبير بقوله تعالى: ﴿صَرَّفْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِنْ كُلِّ مَثَلٍ﴾؟","answer":"نوّع البيان ووجّهه للناس ليقطع عذر من يطلب صورة أخرى للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص115، تحت «بلاغة الكناية في جملة صرفنا»","url":""}]},{"id":"s17-171","number":171,"surah":17,"verses":[90,91,92,93],"references":[{"surah":17,"verses":[90,91,92,93]}],"verseLabel":"الإسراء: 90-93","question":"ما دلالة قول المشركين: ﴿لن نؤمن لك﴾؟","answer":"تفيد ﴿لن﴾ إصرارهم على نفي الإيمان في المستقبل، فتفضح أن مطالبهم تعنت لا طلب برهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص124، تحت «سر إيثار النفي بلن في السياق»","url":""}]},{"id":"s17-222","number":222,"surah":17,"verses":[90,91,92,93],"references":[{"surah":17,"verses":[90,91,92,93]}],"verseLabel":"الإسراء: 90-93","question":"ما دلالة تقييد الكتاب بقولهم: ﴿كتابًا نقرؤه﴾؟","answer":"اشترطوا كتابًا ماديًا ينزل عليهم ويباشرون قراءته، فزادوا في التحكم بعد قيام آية القرآن القائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص147، تحت «سر تقييد الكتاب بالصفة نقرؤه»","url":""}]},{"id":"s17-172","number":172,"surah":17,"verses":[93],"references":[{"surah":17,"verses":[93]}],"verseLabel":"الإسراء: 93","question":"ما دلالة القصر في قوله: ﴿هل كنت إلا بشرًا رسولًا﴾؟","answer":"يقصر شأنه على البشرية والرسالة: فهو مبلغ عن الله لا مالك لخزائن القدرة ولا منفذ لأهوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص150، تحت «بلاغة التعبير بأسلوب القصر»","url":""}]},{"id":"s17-223","number":223,"surah":17,"verses":[93],"references":[{"surah":17,"verses":[93]}],"verseLabel":"الإسراء: 93","question":"ما دلالة الجمع بين ﴿بشرًا﴾ و﴿رسولًا﴾؟","answer":"يقرر أن البشرية لا تنافي الرسالة، لكنها تحدد وظيفة الرسول بالبلاغ ولا تجعله قادرًا على الخوارق باختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص150، تحت «وجه الجمع بين اللفظين بشرًا رسولًا»","url":""}]},{"id":"s17-173","number":173,"surah":17,"verses":[94],"references":[{"surah":17,"verses":[94]}],"verseLabel":"الإسراء: 94","question":"ما دلالة اعتراضهم بقولهم: ﴿أَبَعَثَ اللَّهُ بَشَرًا رَسُولًا﴾؟","answer":"يصور الاستفهام استنكارهم اجتماع البشرية والرسالة، وهو اعتقاد حجبهم عن الإيمان. وترد الآية التالية بأن مجانسة الرسول لمن أرسل إليهم تحقق الألفة وإمكان التلقي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص157، تحت «الغرض من الاستفهام بالهمزة»","url":""}]},{"id":"s17-174","number":174,"surah":17,"verses":[95],"references":[{"surah":17,"verses":[95]}],"verseLabel":"الإسراء: 95","question":"ما دلالة افتراض ملائكة يمشون في الأرض في بيان حكمة بشرية الرسول؟","answer":"يفترض التعبير ملائكة مستقرين في الأرض، فيناسبهم رسول من جنسهم كما يناسب البشرَ رسول بشري؛ فالمجانسة تحقق الألفة والتفاهم والتلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص163، تحت «سر التقييد بالوصف بجملة يمشون»","url":""}]},{"id":"s17-175","number":175,"surah":17,"verses":[96],"references":[{"surah":17,"verses":[96]}],"verseLabel":"الإسراء: 96","question":"ما دلالة وصف الله بأنه ﴿شهيد﴾ في قوله: ﴿كفى بالله شهيدًا بيني وبينكم﴾؟","answer":"يفيد كفاية علم الله وشهادته للرسول، وفيها تسلية له ووعيد للمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص168، تحت «بلاغة الكناية في لفظ الشهيد»","url":""}]},{"id":"s17-224","number":224,"surah":17,"verses":[96],"references":[{"surah":17,"verses":[96]}],"verseLabel":"الإسراء: 96","question":"ما دلالة الجمع بين ﴿خبيرًا بصيرًا﴾ في تعليل شهادة الله؟","answer":"يجمع إحاطته ببواطن أحوال العباد وظواهرها، فتقوم شهادته على علم كامل لا يخفى عليه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص172، تحت «سر التعبير بالاسمين خبيرًا بصيرًا في الفاصلة»","url":""}]},{"id":"s17-176","number":176,"surah":17,"verses":[97],"references":[{"surah":17,"verses":[97]}],"verseLabel":"الإسراء: 97","question":"ما دلالة حشر المكذبين ﴿عُمْيًا وَبُكْمًا وَصُمًّا﴾؟","answer":"جزاء مناسب لتعطيلهم وسائل الهداية في الدنيا، وحال تزيدهم ذلًا وحيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص191، تحت «العمى والبكم والصمم بين الحقيقة والاستعارة»","url":""}]},{"id":"s17-177","number":177,"surah":17,"verses":[97],"references":[{"surah":17,"verses":[97]}],"verseLabel":"الإسراء: 97","question":"ما دلالة ﴿كلما﴾ في قوله: ﴿كلما خبت زدناهم سعيرًا﴾؟","answer":"تربط كل خبو بتجدد السعير، فتثبت دوام العذاب وتقطع رجاء انتهائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص194، تحت «براعة استعمال لفظ كلما في إثبات دوام العذاب»","url":""}]},{"id":"s17-225","number":225,"surah":17,"verses":[97],"references":[{"surah":17,"verses":[97]}],"verseLabel":"الإسراء: 97","question":"لماذا أُوقعت زيادة السعير على أهل النار لا على النار؟","answer":"يوجه التعبير النظر إلى أثر الزيادة في المعذبين أنفسهم، فالمقصود ازدياد ما يلقونه من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص195، تحت «سر إيقاع الفعل على أهل النار لا على النار»","url":""}]},{"id":"s17-226","number":226,"surah":17,"verses":[97],"references":[{"surah":17,"verses":[97]}],"verseLabel":"الإسراء: 97","question":"ما الفرق الذي يصوره لفظ ﴿خبت﴾ في قوله: ﴿كلما خبت﴾؟","answer":"الخبو سكون اللهب وضعفه لا انطفاؤه التام؛ فإذا خف سعيرها جُدد عليهم أشد منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص196، تحت «خبت وانطفأت»","url":""}]},{"id":"s17-178","number":178,"surah":17,"verses":[99],"references":[{"surah":17,"verses":[99]}],"verseLabel":"الإسراء: 99","question":"ما دلالة الاستدلال بخلق السماوات والأرض على بعث البشر؟","answer":"من قدر على الأعظم ابتداءً لا يعجز عن إعادة الأصغر بعد موته.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص208، تحت «غرض الاستفهام في جملة أولم يروا»","url":""}]},{"id":"s17-179","number":179,"surah":17,"verses":[100],"references":[{"surah":17,"verses":[100]}],"verseLabel":"الإسراء: 100","question":"ما دلالة وصف الإنسان بأنه ﴿قَتُورًا﴾ بعد افتراض امتلاكه خزائن الرحمة؟","answer":"«قتورًا» يفيد المبالغة في التضييق والإمساك. ويبلغ التصوير غايته بافتراض امتلاك خزائن رحمة الله ثم الإمساك خوف النفاد؛ فتفضح المفارقة شدة الشح وسوء تصور سعة الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص232، تحت «القتر والبخل»","url":""}]},{"id":"s17-180","number":180,"surah":17,"verses":[101],"references":[{"surah":17,"verses":[101]}],"verseLabel":"الإسراء: 101","question":"ما دلالة إبهام آيات موسى ثم تخصيصها بالعدد ﴿تسع آيات﴾؟","answer":"يجمع العدد الآيات الكثيرة في لفظ موجز ويستحضر تمامها، مع ترك تفصيلها لما هو معروف من قصتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص237، تحت «غرض إبهام الآيات والتخصيص بالعدد تسع»","url":""}]},{"id":"s17-227","number":227,"surah":17,"verses":[101],"references":[{"surah":17,"verses":[101]}],"verseLabel":"الإسراء: 101","question":"ما دلالة وصف آيات موسى بأنها ﴿بينات﴾؟","answer":"يبرز وضوح دلالتها على صدق موسى، ويبين أن جحود فرعون لم يكن لنقص البرهان بل للعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص237، تحت «نكتة وصف الآيات بالبينات»","url":""}]},{"id":"s17-181","number":181,"surah":17,"verses":[102],"references":[{"surah":17,"verses":[102]}],"verseLabel":"الإسراء: 102","question":"ما دلالة وصف موسى لفرعون بأنه ﴿مَثْبُورًا﴾؟","answer":"المثبور الهالك المبعد عن الخير. قابل موسى اتهام فرعون له بأنه «مسحور» بوصف فرعون بأنه «مثبور»، تهديدًا بعاقبة عناده مع ظهور الآيات؛ فاجتمعت المقابلة في اللفظ والرد على باطل الاتهام.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص250، تحت «دلالة التعبير باسم المفعول مثبورًا»","url":""}]},{"id":"s17-182","number":182,"surah":17,"verses":[103],"references":[{"surah":17,"verses":[103]}],"verseLabel":"الإسراء: 103","question":"ما دلالة قول الله عن فرعون: ﴿فأراد أن يستفزهم من الأرض﴾؟","answer":"الاستفزاز إزعاج بعنف وخفة، فيصور محاولته اقتلاع بني إسرائيل من الأرض لا مجرد إخراج هادئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص253، تحت «نكتة استعمال لفظ يستفزهم»","url":""}]},{"id":"s17-228","number":228,"surah":17,"verses":[103],"references":[{"surah":17,"verses":[103]}],"verseLabel":"الإسراء: 103","question":"ما دلالة تعقيب إرادة فرعون بقوله: ﴿فأغرقناه ومن معه﴾؟","answer":"يقابل تدبيره لاقتلاع المؤمنين باقتلاعه هو وجنده، فارتد مكره عليه جزاءً من جنس قصده.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص255، تحت «براعة استعمال الفاء في الجزاء بالمقابلة»","url":""}]},{"id":"s17-183","number":183,"surah":17,"verses":[104],"references":[{"surah":17,"verses":[104]}],"verseLabel":"الإسراء: 104","question":"ما دلالة الأمر لبني إسرائيل: ﴿اسكنوا الأرض﴾ بعد هلاك فرعون؟","answer":"ينقلهم من الاستضعاف والتشريد إلى الاستقرار والتمكن، فيظهر تمام انقلاب الحال بعد النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص261، تحت «نكتة الأمر في الفعل اسكنوا»","url":""}]},{"id":"s17-229","number":229,"surah":17,"verses":[104],"references":[{"surah":17,"verses":[104]}],"verseLabel":"الإسراء: 104","question":"ما سر اختلاف الأمر بالسكن هنا عن الأمر بالدخول في موضع آخر؟","answer":"ناسب السكن مقام الاستقرار بعد زوال فرعون، أما الدخول فيتجه إلى ابتداء الانتقال إلى الأرض؛ فلكل تعبير سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص261، تحت «توجيه المتشابه اللفظي بين الأمر بالسكن والدخول»","url":""}]},{"id":"s17-230","number":230,"surah":17,"verses":[104],"references":[{"surah":17,"verses":[104]}],"verseLabel":"الإسراء: 104","question":"ما دلالة إطلاق ﴿وعد الآخرة﴾ بعد أمر بني إسرائيل بالسكن؟","answer":"يذكّر بأن استقرار الدنيا مؤقت، وأن الجمع النهائي والحساب يقعان عند مجيء وعد الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص263، تحت «فائدة الإطلاق في لفظ الآخرة»","url":""}]},{"id":"s17-184","number":184,"surah":17,"verses":[105],"references":[{"surah":17,"verses":[105]}],"verseLabel":"الإسراء: 105","question":"ما سر تكرار ﴿بِالْحَقِّ﴾ في قوله تعالى: ﴿وَبِالْحَقِّ أَنْزَلْنَاهُ وَبِالْحَقِّ نَزَلَ﴾؟","answer":"من وجوه التفريق أن الأول يقرر إنزاله بالحكمة والغاية الحق، والثاني يقرر اشتماله على الحق وسلامة وصوله من التغيير. ويذكر المصدر أيضًا وجه التأكيد؛ فتكرار اللفظ يثبت إحاطة الحق بإنزاله ونزوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص270، تحت «معنى بالحق وسر تكرار لفظه»","url":""}]},{"id":"s17-185","number":185,"surah":17,"verses":[106],"references":[{"surah":17,"verses":[106]}],"verseLabel":"الإسراء: 106","question":"ما دلالة قوله تعالى: ﴿لِتَقْرَأَهُ عَلَى النَّاسِ عَلَى مُكْثٍ﴾؟","answer":"يدل المكث على التمهل والتثبت، ويلائم نزول القرآن مفرقًا ومراعاة أحوال الناس، ليتيسر تلقيه وحفظه وفهمه والعمل به مع تجدد الوقائع.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص290، تحت «إيثار استعمال لفظ مكث»","url":""}]},{"id":"s17-186","number":186,"surah":17,"verses":[107],"references":[{"surah":17,"verses":[107]}],"verseLabel":"الإسراء: 107","question":"ما سرّ التعبير بقوله تعالى: ﴿آمِنُوا بِهِ أَوْ لَا تُؤْمِنُوا﴾؟","answer":"الأمر هنا يفيد التهديد والتوبيخ، وفيه تسوية من جهة أن إيمانهم أو إعراضهم لا يغير حقيقة القرآن ولا يضر إلا المعرض نفسه. ثم يستشهد السياق بخشوع أهل العلم تعريضًا بجهل المكذبين وتسلية للنبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص299، تحت «بلاغة الأمر في قوله آمنوا به أو لا تؤمنوا»","url":""}]},{"id":"s17-187","number":187,"surah":17,"verses":[107],"references":[{"surah":17,"verses":[107]}],"verseLabel":"الإسراء: 107","question":"ما سر إيثار ﴿يخرون﴾ بدل يسجدون في وصف أهل العلم؟","answer":"يصور سرعة سقوطهم للسجود وشدة استجابتهم للقرآن، كأن الخشوع يسوقهم إلى الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص305، تحت «إيثار استخدام لفظ يخرون بدل يسجدون ويسقطون»","url":""}]},{"id":"s17-231","number":231,"surah":17,"verses":[107],"references":[{"surah":17,"verses":[107]}],"verseLabel":"الإسراء: 107","question":"ما سر إيثار ﴿الأذقان﴾ بدل الوجوه في تصوير سجودهم؟","answer":"يبالغ في تصوير تطامن الوجوه إلى الأرض؛ فالذقن أول ما يحاذيها عند الانحناء الشديد للسجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص308، تحت «نكتة إيثار لفظ الأذقان بدلًا من الوجوه»","url":""}]},{"id":"s17-188","number":188,"surah":17,"verses":[109],"references":[{"surah":17,"verses":[109]}],"verseLabel":"الإسراء: 109","question":"ما سر تكرار الخرور في قوله تعالى: ﴿وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ﴾؟","answer":"من توجيهات التكرار أنه خرور واحد أعيد للاهتمام بحالي السجود والبكاء، وهو الوجه المنقول عن ابن عاشور. ويذكر المصدر أيضًا حمله على اختلاف الحالين أو سببهما؛ فالتكرار يبرز عمق التأثر وتعدد مظاهر الخشوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص327، تحت «سر تكرار جملة ويخرون للأذقان»","url":""}]},{"id":"s17-189","number":189,"surah":17,"verses":[110],"references":[{"surah":17,"verses":[110]}],"verseLabel":"الإسراء: 110","question":"ما سر اختصاص اسمي ﴿الله﴾ و﴿الرحمن﴾ بالذكر؟","answer":"ليرد توهم المشركين تعدد المسمى بتعدد الاسم، ويقرر أن الاسمين وسائر الأسماء الحسنى لمسمى واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص340، تحت «سر اختصاص اسم الله واسم الرحمن بالذكر»","url":""}]},{"id":"s17-232","number":232,"surah":17,"verses":[110],"references":[{"surah":17,"verses":[110]}],"verseLabel":"الإسراء: 110","question":"ما سر تكرار ﴿ادعوا﴾ في قوله: ﴿ادعوا الله أو ادعوا الرحمن﴾؟","answer":"يسوّي بين الدعاء بالاسمين ويؤكد صحة التوجه بأي منهما، فلا يتعلق الحكم بلفظ واحد دون الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص342، تحت «سر تكرار ادعوا»","url":""}]},{"id":"s17-190","number":190,"surah":17,"verses":[110],"references":[{"surah":17,"verses":[110]}],"verseLabel":"الإسراء: 110","question":"ما دلالة الجمع بين النهي عن شدة الجهر والنهي عن شدة المخافتة؟","answer":"نُهي عن شدة الجهر حتى لا يثير ذلك المشركين ويزيد تصلبهم، وعن شدة الإسرار حتى يسمع المتهيئون للاهتداء؛ فطُلب طريق وسط يحقق المقصودين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص348، تحت «دلالة النهي في قوله ولا تجهر»","url":""}]},{"id":"s17-191","number":191,"surah":17,"verses":[111],"references":[{"surah":17,"verses":[111]}],"verseLabel":"الإسراء: 111","question":"ما سر افتتاح سورة الإسراء بالتسبيح وختامها بالحمد والتكبير؟","answer":"افتتحت السورة بتسبيح الله عند ذكر تكريم رسوله بالإسراء، وختمت بما يستدعيه ذلك من الحمد والتكبير. فيرد الختام على المطلع، وتنتظم أذكار التنزيه والثناء والتعظيم في أول السورة وآخرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص379، تحت «بلاغة رد العجز على الصدر بين ختام سورة الإسراء ومطلعها»","url":""}]},{"id":"s17-192","number":192,"surah":17,"verses":[111],"references":[{"surah":17,"verses":[111]}],"verseLabel":"الإسراء: 111","question":"ما سر وصف الله بالاسم الموصول في قوله: ﴿الحمد لله الذي لم يتخذ ولدًا﴾؟","answer":"يجعل صفات التنزيه الآتية صلةً معلومة تفسر استحقاقه الحمد الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص369، تحت «سر الوصف باسم الموصول»","url":""}]},{"id":"s17-233","number":233,"surah":17,"verses":[111],"references":[{"surah":17,"verses":[111]}],"verseLabel":"الإسراء: 111","question":"ما سر تقديم نفي الولد على نفي الشريك والولي؟","answer":"بدأ بأشد دعاوى المشركين مساسًا بالتوحيد، ثم أتبعها بنفي المشاركة في الملك ونفي الحاجة إلى النصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص370، تحت «سر تقديم جملة لم يتخذ ولدًا على ما بعدها»","url":""}]},{"id":"s17-234","number":234,"surah":17,"verses":[111],"references":[{"surah":17,"verses":[111]}],"verseLabel":"الإسراء: 111","question":"ما دلالة قيد ﴿من الذل﴾ في نفي الولي؟","answer":"ينفي اتخاذ ولي ينشأ عن ضعف أو احتياج، أما ولاية الله لعباده المؤمنين فهي فضل ورحمة لا افتقارًا إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص376، تحت «فائدة قيد الجار والمجرور من الذل»","url":""}]},{"id":"s17-193","number":193,"surah":17,"verses":[111],"references":[{"surah":17,"verses":[111]}],"verseLabel":"الإسراء: 111","question":"ما سرّ التعبير بـ﴿وَكَبِّرْهُ تَكْبِيرًا﴾؟","answer":"أُكد الأمر بالمصدر للمبالغة في تعظيم الله وتنزيهه عن كل ما لا يليق بكماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص378، تحت «فائدة التعبير بالمصدر والإتيان به من جنس المأمور به»","url":""}]},{"id":"s18-1","number":1,"surah":18,"verses":[1],"references":[{"surah":18,"verses":[1]}],"verseLabel":"الكهف: 1","question":"ما دلالة افتتاح سورة الكهف بالجملة الخبرية ﴿الْحَمْدُ لِلَّهِ﴾؟","answer":"تثبت الجملة الحمد لله ثبوتًا مستقرًا دائمًا، وتؤدي في الوقت نفسه معنى إنشاء الثناء عليه. وافتتاح السورة بها يلفت إلى أن إنزال الكتاب من أعظم النعم التي يستحق الله عليها الحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص399، تحت «بلاغة الجملة الخبرية ودلالتها في قوله ﴿الْحَمْدُ لِلَّهِ﴾»","url":""}]},{"id":"s18-213","number":213,"surah":18,"verses":[1],"references":[{"surah":18,"verses":[1]}],"verseLabel":"الكهف: 1","question":"ما سر تقديم لفظ ﴿الْحَمْدُ﴾ على اسم الله في افتتاح سورة الكهف؟","answer":"قُدِّم الحمد لأن المقام مقام ثناء على نعمة إنزال القرآن، فبدأ بما هو موضع العناية في السياق، ثم ذُكر المستحق له وهو الله جل جلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص400، تحت «بلاغة تقديم لفظ الحمد على الاسم الجليل»","url":""}]},{"id":"s18-214","number":214,"surah":18,"verses":[1],"references":[{"surah":18,"verses":[1]}],"verseLabel":"الكهف: 1","question":"ما دلالة وصف الله بالاسم الموصول في قوله: ﴿الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ﴾؟","answer":"تربط صلة الموصول استحقاق الله للحمد بإنزال الكتاب، فتُعظِّم نعمة القرآن وتذكّر بالمنعم بها، وتبين أن هذه النعمة سبب ظاهر للحمد والثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص401-402، تحت «نكتة التعبير بالموصول في قوله تعالى: ﴿الَّذِي﴾»","url":""}]},{"id":"s18-2","number":2,"surah":18,"verses":[1],"references":[{"surah":18,"verses":[1]}],"verseLabel":"الكهف: 1","question":"ما سرّ التعبير بـ﴿عَلَى عَبْدِهِ﴾ دون «على رسوله»؟","answer":"وصفه بالعبودية تنويهٌ بمنزلته ورفعٌ لقدره بإنزال الكتاب عليه، مع تقرير أنه مهما علت منزلته فهو عبد لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص404، تحت «إيثار لفظ العبودية في قوله عبده»","url":""}]},{"id":"s18-3","number":3,"surah":18,"verses":[1],"references":[{"surah":18,"verses":[1]}],"verseLabel":"الكهف: 1","question":"ما سرّ تقديم نفي العوج في ﴿وَلَمْ يَجْعَلْ لَهُ عِوَجًا﴾ على وصف الكتاب بـ﴿قَيِّمًا﴾؟","answer":"نُفي عنه الخلل والميل أولًا، ثم أُثبت له كمال الاستقامة والاعتدال؛ فجمع سلامته من النقص وثبوت الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص414، تحت «فائدة ذكر قيمًا عقيب قوله ولم يجعل له عوجًا»","url":""}]},{"id":"s18-4","number":4,"surah":18,"verses":[1,2],"references":[{"surah":18,"verses":[1,2]}],"verseLabel":"الكهف: 1-2","question":"ما دلالة الجمع بين نفي العوج ووصف الكتاب بأنه ﴿قَيِّمًا﴾؟","answer":"لأن نفي العوج يثبت خلوه من الخلل والتناقض، ووصفه بالقيم يثبت استقامته وقيامه بمصالح العباد؛ فليس الوصفان تكرارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص415، تحت «دلالة الطباق بين العوج المنفي والقيم المثبت»","url":""}]},{"id":"s18-5","number":5,"surah":18,"verses":[2],"references":[{"surah":18,"verses":[2]}],"verseLabel":"الكهف: 2","question":"ما دلالة وصف البأس بأنه ﴿شَدِيدًا﴾؟","answer":"لتهويل الوعيد وبيان عظم هذا البأس وقوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص419، تحت «نكتة وصف البأس بالشدة»","url":""}]},{"id":"s18-215","number":215,"surah":18,"verses":[2],"references":[{"surah":18,"verses":[2]}],"verseLabel":"الكهف: 2","question":"ما سرّ التعبير بـ﴿مِنْ لَدُنْهُ﴾ في وصف البأس؟","answer":"ليدل على أن البأس صادر من عند الله، ولفظ ﴿لدن﴾ أخص في معنى القرب والصدور من ﴿عند﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص421، تحت «سر إيثار لفظ لدنه»","url":""}]},{"id":"s18-6","number":6,"surah":18,"verses":[2],"references":[{"surah":18,"verses":[2]}],"verseLabel":"الكهف: 2","question":"ما سرّ تقديم الإنذار على البشارة؟","answer":"لأن المقام مقام إنذار المعاندين، ودفع المفسدة مقدّم على جلب المصلحة؛ فكان الإنذار هو الغرض الأهم في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص418، تحت «نكتة تقديم الإنذار على التبشير»","url":""}]},{"id":"s18-7","number":7,"surah":18,"verses":[2],"references":[{"surah":18,"verses":[2]}],"verseLabel":"الكهف: 2","question":"ما دلالة وصف أجر المؤمنين بأنه ﴿حَسَنًا﴾؟","answer":"وصف الأجر بالحسن يجمع ما فيه من البهجة والنفع والخلو من القبح، والمراد به نعيم الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص428، تحت «نكتة وصف الأجر بالحسن في قوله أجرًا حسنًا»","url":""}]},{"id":"s18-8","number":8,"surah":18,"verses":[3],"references":[{"surah":18,"verses":[3]}],"verseLabel":"الكهف: 3","question":"ما سرّ التعبير عن أهل الجنة بأنهم ﴿مَاكِثِينَ فِيهِ﴾؟","answer":"ليدل على استقرارهم وإقامتهم في النعيم من غير انتقال عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص428، تحت «إيثار لفظ ماكثين دون غيره من مرادفاته»","url":""}]},{"id":"s18-216","number":216,"surah":18,"verses":[3],"references":[{"surah":18,"verses":[3]}],"verseLabel":"الكهف: 3","question":"ما دلالة تقييد مكث أهل الجنة بقوله ﴿أَبَدًا﴾؟","answer":"يفيد دوام مكثهم في النعيم بلا انتهاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص430، تحت «فائدة الظرف أبدًا»","url":""}]},{"id":"s18-9","number":9,"surah":18,"verses":[4],"references":[{"surah":18,"verses":[4]}],"verseLabel":"الكهف: 4","question":"ما سر تخصيص القائلين ﴿اتَّخَذَ اللَّهُ وَلَدًا﴾ بإنذار بعد الإنذار العام؟","answer":"للتنبيه على فظاعة هذه المقالة وعظم استحقاقها للوعيد؛ فعُطف الخاص على العام اهتمامًا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص436، تحت «نكتة تخصيص الذين قالوا اتخذ الله ولدًا بالإنذار»","url":""}]},{"id":"s18-10","number":10,"surah":18,"verses":[5],"references":[{"surah":18,"verses":[5]}],"verseLabel":"الكهف: 5","question":"ما سرّ التعبير بـ﴿كَبُرَتْ كَلِمَةً﴾ دون «عظمت»؟","answer":"اختير ﴿كبرت﴾ للدلالة على عظم الذنب وشدة قبح المقالة، وجاءت الصيغة للتعجب من شناعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص447، تحت «إيثار لفظ كبرت على ما يقاربه من ألفاظ»","url":""}]},{"id":"s18-11","number":11,"surah":18,"verses":[5],"references":[{"surah":18,"verses":[5]}],"verseLabel":"الكهف: 5","question":"ما سرّ التعبير بـ﴿تَخْرُجُ مِنْ أَفْوَاهِهِمْ﴾؟","answer":"للدلالة على أنها مقولة لا مصدر لها إلا التلفظ بالأفواه، ولا تقوم على علم أو حقيقة يعقلها العقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص448، تحت «إيثار لفظ تخرج دون ما يقاربه»","url":""}]},{"id":"s18-12","number":12,"surah":18,"verses":[5],"references":[{"surah":18,"verses":[5]}],"verseLabel":"الكهف: 5","question":"ما دلالة حصر قولهم في الكذب بقوله تعالى: ﴿إِنْ يَقُولُونَ إِلَّا كَذِبًا﴾؟","answer":"لنفي كل وصف عن مقالتهم إلا الكذب، مع تأكيد النفي بأسلوب النفي والاستثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص450، تحت «بلاغة القصر في حصر قولهم بالكذب»","url":""}]},{"id":"s18-13","number":13,"surah":18,"verses":[6],"references":[{"surah":18,"verses":[6]}],"verseLabel":"الكهف: 6","question":"ما سرّ التعبير بـ﴿فَلَعَلَّكَ بَاخِعٌ نَفْسَكَ﴾؟","answer":"البخع بلوغ الحزن بالنفس إلى الهلاك؛ والتعبير يصور شدة حرص النبي ﷺ على إيمانهم، وفيه تسلية ونهي عن استهلاك النفس حزنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص456، تحت «سر إيثار باخع على هيئة اسم الفاعل»","url":""}]},{"id":"s18-14","number":14,"surah":18,"verses":[6],"references":[{"surah":18,"verses":[6]}],"verseLabel":"الكهف: 6","question":"ما سرّ إطلاق ﴿هَذَا الْحَدِيثِ﴾ على القرآن؟","answer":"الحديث كلام وخبر، ومن توجيهات إطلاقه على القرآن تجدد نزوله واشتماله على الأخبار والقصص. واسم الإشارة القريب يستحضر وضوحه وحضوره في الأسماع، فيزيد التعجيب من إعراضهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص459، تحت «نكتة إطلاق لفظ الحديث على القرآن»","url":""}]},{"id":"s18-15","number":15,"surah":18,"verses":[7],"references":[{"surah":18,"verses":[7]}],"verseLabel":"الكهف: 7","question":"ما سرّ التعبير بـ﴿زِينَةً لَهَا﴾ دون «زينة لكم»؟","answer":"جُعل ما على الأرض زينةً للأرض نفسها، فيجمع التعبير الامتنان بجمال المخلوقات والتنبيه إلى أنها موضع ابتلاء زائل، لا ملك ثابت للإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص467، تحت «فائدة التقييد بشبه الجملة لها»","url":""}]},{"id":"s18-16","number":16,"surah":18,"verses":[8],"references":[{"surah":18,"verses":[8]}],"verseLabel":"الكهف: 8","question":"ما سرّ التعبير بـ﴿صَعِيدًا جُرُزًا﴾؟","answer":"يصوّر انقلاب زينة الأرض إلى أرض مستوية جافة أجرد لا نبات فيها؛ فتكتمل صورة فناء الحياة وزينتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص475، تحت «إيثار لفظ صعيدًا جرزًا»","url":""}]},{"id":"s18-17","number":17,"surah":18,"verses":[9],"references":[{"surah":18,"verses":[9]}],"verseLabel":"الكهف: 9","question":"ما سرّ التعبير بـ﴿أَمْ حَسِبْتَ﴾ دون «أفظننت»؟","answer":"لأن الحسبان هنا أدنى درجة من الظن وليس اعتقادًا راجحًا؛ فناسب إنكار أدنى توهم أن أصحاب الكهف غاية العجب، كما أن لفظ الحسبان يلائم ما في القصة من حساب مدة لبثهم وعددهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص482، تحت «سر إيثار الحسبان دون الظن»","url":""}]},{"id":"s18-18","number":18,"surah":18,"verses":[9],"references":[{"surah":18,"verses":[9]}],"verseLabel":"الكهف: 9","question":"ما سرّ تقديم ﴿مِنْ آيَاتِنَا﴾ على ﴿عَجَبًا﴾؟","answer":"لأن الأهم نفي أن تكون قصتهم بالقياس إلى آيات الله هي العجب البالغ؛ فقُدّم تعلقها بآيات الله قبل وصفها بالعجب، وفي ذلك ردّ تهويل السائلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص485، تحت «سر تقديم الجار والمجرور على عجبًا»","url":""}]},{"id":"s18-19","number":19,"surah":18,"verses":[9],"references":[{"surah":18,"verses":[9]}],"verseLabel":"الكهف: 9","question":"ما دلالة الجمع بين ﴿الْكَهْفِ وَالرَّقِيمِ﴾ في التعريف بأصحاب القصة؟","answer":"يقترن أصحاب القصة بالكهف الذي لازموه وبالرقيم الذي تعددت الأقوال فيه: فقيل لوح كتب فيه خبرهم، وقيل اسم موضع. ويناقش المصدر أيضًا هل أصحاب الكهف والرقيم طائفة واحدة أم طائفتان؛ لذلك لا يصح الجزم بوجه واحد على أنه المعنى الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص483، 484، تحت «دلالة والرقيم ومعنى العطف»","url":""}]},{"id":"s18-20","number":20,"surah":18,"verses":[10],"references":[{"surah":18,"verses":[10]}],"verseLabel":"الكهف: 10","question":"ما سر إظهار لفظ ﴿الْفِتْيَةُ﴾ بدل الإضمار؟","answer":"للتنبيه على حداثة سنهم وقوة إيمانهم مع الشباب، وفي إظهار الاسم عناية بموضع العبرة في حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص490، 491، تحت «نكتة الإظهار في مقام الإضمار والتعبير بالفتية»","url":""}]},{"id":"s18-21","number":21,"surah":18,"verses":[10],"references":[{"surah":18,"verses":[10]}],"verseLabel":"الكهف: 10","question":"ما دلالة حذف حرف النداء في دعاء الفتية: ﴿رَبَّنَا آتِنَا﴾؟","answer":"حذف حرف النداء يصور قربهم من ربهم واستبطانهم عظمته؛ فلا يحتاجون إلى أداة تنبيه في مناجاته. أما مبادرتهم بالدعاء عقب الإيواء إلى الكهف فتظهرها الفاء في ﴿فَقَالُوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص492، تحت «بلاغة الحذف في ربنا آتنا»","url":""}]},{"id":"s18-22","number":22,"surah":18,"verses":[10],"references":[{"surah":18,"verses":[10]}],"verseLabel":"الكهف: 10","question":"ما سرّ التعبير بـ﴿مِنْ لَدُنْكَ رَحْمَةً﴾؟","answer":"طلبوا رحمة خاصة من عند الله تعظم حاجتهم إليها، وتقديم ﴿مِنْ لَدُنْكَ﴾ يبرز اختصاصها به وقوة رغبتهم فيها. و«لدن» تؤكد صدورها من عنده، مع تنكير الرحمة للتعظيم والتنوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص493، تحت «نكتة إيثار التعبير بلَدُنك على عندك»","url":""}]},{"id":"s18-23","number":23,"surah":18,"verses":[10],"references":[{"surah":18,"verses":[10]}],"verseLabel":"الكهف: 10","question":"ما سرّ تقديم ﴿لَنَا﴾ في ﴿وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا﴾؟","answer":"للاهتمام بحاجتهم إلى المطلوب وإبراز أنه المرغوب لهم قبل بيان الأمر الذي يطلبون تهيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص496، تحت «سر تقديم لنا على من أمرنا»","url":""}]},{"id":"s18-24","number":24,"surah":18,"verses":[11],"references":[{"surah":18,"verses":[11]}],"verseLabel":"الكهف: 11","question":"ما سرّ التعبير بـ﴿فَضَرَبْنَا عَلَى آذَانِهِمْ﴾ بدل «أنمناهم»؟","answer":"هو كناية عن إلقاء نوم ثقيل حُجب معه السمع؛ وخصت الآذان لأن السمع هو الطريق المعتاد لتنبه النائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص501، تحت «بلاغة الكناية في الضرب على الآذان»","url":""}]},{"id":"s18-25","number":25,"surah":18,"verses":[11],"references":[{"surah":18,"verses":[11]}],"verseLabel":"الكهف: 11","question":"ما سرّ التعبير بـ﴿سِنِينَ عَدَدًا﴾؟","answer":"من توجيهات «عددًا» أنه وصف للسنين يفيد كثرتها وطول اللبث، مع إجمال المقدار هنا. ويذكر المصدر أيضًا وجه التقليل بالنظر إلى قدرة الله؛ فالتكثير تفسير معتبر وليس الوجه الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص504، تحت «دلالة التعبير بلفظ عددًا»","url":""}]}]);
